/**
 * Pruning functions for TNA models.
 * Port of Python tna/prune.py + disparity filter (Serrano et al. 2009).
 */
import type { TNA, GroupTNA } from '../core/types.js';
import { isGroupTNA, groupEntries } from '../core/group.js';
import { arrayQuantile } from '../core/matrix.js';

export interface PruneOptions {
  /** Pruning method. Default `'threshold'`, as in R `tna::prune`. */
  method?: 'threshold' | 'lowest' | 'disparity';
  /** Minimum edge weight for the `threshold` method (default 0.1). Edges with
   *  `0 < weight <= threshold` are candidates for removal. */
  threshold?: number;
  /** For the `lowest` method: the PROPORTION of non-zero edges to cut (default 0.05).
   *  The cut-off is `quantile(positive weights, lowest)` — R's `prune(lowest = )`. */
  lowest?: number;
  /**
   * Significance level for the disparity filter. Default 0.5, matching R
   * `tna::prune(method = "disparity", level = )`.
   *
   * R spells this parameter `level`; it is accepted as an alias below so an R script
   * ports across unchanged. (It was `alpha`, default 0.05, until 2026-07-13 — a caller
   * passing R's `level` was silently ignored and got 0.05.)
   */
  alpha?: number;
  /** Alias for `alpha` — R's spelling. */
  level?: number;
}

/** R `tna::prune`'s defaults, in one place so they cannot drift. */
export const PRUNE_DEFAULT_THRESHOLD = 0.1;
export const PRUNE_DEFAULT_LOWEST = 0.05;
export const PRUNE_DEFAULT_LEVEL = 0.5;

/**
 * Prune edges from a TNA model — R `tna::prune`.
 *
 * Accepts either a bare threshold number (backward compatible) or an options object.
 * Three methods, all matching R:
 *   `threshold` (default) — cut edges with `0 < weight <= threshold` (default 0.1)
 *   `lowest`              — cut the lowest `lowest` proportion of non-zero edges,
 *                           i.e. below `quantile(positive weights, lowest)` (default 0.05)
 *   `disparity`           — Serrano et al. 2009 backbone at significance `level` (default 0.5)
 *
 * `threshold` and `lowest` remove edges ONE AT A TIME and keep any edge whose removal
 * would disconnect the graph (R's `is_weakly_connected` guard) — so they differ only in
 * how the cut-off is computed.
 *
 * An unknown method THROWS. It used to fall through to threshold-pruning at the default
 * 0.1, so `{method: 'lowest'}` — which R has and tnaj did not — silently returned a
 * plausible, wrong model instead of erroring. A confidently-returned wrong number is worse
 * than a crash.
 */
export function prune(
  model: TNA | GroupTNA,
  thresholdOrOptions: number | PruneOptions = PRUNE_DEFAULT_THRESHOLD,
): TNA | Record<string, TNA> {
  if (isGroupTNA(model)) {
    const result: Record<string, TNA> = {};
    for (const [name, m] of groupEntries(model)) {
      result[name] = prune(m, thresholdOrOptions) as TNA;
    }
    return result;
  }

  const tnaModel = model as TNA;
  const opts: PruneOptions = typeof thresholdOrOptions === 'number'
    ? { method: 'threshold', threshold: thresholdOrOptions }
    : thresholdOrOptions;

  const method = opts.method ?? 'threshold';

  switch (method) {
    case 'threshold':
      return pruneThreshold(tnaModel, opts.threshold ?? PRUNE_DEFAULT_THRESHOLD);

    case 'lowest': {
      // R: cut_off <- quantile(weights[weights > 0], probs = lowest), then the SAME
      // connectivity-preserving removal loop as `threshold`.
      const pos: number[] = [];
      const n = tnaModel.weights.rows;
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
          const w = tnaModel.weights.get(i, j);
          if (w > 0) pos.push(w);
        }
      }
      if (pos.length === 0) return pruneThreshold(tnaModel, 0);
      const cutOff = arrayQuantile(Float64Array.from(pos), opts.lowest ?? PRUNE_DEFAULT_LOWEST);
      return pruneThreshold(tnaModel, cutOff);
    }

    case 'disparity':
      // `level` is R's spelling of the same parameter; accept both.
      return pruneDisparity(tnaModel, opts.level ?? opts.alpha ?? PRUNE_DEFAULT_LEVEL);

    default:
      throw new Error(
        `prune: unknown method ${JSON.stringify(method)}. ` +
        "Expected 'threshold', 'lowest' or 'disparity'.",
      );
  }
}

/**
 * Threshold pruning matching R's prune_default.
 * Removes edges with weight <= threshold, preserving weak connectivity.
 */
function pruneThreshold(model: TNA, threshold: number): TNA {
  const n = model.weights.rows;
  const weights = model.weights.clone();

  // Collect edges to remove: weight > 0 AND weight <= threshold
  const toRemove: { i: number; j: number; w: number }[] = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const w = weights.get(i, j);
      if (w > 0 && w <= threshold) {
        toRemove.push({ i, j, w });
      }
    }
  }

  // Remove each edge only if graph stays weakly connected
  for (const { i, j } of toRemove) {
    const prev = weights.get(i, j);
    weights.set(i, j, 0);
    if (!isWeaklyConnected(weights, n)) {
      weights.set(i, j, prev); // restore
    }
  }

  return {
    weights,
    inits: new Float64Array(model.inits),
    labels: [...model.labels],
    data: model.data,
    type: model.type,
    scaling: [...model.scaling],
  };
}

/** Check if a directed graph is weakly connected (all nodes reachable ignoring edge direction). */
function isWeaklyConnected(weights: import('../core/matrix.js').Matrix, n: number): boolean {
  if (n <= 1) return true;
  const visited = new Uint8Array(n);
  const stack = [0];
  visited[0] = 1;
  let count = 1;

  while (stack.length > 0) {
    const u = stack.pop()!;
    for (let v = 0; v < n; v++) {
      if (!visited[v] && (weights.get(u, v) > 0 || weights.get(v, u) > 0)) {
        visited[v] = 1;
        count++;
        stack.push(v);
      }
    }
  }
  return count === n;
}

/**
 * Disparity filter backbone extraction (Serrano et al. 2009).
 * Matches R tna::prune(method="disparity") which uses both out-degree and
 * in-degree p-values, taking pmin. Self-loops are always removed.
 */
export function pruneDisparity(model: TNA, alpha = PRUNE_DEFAULT_LEVEL): TNA {
  const n = model.weights.rows;
  const mat = model.weights;

  // Out-degree disparity: p_out[i][j] = (1 - w[i][j]/rowSum[i])^(outDeg[i]-1)
  const outStrength = new Float64Array(n);
  const outDegree = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (mat.get(i, j) > 0) { outStrength[i]! += mat.get(i, j); outDegree[i]!++; }
    }
  }

  // In-degree disparity: p_in[i][j] = (1 - w[i][j]/colSum[j])^(inDeg[j]-1)
  const inStrength = new Float64Array(n);
  const inDegree = new Float64Array(n);
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      if (mat.get(i, j) > 0) { inStrength[j]! += mat.get(i, j); inDegree[j]!++; }
    }
  }

  // Compute significance: edge kept if pmin(out_p, in_p) < alpha
  const weights = mat.clone();
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) { weights.set(i, j, 0); continue; } // diagonal always 0
      const w = mat.get(i, j);
      if (w <= 0) continue;

      const outP = outStrength[i]! > 0
        ? Math.pow(1 - w / outStrength[i]!, Math.max(outDegree[i]! - 1, 0))
        : 1;
      const inP = inStrength[j]! > 0
        ? Math.pow(1 - w / inStrength[j]!, Math.max(inDegree[j]! - 1, 0))
        : 1;
      const pValue = Math.min(outP, inP);

      if (pValue >= alpha) {
        weights.set(i, j, 0);
      }
    }
  }

  return {
    weights,
    inits: new Float64Array(model.inits),
    labels: [...model.labels],
    data: model.data,
    type: model.type,
    scaling: [...model.scaling],
  };
}
