/**
 * pathways — port of Nestimate::pathways generic dispatcher (R/pathways.R, 0.5.1).
 *
 * Extracts higher-order pathway strings in `"A B -> C"` format from
 * net_hon / net_hypa / net_mogen objects, suitable for downstream
 * simplicial-complex visualisation (cograph::plot_simplicial).
 */
import type { HonResult } from './hon.js';
import type { HypaResult } from './hypa.js';
import type { MogenResult } from './mogen.js';
import { mogenTransitions } from './mogen.js';

export interface PathwaysHonOptions {
  minCount?: number;     // default 1
  minProb?: number;      // default 0
  top?: number;          // default undefined (= all)
  order?: number;        // optional — pin to specific from_order
}

export interface PathwaysHypaOptions {
  type?: 'all' | 'over' | 'under'; // default "all"
}

export interface PathwaysMogenOptions {
  order?: number;        // default optimalOrder
  minCount?: number;     // default 1
  minProb?: number;      // default 0
  top?: number;
}

/** Convert "A -> B -> C" → "A B -> C" (cograph plot_simplicial format). */
function arrowToSimplicial(path: string): string {
  const parts = path.split('->').map(s => s.trim());
  if (parts.length < 2) return path;
  const sources = parts.slice(0, -1).join(' ');
  const target = parts[parts.length - 1]!;
  return `${sources} -> ${target}`;
}

/* ── pathways.net_hon ────────────────────────────────────────────── */

export function pathwaysHon(hon: HonResult, options: PathwaysHonOptions = {}): string[] {
  const { minCount = 1, minProb = 0, top, order } = options;
  let edges = hon.edges.filter(e => e.fromOrder > 1);
  if (order !== undefined) edges = edges.filter(e => e.fromOrder === order);
  if (minCount > 1) edges = edges.filter(e => e.count >= minCount);
  if (minProb > 0) edges = edges.filter(e => e.probability >= minProb);
  edges.sort((a, b) => b.count - a.count);
  if (top !== undefined && edges.length > top) edges = edges.slice(0, top);
  return edges.map(e => arrowToSimplicial(e.path));
}

/* ── pathways.net_hypa ───────────────────────────────────────────── */

export function pathwaysHypa(hypa: HypaResult, options: PathwaysHypaOptions = {}): string[] {
  const type = options.type ?? 'all';
  let rows: { path: string; ratio: number; anomaly: string }[];
  if (type === 'all') {
    rows = hypa.scores.filter(s => s.anomaly === 'over' || s.anomaly === 'under');
  } else {
    rows = hypa.scores.filter(s => s.anomaly === type);
  }
  // R rbinds over (already ratio-desc) and under (already ratio-asc) in the
  // pre-sorted `scores`. Match that ordering: over by ratio desc, then under
  // by ratio asc.
  if (type === 'all') {
    const over = rows.filter(r => r.anomaly === 'over').sort((a, b) => b.ratio - a.ratio);
    const under = rows.filter(r => r.anomaly === 'under').sort((a, b) => a.ratio - b.ratio);
    rows = [...over, ...under];
  } else if (type === 'over') {
    rows.sort((a, b) => b.ratio - a.ratio);
  } else {
    rows.sort((a, b) => a.ratio - b.ratio);
  }
  return rows.map(r => arrowToSimplicial(r.path));
}

/* ── pathways.net_mogen ──────────────────────────────────────────── */

export function pathwaysMogen(mogen: MogenResult, options: PathwaysMogenOptions = {}): string[] {
  const order = options.order ?? mogen.optimalOrder;
  const { minCount = 1, minProb = 0, top } = options;
  if (order < 1) return [];
  let trans = mogenTransitions(mogen, { order, minCount });
  if (minProb > 0) trans = trans.filter(t => t.probability >= minProb);
  trans.sort((a, b) => b.count - a.count);
  if (top !== undefined && trans.length > top) trans = trans.slice(0, top);
  return trans.map(t => arrowToSimplicial(t.path));
}
