/**
 * HONEM — port of Nestimate::build_honem (R/honem.R, 0.5.1).
 *
 * Higher-Order Network Embeddings via direct matrix factorization
 * (Saebi et al. 2020). No random walks or skip-gram — uses
 * exponentially-decaying powers of the transition matrix and truncated SVD.
 *
 *   D = row-normalized HON transition matrix
 *   S = (1/Z) * sum_{k=0..L} exp(-k) * D^{k+1},  Z = sum exp(-k)
 *   S = U * diag(sigma) * V^T  (truncated to top `dim` components)
 *   embeddings = U[, 1:dim] * diag(sqrt(sigma[1:dim]))
 *
 * Singular vectors are sign-ambiguous; the equivalence test compares
 * |embedding| element-wise (and singular values exactly), which is the
 * only invariant component of the result.
 */
import { Matrix } from '../core/matrix.js';
import type { HonResult } from './hon.js';

export type HonemInput = HonResult | Matrix;

export interface HonemOptions {
  dim?: number;        // default 32
  maxPower?: number;   // default 10
}

export interface HonemResult {
  embeddings: Matrix;          // (n × dim)
  nodes: string[];             // row labels
  singularValues: Float64Array;
  explainedVariance: number;
  dim: number;
  maxPower: number;
  nNodes: number;
}

/* ── SVD via Jacobi eigen-decomposition of S^T S ──────────────────── */

/**
 * Jacobi eigenvalue iteration for an n×n symmetric matrix. Returns
 * eigenvalues (length n) and orthogonal eigenvector matrix V (columns
 * are eigenvectors). O(n^3 · iterations) — fine for n ≤ ~100.
 */
function jacobiSymmetricEigen(A: Matrix, maxSweeps = 100, tol = 1e-14): {
  values: Float64Array; vectors: Matrix;
} {
  const n = A.rows;
  if (n !== A.cols) throw new Error('jacobiSymmetricEigen: A must be square');
  // Copy A to a working buffer (row-major flat).
  const a = new Float64Array(n * n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) a[i * n + j] = A.get(i, j);
  }
  const V = new Float64Array(n * n);
  for (let i = 0; i < n; i++) V[i * n + i] = 1;

  for (let sweep = 0; sweep < maxSweeps; sweep++) {
    // Sum of squared off-diagonals.
    let off = 0;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const v = a[i * n + j]!;
        off += v * v;
      }
    }
    if (off < tol) break;

    for (let p = 0; p < n - 1; p++) {
      for (let q = p + 1; q < n; q++) {
        const apq = a[p * n + q]!;
        if (Math.abs(apq) < 1e-300) continue;
        const app = a[p * n + p]!;
        const aqq = a[q * n + q]!;
        // Rotation that zeroes out a[p,q].
        const theta = (aqq - app) / (2 * apq);
        let t: number;
        if (!Number.isFinite(theta) || Math.abs(theta) > 1e15) {
          t = 0.5 / theta;
        } else {
          t = (theta >= 0 ? 1 : -1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
        }
        const c = 1 / Math.sqrt(t * t + 1);
        const s = t * c;

        // Update diagonal.
        a[p * n + p] = app - t * apq;
        a[q * n + q] = aqq + t * apq;
        a[p * n + q] = 0;
        a[q * n + p] = 0;

        // Update other rows/cols.
        for (let i = 0; i < n; i++) {
          if (i === p || i === q) continue;
          const aip = a[i * n + p]!;
          const aiq = a[i * n + q]!;
          a[i * n + p] = c * aip - s * aiq;
          a[p * n + i] = a[i * n + p]!;
          a[i * n + q] = s * aip + c * aiq;
          a[q * n + i] = a[i * n + q]!;
        }

        // Accumulate rotation in V.
        for (let i = 0; i < n; i++) {
          const vip = V[i * n + p]!;
          const viq = V[i * n + q]!;
          V[i * n + p] = c * vip - s * viq;
          V[i * n + q] = s * vip + c * viq;
        }
      }
    }
  }

  const values = new Float64Array(n);
  for (let i = 0; i < n; i++) values[i] = a[i * n + i]!;
  const vectors = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) vectors.set(i, j, V[i * n + j]!);
  }
  return { values, vectors };
}

/** Square SVD via S^T S eigendecomposition. Returns U, sigma (sorted
 *  descending), V such that S ≈ U diag(sigma) V^T. Singular vectors are
 *  sign-ambiguous in general. */
function svdSquare(S: Matrix): { u: Matrix; sigma: Float64Array; v: Matrix } {
  const n = S.rows;
  if (n !== S.cols) throw new Error('svdSquare: S must be square');
  // B = S^T S
  const B = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let acc = 0;
      for (let k = 0; k < n; k++) acc += S.get(k, i) * S.get(k, j);
      B.set(i, j, acc);
    }
  }
  const { values, vectors } = jacobiSymmetricEigen(B);
  // Sort descending by eigenvalue.
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => values[b]! - values[a]!);

  const sigma = new Float64Array(n);
  const v = new Matrix(n, n);
  for (let j = 0; j < n; j++) {
    const oj = order[j]!;
    sigma[j] = Math.sqrt(Math.max(0, values[oj]!));
    for (let i = 0; i < n; i++) v.set(i, j, vectors.get(i, oj));
  }
  // U = S V Σ^{-1}
  const u = new Matrix(n, n);
  for (let j = 0; j < n; j++) {
    if (sigma[j]! === 0) continue;
    const inv = 1 / sigma[j]!;
    for (let i = 0; i < n; i++) {
      let acc = 0;
      for (let k = 0; k < n; k++) acc += S.get(i, k) * v.get(k, j);
      u.set(i, j, acc * inv);
    }
  }
  return { u, sigma, v };
}

/* ── HONEM core ───────────────────────────────────────────────────── */

function rowNormalize(mat: Matrix): Matrix {
  const out = new Matrix(mat.rows, mat.cols);
  for (let i = 0; i < mat.rows; i++) {
    let row = 0;
    for (let j = 0; j < mat.cols; j++) row += mat.get(i, j);
    if (row > 0) {
      for (let j = 0; j < mat.cols; j++) out.set(i, j, mat.get(i, j) / row);
    }
  }
  return out;
}

function matMul(a: Matrix, b: Matrix): Matrix {
  if (a.cols !== b.rows) throw new Error('matMul: shape mismatch');
  const out = new Matrix(a.rows, b.cols);
  for (let i = 0; i < a.rows; i++) {
    for (let k = 0; k < a.cols; k++) {
      const aik = a.get(i, k);
      if (aik === 0) continue;
      for (let j = 0; j < b.cols; j++) out.set(i, j, out.get(i, j) + aik * b.get(k, j));
    }
  }
  return out;
}

/** S = (1/Z) * sum_{k=0..L} exp(-k) * D^{k+1}. */
function honemNeighborhood(D: Matrix, maxPower: number): Matrix {
  const n = D.rows;
  const weights = new Float64Array(maxPower + 1);
  let Z = 0;
  for (let k = 0; k <= maxPower; k++) { weights[k] = Math.exp(-k); Z += weights[k]!; }
  let Dpow: Matrix = D; // D^1
  const S = new Matrix(n, n);
  for (let k = 0; k <= maxPower; k++) {
    const w = weights[k]!;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        S.set(i, j, S.get(i, j) + w * Dpow.get(i, j));
      }
    }
    if (k < maxPower) Dpow = matMul(Dpow, D); // bump to D^{k+2}
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) S.set(i, j, S.get(i, j) / Z);
  }
  return S;
}

/* ── Public entry point ──────────────────────────────────────────── */

export function buildHonem(hon: HonemInput, options: HonemOptions = {}): HonemResult {
  let dim = options.dim ?? 32;
  const maxPower = options.maxPower ?? 10;
  if (!(dim >= 1)) throw new Error("'dim' must be >= 1");
  if (!(maxPower >= 1)) throw new Error("'maxPower' must be >= 1");

  let mat: Matrix;
  let nodes: string[];
  if (hon instanceof Matrix) {
    mat = hon;
    nodes = Array.from({ length: mat.rows }, (_, i) => `node_${i + 1}`);
  } else {
    mat = hon.matrix;
    nodes = [...hon.nodes];
  }

  const n = mat.rows;
  if (n < 2) throw new Error('Need at least 2 nodes for embedding');
  if (n !== mat.cols) throw new Error("'hon' adjacency matrix must be square");

  dim = Math.min(dim, n - 1);

  const D = rowNormalize(mat);
  const S = honemNeighborhood(D, maxPower);
  const { u, sigma } = svdSquare(S);

  // embeddings = U[, 1:dim] * diag(sqrt(sigma[1:dim]))
  const embeddings = new Matrix(n, dim);
  for (let j = 0; j < dim; j++) {
    const sqrtS = Math.sqrt(Math.max(0, sigma[j]!));
    for (let i = 0; i < n; i++) embeddings.set(i, j, u.get(i, j) * sqrtS);
  }
  // Total variance is sum sigma^2 across all components.
  let totalVar = 0;
  for (let j = 0; j < n; j++) totalVar += sigma[j]! * sigma[j]!;
  let explained = 0;
  for (let j = 0; j < dim; j++) explained += sigma[j]! * sigma[j]!;
  const explainedVariance = totalVar > 0 ? explained / totalVar : 0;

  // Truncated singular values (length dim)
  const singularValues = new Float64Array(dim);
  for (let j = 0; j < dim; j++) singularValues[j] = sigma[j]!;

  return {
    embeddings,
    nodes,
    singularValues,
    explainedVariance,
    dim,
    maxPower,
    nNodes: n,
  };
}
