/**
 * Path Dependence — port of Nestimate::path_dependence (R/path_dependence.R, 0.5.1).
 *
 * Diagnoses where a chain's order-1 Markov assumption fails by comparing,
 * for each order-k context, the empirical next-state distribution
 * P(next | full context) against the order-1 prediction P(next | last state).
 * Returns per-context KL, entropy drop, modal-flip flag, plus chain-level
 * count-weighted aggregates.
 *
 * Input is a wide sequence data.frame / matrix in R (rows = trajectories,
 * cols = time steps). In tnaj that maps directly to `SequenceData` —
 * `(string | null)[][]` — so callers pass that without conversion.
 */
import type { SequenceData } from '../core/types.js';

const HON_SEP = '\x01';

export type PathDependenceInput = SequenceData | string[][];

export interface PathDependenceOptions {
  order?: number;       // default 2 — context length
  minCount?: number;    // default 5
  base?: number;        // default 2 (bits)
}

export interface PathDependenceContextRow {
  context: string;          // arrow-notation k-state context
  n: number;
  hOrder1: number;
  hOrderK: number;
  hDrop: number;            // hOrder1 − hOrderK
  kl: number;               // KL(P_k || P_1) (Infinity if any P_k(t) > 0 has P_1(t) = 0)
  topO1: string;            // most likely next state under order-1
  topOk: string;            // most likely next state under order-k
  flips: boolean;           // topO1 !== topOk
}

export interface PathDependenceResult {
  contexts: PathDependenceContextRow[];   // sorted by kl descending
  chain: {
    klWeighted: number;
    hDropWeighted: number;
    nContexts: number;
    nFlips: number;
  };
  order: number;
  base: number;
  minCount: number;
  states: string[];
}

/* ── helpers ─────────────────────────────────────────────────────── */

/** Match R's behavior: null/undefined become the literal token "NA" so
 *  windows containing them are detectable via substring match. */
function cellAsR(v: string | null | undefined): string {
  return v === null || v === undefined ? 'NA' : v;
}

/** Slide a k-wide window across columns, pool all rows, drop windows that
 *  contain the literal "NA" substring (matches R's `grepl("NA", ...)`). */
function pdKgramCounts(data: PathDependenceInput, k: number): Map<string, number> {
  if (data.length === 0) return new Map();
  const ncols = data.reduce((m, row) => Math.max(m, row.length), 0);
  if (ncols < k) {
    throw new Error(
      `Sequences too short for order ${k - 1} (need >=${k} columns, got ${ncols}).`,
    );
  }
  const counts = new Map<string, number>();
  for (let t = 0; t + k <= ncols; t++) {
    for (const row of data) {
      const parts: string[] = new Array(k);
      let hasNA = false;
      for (let j = 0; j < k; j++) {
        const cell = cellAsR(row[t + j] as string | null | undefined);
        if (cell === 'NA') { hasNA = true; break; }
        parts[j] = cell;
      }
      if (hasNA) continue;
      const key = parts.join(HON_SEP);
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }
  return counts;
}

/** Split each k-gram key into context (first k-1) and next_state (last). */
function pdSplitKgram(name: string, k: number): { context: string; nextState: string } {
  const parts = name.split(HON_SEP);
  const context = parts.slice(0, k - 1).join(' -> ');
  const nextState = parts[k - 1]!;
  return { context, nextState };
}

/** KL(p || q) in given log base. Returns +Infinity if any p[i] > 0 has q[i] = 0. */
function pdKl(p: Float64Array, q: Float64Array, base: number): number {
  const logBase = Math.log(base);
  let acc = 0;
  for (let i = 0; i < p.length; i++) {
    const pi = p[i]!;
    if (pi <= 0) continue;
    const qi = q[i]!;
    if (qi === 0) return Infinity;
    acc += pi * (Math.log(pi / qi) / logBase);
  }
  return acc;
}

/** Shannon entropy in given log base. 0 log 0 := 0. */
function pdEntropy(p: Float64Array, base: number): number {
  const logBase = Math.log(base);
  let acc = 0;
  for (let i = 0; i < p.length; i++) {
    const pi = p[i]!;
    if (pi > 0) acc -= pi * (Math.log(pi) / logBase);
  }
  return acc;
}

function argmax(p: Float64Array): number {
  let best = 0;
  let bestV = p[0]!;
  for (let i = 1; i < p.length; i++) {
    if (p[i]! > bestV) { bestV = p[i]!; best = i; }
  }
  return best;
}

/* ── main ────────────────────────────────────────────────────────── */

export function pathDependence(
  data: PathDependenceInput,
  options: PathDependenceOptions = {},
): PathDependenceResult {
  const order = options.order ?? 2;
  const minCount = options.minCount ?? 5;
  const base = options.base ?? 2;
  if (!(order >= 2)) throw new Error("'order' must be >= 2");
  if (!(minCount >= 1)) throw new Error("'minCount' must be >= 1");
  if (!(base > 0 && base !== 1 && Number.isFinite(base))) {
    throw new Error("'base' must be a finite positive number != 1");
  }

  // Counts at order k (full context + next state) and at order 1.
  const cK = pdKgramCounts(data, order + 1);
  const c1 = pdKgramCounts(data, 2);

  if (cK.size === 0) {
    throw new Error(`No complete order-${order} contexts found in data.`);
  }

  // Collect the global state inventory from order-1 keys (matches R's
  // `sort(unique(c(parts1$context, parts1$next_state)))`).
  const stateSet = new Set<string>();
  for (const key of c1.keys()) {
    const parts = key.split(HON_SEP);
    stateSet.add(parts[0]!);
    stateSet.add(parts[1]!);
  }
  const states = [...stateSet].sort();
  const nStates = states.length;
  const stateIdx = new Map<string, number>();
  states.forEach((s, i) => stateIdx.set(s, i));

  // Order-1 conditional table P_1(next | last). Build a (states × states)
  // matrix where p1Cache[lastIdx][nextIdx] = P_1(next | last).
  const o1Rows = new Map<string, Map<string, number>>();      // last → (next → count)
  const o1Totals = new Map<string, number>();
  for (const [key, c] of c1) {
    const { context, nextState } = pdSplitKgram(key, 2);
    let row = o1Rows.get(context);
    if (!row) { row = new Map(); o1Rows.set(context, row); }
    row.set(nextState, (row.get(nextState) ?? 0) + c);
    o1Totals.set(context, (o1Totals.get(context) ?? 0) + c);
  }
  const p1Cache: Float64Array[] = [];
  for (const last of states) {
    const arr = new Float64Array(nStates);
    const row = o1Rows.get(last);
    const total = o1Totals.get(last);
    if (row && total) {
      for (const [nxt, c] of row) {
        const j = stateIdx.get(nxt);
        if (j !== undefined) arr[j] = c / total;
      }
    }
    p1Cache.push(arr);
  }

  // Order-k conditional table.
  // For each context (first `order` states), accumulate count and
  // build per-context (next → count) table; track last_state.
  interface OkContext {
    context: string;
    lastState: string;
    counts: Map<string, number>;
    total: number;
  }
  const okByContext = new Map<string, OkContext>();
  for (const [key, c] of cK) {
    const parts = key.split(HON_SEP);
    const context = parts.slice(0, order).join(' -> ');
    const nextState = parts[order]!;
    const lastState = parts[order - 1]!;
    let entry = okByContext.get(context);
    if (!entry) {
      entry = { context, lastState, counts: new Map(), total: 0 };
      okByContext.set(context, entry);
    }
    entry.counts.set(nextState, (entry.counts.get(nextState) ?? 0) + c);
    entry.total += c;
  }

  // Aggregate per context, dropping low-count contexts.
  const rows: PathDependenceContextRow[] = [];
  for (const ctx of okByContext.values()) {
    if (ctx.total < minCount) continue;
    const pK = new Float64Array(nStates);
    for (const [nxt, c] of ctx.counts) {
      const j = stateIdx.get(nxt);
      if (j !== undefined) pK[j] = c / ctx.total;
    }
    const lastIdx = stateIdx.get(ctx.lastState);
    const p1 = lastIdx !== undefined ? p1Cache[lastIdx]! : new Float64Array(nStates);
    const h1 = pdEntropy(p1, base);
    const hk = pdEntropy(pK, base);
    const kl = pdKl(pK, p1, base);
    const topO1 = states[argmax(p1)]!;
    const topOk = states[argmax(pK)]!;
    rows.push({
      context: ctx.context,
      n: ctx.total,
      hOrder1: h1,
      hOrderK: hk,
      hDrop: h1 - hk,
      kl,
      topO1,
      topOk,
      flips: topO1 !== topOk,
    });
  }
  // Sort by KL desc — match R's `order(-KL)`. Treat +Inf as largest.
  rows.sort((a, b) => {
    const ak = Number.isFinite(a.kl) ? a.kl : Infinity;
    const bk = Number.isFinite(b.kl) ? b.kl : Infinity;
    return bk - ak;
  });

  // Chain-level: count-weighted average across contexts with finite KL.
  let totalN = 0;
  let klSum = 0;
  let hDropSum = 0;
  let nFlips = 0;
  for (const r of rows) {
    if (r.flips) nFlips++;
    if (Number.isFinite(r.kl)) {
      totalN += r.n;
      klSum += r.kl * r.n;
      hDropSum += r.hDrop * r.n;
    }
  }
  const klWeighted = totalN > 0 ? klSum / totalN : 0;
  const hDropWeighted = totalN > 0 ? hDropSum / totalN : 0;

  return {
    contexts: rows,
    chain: {
      klWeighted,
      hDropWeighted,
      nContexts: rows.length,
      nFlips,
    },
    order,
    base,
    minCount,
    states,
  };
}
