/**
 * Hypergraph suite — ports of Nestimate hypergraph functions.
 *
 *   - buildHypergraph     ← Nestimate::build_hypergraph (R/hypergraph.R:89)
 *   - bipartiteGroups     ← Nestimate::bipartite_groups (R/bipartite_groups.R:75)
 *   - cliqueExpansion     ← Nestimate::clique_expansion (R/clique_expansion.R:63)
 *   - hypergraphMeasures  ← Nestimate::hypergraph_measures (R/hypergraph_measures.R:96)
 *   - hypergraphCentrality ← Nestimate::hypergraph_centrality (R/hypergraph_centrality.R:81)
 *
 * Verified against Nestimate ≥ 0.5.7.
 *
 * The hypergraph object is a binary incidence matrix `B` (n_nodes × n_hyperedges)
 * plus the hyperedge list for convenience. Most measures are direct BLAS ops
 * (BBᵀ for co-degree, BᵀB for pairwise overlap). Centralities reuse the same
 * matrix; the three variants (CEC, Z, H) are power-iteration on the
 * incidence-derived operator.
 */
import { Matrix } from '../core/matrix.js';
import { SeededRNG } from '../core/rng.js';
import { buildSimplicial, type SimplicialInput, type SimplicialComplex } from './simplicial.js';

/* ── data shape ───────────────────────────────────────────────────── */

export interface Hypergraph {
  /** List of hyperedges; each hyperedge is the sorted 0-based vertex indices it spans. */
  hyperedges: number[][];
  /** n_nodes × n_hyperedges binary (or weighted, for bipartiteGroups with `weight`) incidence matrix. */
  incidence: Matrix;
  nodes: string[];
  nNodes: number;
  nHyperedges: number;
  /** Counts of hyperedges of each size, indexed by size (size_2, size_3, ...). */
  sizeDistribution: Record<string, number>;
  /** Recorded construction parameters (for traceability). */
  params: Record<string, unknown>;
}

/* ── buildHypergraph ─────────────────────────────────────────────── */

export interface BuildHypergraphOptions {
  /** Bernoulli probability that each k-clique with k ≥ 3 becomes a k-hyperedge. Default 1. */
  p?: number;
  /** Enumeration method. Only 'clique' is implemented (matches R 0.5.7). */
  method?: 'clique';
  /** Include the underlying 2-edges as 2-hyperedges. Default true. */
  includePairwise?: boolean;
  /** Maximum hyperedge size. Default 3. */
  maxSize?: number;
  /** Edge weight cutoff used to binarise the adjacency. Default 0. */
  threshold?: number;
  /** Seed for the Bernoulli sampling when 0 < p < 1. Default 42 (reproducible). */
  seed?: number;
  /** Optional node labels (used when input is a raw matrix). */
  labels?: string[];
}

export function buildHypergraph(
  net: SimplicialInput | SimplicialComplex,
  options: BuildHypergraphOptions = {},
): Hypergraph {
  const {
    p = 1, method = 'clique', includePairwise = true,
    maxSize = 3, threshold = 0, seed = 42, labels,
  } = options;
  if (method !== 'clique') throw new Error(`buildHypergraph: method='${method}' not implemented`);
  if (!(p >= 0 && p <= 1)) throw new Error('buildHypergraph: p must be in [0, 1]');
  if (!Number.isInteger(maxSize) || maxSize < 2) throw new Error('buildHypergraph: maxSize must be an integer ≥ 2');

  // Use buildSimplicial to enumerate all cliques up to maxSize (dim = maxSize - 1).
  // simplicial-complex input is short-circuited via its existing simplices list.
  let simplices: number[][];
  let nodes: string[];
  if ((net as SimplicialComplex).simplices !== undefined && (net as SimplicialComplex).nodes !== undefined) {
    const sc = net as SimplicialComplex;
    simplices = sc.simplices.map(s => s.slice());
    nodes = sc.nodes.slice();
  } else {
    const sc = buildSimplicial(net as SimplicialInput, {
      type: 'clique', threshold, maxDim: maxSize - 1, labels,
    });
    simplices = sc.simplices.map(s => s.slice());
    nodes = sc.nodes.slice();
  }

  const sizes = simplices.map(s => s.length);
  const edges2 = simplices.filter((_, i) => sizes[i] === 2);
  const hiSimps = simplices.filter((_, i) => sizes[i]! >= 3 && sizes[i]! <= maxSize);

  // Bernoulli sampling on higher-order simplices.
  let sampledHi: number[][];
  if (hiSimps.length === 0 || p <= 0) {
    sampledHi = [];
  } else if (p >= 1) {
    sampledHi = hiSimps;
  } else {
    const rng = new SeededRNG(seed);
    sampledHi = hiSimps.filter(() => rng.random() < p);
  }

  const hyperedges = includePairwise ? edges2.concat(sampledHi) : sampledHi;
  const m = hyperedges.length;
  const n = nodes.length;
  const incidence = new Matrix(n, m);
  for (let j = 0; j < m; j++) {
    for (const v of hyperedges[j]!) incidence.set(v, j, 1);
  }

  // Size distribution.
  const sizeDistribution: Record<string, number> = {};
  for (const he of hyperedges) {
    const k = he.length;
    const key = `size_${k}`;
    sizeDistribution[key] = (sizeDistribution[key] ?? 0) + 1;
  }

  return {
    hyperedges, incidence, nodes, nNodes: n, nHyperedges: m,
    sizeDistribution,
    params: { method, p, includePairwise, maxSize, threshold, seed },
  };
}

/* ── bipartiteGroups ─────────────────────────────────────────────── */

export interface BipartiteGroupsOptions {
  /** Optional column index/name in `data` for per-(player, group) weights. */
  weight?: string;
}

/** Tiny long-format row shape — a record with `player` and `group` (and
 *  optional weight) field names matching the option-passed keys. */
export type BipartiteRow = Record<string, string | number | null | undefined>;

export function bipartiteGroups(
  data: BipartiteRow[],
  player: string,
  group: string,
  options: BipartiteGroupsOptions = {},
): Hypergraph {
  const { weight } = options;
  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('bipartiteGroups: data must be a non-empty array');
  }
  // Drop NA rows on (player, group, weight?).
  const rows = data.filter(r =>
    r[player] != null && r[player] !== '' &&
    r[group]  != null && r[group]  !== '' &&
    (!weight || (r[weight] != null && r[weight] !== '')),
  );
  if (rows.length === 0) {
    throw new Error('bipartiteGroups: no complete observations after dropping NAs');
  }

  const playerVals = rows.map(r => String(r[player]));
  const groupVals = rows.map(r => String(r[group]));
  const playerLevels = Array.from(new Set(playerVals)).sort();
  const groupLevels = Array.from(new Set(groupVals)).sort();
  const playerIdx = new Map(playerLevels.map((v, i) => [v, i]));
  const groupIdx = new Map(groupLevels.map((v, i) => [v, i]));

  const nP = playerLevels.length;
  const nG = groupLevels.length;
  const inc = new Matrix(nP, nG);
  if (!weight) {
    for (let i = 0; i < rows.length; i++) {
      const pi = playerIdx.get(playerVals[i]!)!;
      const gj = groupIdx.get(groupVals[i]!)!;
      if (inc.get(pi, gj) === 0) inc.set(pi, gj, 1);
    }
  } else {
    for (let i = 0; i < rows.length; i++) {
      const pi = playerIdx.get(playerVals[i]!)!;
      const gj = groupIdx.get(groupVals[i]!)!;
      const w = Number(rows[i]![weight]);
      inc.set(pi, gj, inc.get(pi, gj) + (Number.isFinite(w) ? w : 0));
    }
  }

  // Drop hyperedges (groups) that ended up empty (e.g. all-zero weight).
  const keep: number[] = [];
  for (let j = 0; j < nG; j++) {
    let any = false;
    for (let i = 0; i < nP; i++) if (inc.get(i, j) > 0) { any = true; break; }
    if (any) keep.push(j);
  }
  const trimmedNG = keep.length;
  const trimmedInc = new Matrix(nP, trimmedNG);
  const trimmedGroups: string[] = [];
  for (let nj = 0; nj < trimmedNG; nj++) {
    const oj = keep[nj]!;
    trimmedGroups.push(groupLevels[oj]!);
    for (let i = 0; i < nP; i++) trimmedInc.set(i, nj, inc.get(i, oj));
  }

  const hyperedges: number[][] = [];
  for (let j = 0; j < trimmedNG; j++) {
    const he: number[] = [];
    for (let i = 0; i < nP; i++) if (trimmedInc.get(i, j) > 0) he.push(i);
    hyperedges.push(he);
  }

  const sizeDistribution: Record<string, number> = {};
  for (const he of hyperedges) {
    const k = he.length;
    const key = `size_${k}`;
    sizeDistribution[key] = (sizeDistribution[key] ?? 0) + 1;
  }

  return {
    hyperedges, incidence: trimmedInc, nodes: playerLevels,
    nNodes: nP, nHyperedges: trimmedNG,
    sizeDistribution,
    params: {
      source: 'bipartiteGroups', player, group,
      weight: weight ?? null, nObservations: rows.length,
    },
  };
}

/* ── cliqueExpansion ─────────────────────────────────────────────── */

export interface CliqueExpansionOptions {
  /** Use raw incidence values (default). When false, binarise first. */
  weighted?: boolean;
}

export interface CliqueExpansionResult {
  /** n × n symmetric weight matrix W[i, j] = Σ_e B[i, e] · B[j, e] (with W[i, i] = 0). */
  weights: Matrix;
  nodes: string[];
  /** Construction trace. */
  params: Record<string, unknown>;
}

export function cliqueExpansion(hg: Hypergraph, options: CliqueExpansionOptions = {}): CliqueExpansionResult {
  const { weighted = true } = options;
  const n = hg.nNodes;
  const m = hg.nHyperedges;
  const W = new Matrix(n, n);
  if (m > 0) {
    const B = hg.incidence;
    // W = B · Bᵀ (with optional binarisation) and zero diagonal.
    for (let i = 0; i < n; i++) {
      for (let k = i; k < n; k++) {
        let s = 0;
        for (let j = 0; j < m; j++) {
          const a = weighted ? B.get(i, j) : (B.get(i, j) > 0 ? 1 : 0);
          const b = weighted ? B.get(k, j) : (B.get(k, j) > 0 ? 1 : 0);
          s += a * b;
        }
        if (i === k) continue; // diagonal stays zero
        W.set(i, k, s);
        W.set(k, i, s);
      }
    }
  }
  return {
    weights: W, nodes: hg.nodes.slice(),
    params: {
      source: 'cliqueExpansion', weighted,
      nHyperedges: m, hypergraphSizeDistribution: hg.sizeDistribution,
    },
  };
}

/* ── hypergraphMeasures ──────────────────────────────────────────── */

export interface HypergraphMeasures {
  hyperdegree: number[];                  // length n_nodes
  nodeStrength: number[];                 // length n_nodes
  maxEdgeSize: number[];                  // length n_nodes
  coDegree: Matrix;                       // n × n (zero diag)
  edgeSizes: number[];                    // length m
  edgePairwiseOverlap: Matrix;            // m × m (zero diag)
  overlapCoefficient: Matrix;             // m × m
  jaccard: Matrix;                        // m × m
  density: number;
  avgEdgeSize: number;
  sizeDistribution: Record<string, number>;
  intersectionProfile: Record<string, number>;
  pairwiseParticipation: number;
  nNodes: number;
  nHyperedges: number;
}

function choose2(n: number, k: number): number {
  if (k < 0 || k > n) return 0;
  if (k === 0 || k === n) return 1;
  k = Math.min(k, n - k);
  let res = 1;
  for (let i = 0; i < k; i++) res = (res * (n - i)) / (i + 1);
  return Math.round(res);
}

export function hypergraphMeasures(hg: Hypergraph): HypergraphMeasures {
  const n = hg.nNodes;
  const m = hg.nHyperedges;
  if (m === 0) {
    return {
      hyperdegree: new Array<number>(n).fill(0),
      nodeStrength: new Array<number>(n).fill(0),
      maxEdgeSize: new Array<number>(n).fill(0),
      coDegree: new Matrix(n, n),
      edgeSizes: [],
      edgePairwiseOverlap: new Matrix(0, 0),
      overlapCoefficient: new Matrix(0, 0),
      jaccard: new Matrix(0, 0),
      density: 0, avgEdgeSize: 0,
      sizeDistribution: hg.sizeDistribution,
      intersectionProfile: {},
      pairwiseParticipation: 0,
      nNodes: n, nHyperedges: 0,
    };
  }
  const B = hg.incidence;
  // Binarise B for measure formulas (R uses `(B > 0) * 1.0`).
  const Bb = new Matrix(n, m);
  for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) Bb.set(i, j, B.get(i, j) > 0 ? 1 : 0);

  const edgeSizes: number[] = new Array(m).fill(0);
  for (let j = 0; j < m; j++) {
    let s = 0;
    for (let i = 0; i < n; i++) s += Bb.get(i, j);
    edgeSizes[j] = s;
  }
  const hyperdegree = new Array<number>(n).fill(0);
  const nodeStrength = new Array<number>(n).fill(0);
  const maxEdgeSize = new Array<number>(n).fill(0);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (Bb.get(i, j) > 0) {
        hyperdegree[i]!++;
        nodeStrength[i]! += edgeSizes[j]!;
        if (edgeSizes[j]! > maxEdgeSize[i]!) maxEdgeSize[i] = edgeSizes[j]!;
      }
    }
  }

  // co_degree = Bb · Bbᵀ (with zero diag)
  const coDegree = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let k = i + 1; k < n; k++) {
      let s = 0;
      for (let j = 0; j < m; j++) s += Bb.get(i, j) * Bb.get(k, j);
      coDegree.set(i, k, s);
      coDegree.set(k, i, s);
    }
  }
  // edge_pairwise_overlap = Bbᵀ · Bb (with zero diag)
  const edgePairwiseOverlap = new Matrix(m, m);
  for (let j = 0; j < m; j++) {
    for (let l = j + 1; l < m; l++) {
      let s = 0;
      for (let i = 0; i < n; i++) s += Bb.get(i, j) * Bb.get(i, l);
      edgePairwiseOverlap.set(j, l, s);
      edgePairwiseOverlap.set(l, j, s);
    }
  }

  // Overlap coefficient + Jaccard
  const overlapCoefficient = new Matrix(m, m);
  const jaccard = new Matrix(m, m);
  for (let j = 0; j < m; j++) {
    for (let l = 0; l < m; l++) {
      if (j === l) continue;
      const ov = edgePairwiseOverlap.get(j, l);
      const sMin = Math.min(edgeSizes[j]!, edgeSizes[l]!);
      const sUnion = edgeSizes[j]! + edgeSizes[l]! - ov;
      overlapCoefficient.set(j, l, sMin > 0 ? ov / sMin : 0);
      jaccard.set(j, l, sUnion > 0 ? ov / sUnion : 0);
    }
  }

  // Density
  const uniqSizes = new Set(edgeSizes);
  let density: number;
  if (uniqSizes.size === 1) {
    const k = edgeSizes[0]!;
    density = k > n ? 0 : m / choose2(n, k);
  } else {
    let sumK = 0;
    for (const k of edgeSizes) sumK += k;
    density = sumK / (n * m);
  }
  const avgEdgeSize = edgeSizes.reduce((a, b) => a + b, 0) / m;

  // Intersection profile (over upper triangle of edge overlap)
  const intersectionProfile: Record<string, number> = {};
  if (m >= 2) {
    for (let j = 0; j < m; j++) for (let l = j + 1; l < m; l++) {
      const k = edgePairwiseOverlap.get(j, l);
      const key = `overlap_${k}`;
      intersectionProfile[key] = (intersectionProfile[key] ?? 0) + 1;
    }
  }

  // Pairwise participation
  let pairwiseParticipation = 0;
  if (n >= 2) {
    let pos = 0;
    for (let i = 0; i < n; i++) for (let k = i + 1; k < n; k++) {
      if (coDegree.get(i, k) > 0) pos++;
    }
    pairwiseParticipation = pos / choose2(n, 2);
  }

  return {
    hyperdegree, nodeStrength, maxEdgeSize,
    coDegree, edgeSizes, edgePairwiseOverlap,
    overlapCoefficient, jaccard,
    density, avgEdgeSize,
    sizeDistribution: hg.sizeDistribution,
    intersectionProfile, pairwiseParticipation,
    nNodes: n, nHyperedges: m,
  };
}

/* ── hypergraphCentrality ─────────────────────────────────────────
 * Three variants from Benson 2019 (arXiv:1807.09644):
 *   - clique (CEC): eigenvector centrality of the clique-expanded graph.
 *   - Z: linear tensor eigen-equation, λ xᵢ = Σ_{e ∋ i} ∏_{j ∈ e, j≠i} xⱼ.
 *   - H: power-(k-1) tensor eigen-equation,
 *        λ xᵢ^(k-1) = Σ_{e ∋ i} ∏_{j ∈ e, j≠i} xⱼ.
 * All via power iteration with the Kolda-Mayo SSHOPM shift to guarantee
 * monotone convergence on non-negative tensors.
 * ─────────────────────────────────────────────────────────────────── */

export type HypergraphCentralityType = 'clique' | 'Z' | 'H';

export interface HypergraphCentralityOptions {
  /** Which variants to compute. Default ['clique', 'Z', 'H']. */
  type?: HypergraphCentralityType[];
  /** Max iterations. Default 1000. */
  maxIter?: number;
  /** Convergence tolerance on L1 change. Default 1e-8. */
  tol?: number;
  /** L2-normalise each centrality vector. Default true. */
  normalize?: boolean;
}

export type HypergraphCentralityResult = Partial<Record<HypergraphCentralityType, number[]>>;

function tensorPowerIter(
  hyperedges: number[][], edgeSizes: number[], n: number, exponent: number,
  maxIter: number, tol: number, x0: number[], normalize: boolean,
  shift = 1,
): number[] {
  let x = x0.slice();
  for (let iter = 0; iter < maxIter; iter++) {
    const y = new Array<number>(n).fill(0);
    for (let eIdx = 0; eIdx < hyperedges.length; eIdx++) {
      const e = hyperedges[eIdx]!;
      const ke = edgeSizes[eIdx]!;
      if (ke < 2) continue;
      const xe = e.map(v => x[v]!);
      let total = 1;
      let zeros = 0;
      let lastNonZero = -1;
      for (let i = 0; i < ke; i++) {
        if (xe[i] === 0) { zeros++; lastNonZero = -1; }
        else { total *= xe[i]!; }
      }
      if (zeros === 0) {
        for (let i = 0; i < ke; i++) y[e[i]!]! += total / xe[i]!;
      } else if (zeros === 1) {
        // Exactly one zero entry — leave-one-out product is non-zero only for that index.
        let zeroIdx = -1;
        let prodNz = 1;
        for (let i = 0; i < ke; i++) {
          if (xe[i] === 0) zeroIdx = i;
          else prodNz *= xe[i]!;
        }
        if (zeroIdx >= 0) y[e[zeroIdx]!]! += prodNz;
        void lastNonZero;
      }
      // zeros >= 2: every leave-one-out product is zero — no contribution.
    }
    let yArr = y;
    if (exponent > 1) {
      yArr = yArr.map(v => Math.sign(v) * Math.pow(Math.abs(v), 1 / exponent));
    }
    for (let i = 0; i < n; i++) yArr[i] = yArr[i]! + shift * x[i]!;
    let nrm = 0;
    for (const v of yArr) nrm += v * v;
    nrm = Math.sqrt(nrm);
    if (nrm === 0) { x = yArr; break; }
    for (let i = 0; i < n; i++) yArr[i] = yArr[i]! / nrm;
    let l1 = 0;
    for (let i = 0; i < n; i++) l1 += Math.abs(yArr[i]! - x[i]!);
    if (l1 < tol) { x = yArr; break; }
    x = yArr;
  }
  // Sign convention + optional un-normalise.
  let anyNonZero = false;
  for (const v of x) if (v !== 0) { anyNonZero = true; break; }
  if (anyNonZero) {
    let sum = 0;
    for (const v of x) sum += v;
    if (sum < 0) for (let i = 0; i < n; i++) x[i] = -x[i]!;
    if (!normalize) {
      let maxAbs = 0;
      for (const v of x) if (Math.abs(v) > maxAbs) maxAbs = Math.abs(v);
      if (maxAbs > 0) for (let i = 0; i < n; i++) x[i] = x[i]! / maxAbs;
    }
  }
  return x;
}

export function hypergraphCentrality(
  hg: Hypergraph, options: HypergraphCentralityOptions = {},
): HypergraphCentralityResult {
  const { type = ['clique', 'Z', 'H'], maxIter = 1000, tol = 1e-8, normalize = true } = options;
  const n = hg.nNodes;
  const m = hg.nHyperedges;
  const out: HypergraphCentralityResult = {};
  if (n === 0) {
    for (const t of type) out[t] = [];
    return out;
  }
  if (m === 0) {
    for (const t of type) out[t] = new Array<number>(n).fill(0);
    return out;
  }

  const x0 = new Array<number>(n).fill(1 / Math.sqrt(n));
  const edgeSizes = hg.hyperedges.map(e => e.length);
  const kMax = Math.max(...edgeSizes, 0);

  if (type.includes('clique')) {
    // Clique-expansion eigenvector centrality.
    const Bb = new Matrix(n, m);
    for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) Bb.set(i, j, hg.incidence.get(i, j) > 0 ? 1 : 0);
    const W = new Matrix(n, n);
    for (let i = 0; i < n; i++) for (let k = 0; k < n; k++) {
      if (i === k) continue;
      let s = 0;
      for (let j = 0; j < m; j++) s += Bb.get(i, j) * Bb.get(k, j);
      W.set(i, k, s);
    }
    let x = x0.slice();
    for (let iter = 0; iter < maxIter; iter++) {
      const y = new Array<number>(n).fill(0);
      for (let i = 0; i < n; i++) for (let k = 0; k < n; k++) y[i]! += W.get(i, k) * x[k]!;
      let nrm = 0;
      for (const v of y) nrm += v * v;
      nrm = Math.sqrt(nrm);
      if (nrm === 0) { x = y; break; }
      for (let i = 0; i < n; i++) y[i] = y[i]! / nrm;
      let l1 = 0;
      for (let i = 0; i < n; i++) l1 += Math.abs(y[i]! - x[i]!);
      if (l1 < tol) { x = y; break; }
      x = y;
    }
    let sum = 0;
    for (const v of x) sum += v;
    if (sum < 0) for (let i = 0; i < n; i++) x[i] = -x[i]!;
    if (!normalize) {
      let maxAbs = 0;
      for (const v of x) if (Math.abs(v) > maxAbs) maxAbs = Math.abs(v);
      if (maxAbs > 0) for (let i = 0; i < n; i++) x[i] = x[i]! / maxAbs;
    }
    out.clique = x;
  }

  if (type.includes('Z')) {
    out.Z = tensorPowerIter(hg.hyperedges, edgeSizes, n, 1, maxIter, tol, x0, normalize);
  }
  if (type.includes('H')) {
    out.H = tensorPowerIter(hg.hyperedges, edgeSizes, n, Math.max(1, kMax - 1), maxIter, tol, x0, normalize);
  }
  return out;
}
