/**
 * Markov-chain analysis — port of Nestimate::passage_time,
 * Nestimate::markov_stability, and Nestimate::markov_order_test
 * (Nestimate/R/markov.R + Nestimate/R/markov_order.R, 0.4.4).
 *
 * `passageTime` / `markovStability` are deterministic (pure linear algebra).
 * `markovOrderTest` is stochastic (within-w permutation LRT) and supports
 * replay-based index replay for cross-language parity.
 *
 * R reference identities preserved:
 *   - Row normalisation with warning when |rowSums - 1| > 1e-6 (threshold
 *     matches `.mpt_normalize_rows`).
 *   - Zero-row detection throws with a matching error message.
 *   - Kemeny-Snell fundamental matrix:  Z = (I − P + 1·πᵀ)^{-1},
 *     M[i,j] = (Z[j,j] − Z[i,j]) / π[j], diag(M) = 1/π.
 *   - Stationary distribution computed from (I − Pᵀ + J/n)·π = 1/n
 *     (see linalg.ts); equivalent to R's eigenvector extraction.
 *   - Sojourn time = Inf when persistence ≥ 1 − ε (double eps).
 *   - Data-frame columns in stability exactly match R's:
 *       state, persistence, stationary_prob, return_time, sojourn_time,
 *       avg_time_to_others, avg_time_from_others.
 *   - `markov_order_test` port:
 *       - Exact within-w permutation LRT; G² = 2·Σ N log(N/E), context-wise.
 *       - Layer DoF = Σ_rows max(nonzero − 1, 0) (Nestimate convention).
 *       - Log-likelihood: order-0 for step 1, order=min(step-1, k) afterwards,
 *         \x01-separated kgram keys.
 *       - Sequential selection: optimalOrder = last k in a contiguous run of
 *         rejections from k=1 (stop at first non-rejection).
 *       - AIC = 2·cumDof − 2·loglik, BIC = log(sum seq_lens)·cumDof − 2·loglik.
 *       - max_order capped to longest-1 with a console warning (R uses
 *         `message()`).
 *
 * Important: these functions intentionally do NOT round (unlike R's print
 * helpers which truncate to 2–4 decimals). Parity tests compare raw values.
 */
import { Matrix } from '../core/matrix.js';
import { solveLinear, eigenDominantLeft } from '../core/linalg.js';
import { SeededRNG } from '../core/rng.js';
import type { TNA, SequenceData } from '../core/types.js';

/** Input accepted by passageTime / markovStability. */
export type MarkovInput = TNA | Matrix | number[][];

export interface PassageTimeOptions {
  /** Restrict output to this subset of states. Default: all. */
  states?: string[];
  /** Auto-normalise rows if they don't sum to 1. Default true. */
  normalize?: boolean;
}

export interface PassageTimeResult {
  /** n × n MFPT matrix (row i → column j). Diagonal = 1/π_i. */
  matrix: Matrix;
  /** Stationary distribution π aligned with `states`. */
  stationary: Float64Array;
  /**
   * Self-loop probabilities P_ii aligned with `states`. Added so that
   * `markovStability` can read them even after `states` filtering (R's
   * `passage_time` output doesn't expose `persistence`; we do, and also
   * re-derive it in `markovStability` to match R's exact pathway).
   */
  persistence: Float64Array;
  /** State labels aligned with `matrix` / `stationary`. */
  states: string[];
}

export interface MarkovStabilityRow {
  state: string;
  persistence: number;
  stationaryProb: number;
  returnTime: number;
  sojournTime: number;
  avgTimeToOthers: number;
  avgTimeFromOthers: number;
}

export interface MarkovStabilityResult {
  /** One row per state, in state order. */
  stability: MarkovStabilityRow[];
  /** Underlying passage-time object (matches R's `$mpt`). */
  mpt: PassageTimeResult;
}

/* ---------------------------------------------------------------------- */
/*  Internal helpers                                                       */
/* ---------------------------------------------------------------------- */

/** Extract a numeric transition matrix + labels from any supported input. */
function extractP(x: MarkovInput): { P: Matrix; labels: string[] } {
  if (x instanceof Matrix) {
    if (!x.isSquare) {
      throw new Error('passageTime: transition matrix must be square');
    }
    const n = x.rows;
    const labels = Array.from({ length: n }, (_, i) => `S${i + 1}`);
    return { P: x.clone(), labels };
  }

  if (Array.isArray(x)) {
    if (x.length === 0) {
      throw new Error('passageTime: empty matrix input');
    }
    const mat = Matrix.from2D(x);
    if (!mat.isSquare) {
      throw new Error('passageTime: transition matrix must be square');
    }
    const n = mat.rows;
    const labels = Array.from({ length: n }, (_, i) => `S${i + 1}`);
    return { P: mat, labels };
  }

  // TNA model
  const model = x as TNA;
  if (!model.weights || !(model.weights instanceof Matrix)) {
    throw new Error(
      'passageTime: TNA has no numeric weight matrix. Model does not contain data. Rebuild with buildTna().',
    );
  }
  const labels =
    model.labels && model.labels.length === model.weights.rows
      ? model.labels.slice()
      : Array.from({ length: model.weights.rows }, (_, i) => `S${i + 1}`);
  return { P: model.weights.clone(), labels };
}

/**
 * Normalise rows to sum to 1 and reject zero-sum rows.
 * Error / warning messages match Nestimate's `.mpt_normalize_rows` behaviour.
 */
function normaliseRows(
  P: Matrix,
  labels: string[],
  normalize: boolean,
): Matrix {
  const n = P.rows;
  const rowSums = P.rowSums();

  // Zero-row check first (same order as R)
  const zeroStates: string[] = [];
  for (let i = 0; i < n; i++) {
    if (rowSums[i]! <= 0) zeroStates.push(labels[i]!);
  }
  if (zeroStates.length > 0) {
    throw new Error(
      `Transition matrix has zero-sum row(s) for state(s): ${zeroStates.join(', ')}. ` +
        'These states have no outgoing transitions, so the chain is not ergodic ' +
        'and mean first passage times are undefined. Remove the state(s) or ' +
        'supply a different transition matrix.',
    );
  }

  // |rowSum - 1| > 1e-6 → must normalise (or throw if normalize=false)
  let needsNorm = false;
  for (let i = 0; i < n; i++) {
    if (Math.abs(rowSums[i]! - 1) > 1e-6) {
      needsNorm = true;
      break;
    }
  }
  if (!needsNorm) return P;
  if (!normalize) {
    throw new Error('Transition matrix rows must sum to 1.');
  }
  const out = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    const s = rowSums[i]!;
    for (let j = 0; j < n; j++) {
      out.set(i, j, P.get(i, j) / s);
    }
  }
  return out;
}

/**
 * Core Kemeny-Snell MFPT computation.
 *   Z = (I − P + 1·πᵀ)^{-1}
 *   M[i,j] = (Z[j,j] − Z[i,j]) / π[j]
 *   diag(M) = 1/π
 */
function kemenySnellMfpt(P: Matrix, pi: Float64Array): Matrix {
  const n = P.rows;

  // A = I − P + 1·πᵀ (add π_j to every entry in column j)
  const A = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const ident = i === j ? 1 : 0;
      A.set(i, j, ident - P.get(i, j) + pi[j]!);
    }
  }

  // Z = A^{-1}. Use LU solve against identity to get Z column by column.
  const I = Matrix.eye(n);
  let Z: Matrix;
  try {
    Z = solveLinear(A, I);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    throw new Error(
      `Kemeny-Snell fundamental matrix is singular; chain is likely not ergodic (${msg}).`,
    );
  }

  const M = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) {
        M.set(i, j, 1 / pi[i]!);
      } else {
        M.set(i, j, (Z.get(j, j) - Z.get(i, j)) / pi[j]!);
      }
    }
  }
  return M;
}

/* ---------------------------------------------------------------------- */
/*  Public exports                                                         */
/* ---------------------------------------------------------------------- */

/**
 * Mean First Passage Times (Kemeny-Snell).
 *
 * Element M[i,j] is the expected number of steps to travel from state i to
 * state j for the first time. Diagonal equals 1/π_i (mean recurrence time).
 *
 * Mirrors Nestimate::passage_time (R/markov.R).
 */
export function passageTime(
  x: MarkovInput,
  options: PassageTimeOptions = {},
): PassageTimeResult {
  const { normalize = true, states: stateSubset } = options;

  const { P: rawP, labels } = extractP(x);
  const P = normaliseRows(rawP, labels, normalize);
  const n = P.rows;

  let pi = eigenDominantLeft(P);
  // Guard mirroring R's "pmax(pi, .Machine$double.eps); pi / sum(pi)"
  let anyNonPositive = false;
  for (let i = 0; i < n; i++) {
    if (pi[i]! <= 0) {
      anyNonPositive = true;
      break;
    }
  }
  if (anyNonPositive) {
    const EPS = Number.EPSILON;
    let sum = 0;
    const fixed = new Float64Array(n);
    for (let i = 0; i < n; i++) {
      fixed[i] = Math.max(pi[i]!, EPS);
      sum += fixed[i]!;
    }
    for (let i = 0; i < n; i++) fixed[i]! /= sum;
    pi = fixed;
  }

  const M = kemenySnellMfpt(P, pi);

  // Collect persistence = diag(P)
  const persistence = new Float64Array(n);
  for (let i = 0; i < n; i++) persistence[i] = P.get(i, i);

  if (stateSubset && stateSubset.length > 0) {
    const unknown = stateSubset.filter((s) => !labels.includes(s));
    if (unknown.length > 0) {
      throw new Error(`Unknown states: ${unknown.join(', ')}`);
    }
    const idx = stateSubset.map((s) => labels.indexOf(s));
    const Msub = M.subMatrix(idx, idx);
    const piSub = new Float64Array(idx.length);
    const persSub = new Float64Array(idx.length);
    for (let k = 0; k < idx.length; k++) {
      piSub[k] = pi[idx[k]!]!;
      persSub[k] = persistence[idx[k]!]!;
    }
    return {
      matrix: Msub,
      stationary: piSub,
      persistence: persSub,
      states: stateSubset.slice(),
    };
  }

  return {
    matrix: M,
    stationary: pi,
    persistence,
    states: labels,
  };
}

/**
 * Per-state Markov stability metrics.
 *
 * Mirrors Nestimate::markov_stability (R/markov.R) — every column in the
 * `stability` list matches the R data frame field-for-field.
 */
export function markovStability(
  x: MarkovInput,
  options: { normalize?: boolean } = {},
): MarkovStabilityResult {
  const { normalize = true } = options;

  // R path: normalise once in markov_stability, pass already-normalised P into
  // passage_time with normalize=FALSE. We replicate this so that warnings /
  // errors fire exactly once.
  const { P: rawP, labels } = extractP(x);
  const P = normaliseRows(rawP, labels, normalize);

  const mpt = passageTime(P, { normalize: false });
  const n = P.rows;
  const pi = mpt.stationary;
  const M = mpt.matrix;

  const EPS = Number.EPSILON;
  const stability: MarkovStabilityRow[] = [];
  for (let i = 0; i < n; i++) {
    const persistence = P.get(i, i);
    const sojourn =
      persistence >= 1 - EPS ? Number.POSITIVE_INFINITY : 1 / (1 - persistence);

    // mean over off-diagonal row / column
    let sumTo = 0;
    let sumFrom = 0;
    for (let j = 0; j < n; j++) {
      if (j === i) continue;
      sumTo += M.get(i, j);
      sumFrom += M.get(j, i);
    }
    const denom = n - 1;
    const avgTo = denom > 0 ? sumTo / denom : Number.NaN;
    const avgFrom = denom > 0 ? sumFrom / denom : Number.NaN;

    stability.push({
      state: labels[i]!,
      persistence,
      stationaryProb: pi[i]!,
      returnTime: 1 / pi[i]!,
      sojournTime: sojourn,
      avgTimeToOthers: avgTo,
      avgTimeFromOthers: avgFrom,
    });
  }

  return { stability, mpt };
}

/* ====================================================================== */
/*  Markov Order Test — port of Nestimate::markov_order_test               */
/* ====================================================================== */

/** Separator matching Nestimate's `.HON_SEP` for encoding kgram keys. */
const HON_SEP = '\x01';
/** log(Machine$double.eps) — R's fallback lower bound in log-likelihood. */
const LOG_EPS_R = Math.log(2.220446049250313e-16); // = -36.0436533891...

/** Input accepted by `markovOrderTest` — trajectories, tnaj SequenceData, or TNA. */
export type MarkovOrderInput = string[][] | SequenceData | TNA;

/** One row of the order-test table. */
export interface MarkovOrderTestRow {
  order: number;
  loglik: number;
  AIC: number;
  BIC: number;
  /** df for LRT between order and order-1 (NaN for order 0). */
  df: number;
  /** G² statistic (NaN for order 0). */
  g2: number;
  /** Permutation p-value (NaN when df=0 or when no tuples). */
  pPermutation: number;
  /** Asymptotic χ² p-value. */
  pAsymptotic: number;
  /** `pPermutation < alpha` (false for order 0 or NaN). */
  significant: boolean;
}

/** Serialised replay shape for permutation indices.
 *
 * `permIndices[k-1]` is the replay block for order `k` (k in [1..maxOrder]).
 * Each block is `perm[p]` where `perm[p]` is a flat `number[]` of length
 * `tuples.length` — the **full** s-index vector after shuffle. For every
 * w-context, the successor positions inside that context are permuted;
 * singletons are left untouched. The flat layout lets JS replay by writing
 * `s[t] = s_orig[permFlat[t]]` per permutation (all JS needs is an index
 * mapping from the original position to the shuffled position — the x/w
 * columns never change).
 *
 * We use the **flat successor index vector** (length = nTuples) rather than
 * per-context block indices because it is: (a) the most compact JSON form R
 * can emit from inside a per-context shuffle loop, (b) trivially replayable
 * in JS with zero reconstruction overhead, and (c) robust to context
 * ordering differences between R and JS (the mapping is absolute).
 *
 * If `permIndices[k-1]` is missing or empty for any k, that order's
 * permutation is executed with the local RNG (seeded by `opts.seed`).
 */
export interface MarkovOrderReplay {
  permIndices?: number[][][];
}

export interface MarkovOrderOptions {
  /** Highest Markov order to test. Default 3. */
  maxOrder?: number;
  /** Within-w permutations per order. Default 500. */
  nPerm?: number;
  /** Significance level for sequential order selection. Default 0.05. */
  alpha?: number;
  /** Optional RNG seed (deterministic local permutation without replay). */
  seed?: number;
  /** Replay block — if present, each order's permutation stream is
   *  replaced by the supplied successor-index vectors. Guarantees bitwise
   *  agreement with external fixtures. */
  replay?: MarkovOrderReplay;
}

export interface MarkovOrderResult {
  optimalOrder: number;
  bicOrder: number;
  aicOrder: number;
  /** One row per order, 0..maxOrder. */
  testTable: MarkovOrderTestRow[];
  /** Per-order empirical null G² distribution; `permutationNull[k-1]` is
   *  a `number[]` of length nPerm (or shorter if df=0). */
  permutationNull: number[][];
  /** Log-likelihood per order (length = maxOrder+1, order 0 first). */
  logliks: number[];
  /** Layer DoF per order (length = maxOrder+1, order 0 first). */
  layerDofs: number[];
  /** Fitted transition matrices (length = maxOrder+1); entry 0 is the
   *  order-0 marginal, stored as a 1×nStates Matrix for type uniformity.
   *  Entries 1..maxOrder are the kgram → kgram row-stochastic matrices. */
  transitionMatrices: Matrix[];
  /** Per-order kgram node labels (in the order used by each transition
   *  matrix). `transitionNodes[0]` = state labels from the marginal. */
  transitionNodes: string[][];
  /** Marginal state labels. */
  states: string[];
  /** Marginal probabilities aligned with `states`. */
  marginal: Float64Array;
  nSequences: number;
  nObservations: number;
  /** Per-order tuple count (length maxOrder). */
  nTuples: number[];
  nPerm: number;
  alpha: number;
  maxOrder: number;
}

/* -------- input coercion -------- */

/** Strip nulls/undefined and coerce an input into string[][]. */
export function extractTrajectories(data: MarkovOrderInput): string[][] {
  // TNA
  if (
    data !== null &&
    typeof data === 'object' &&
    !Array.isArray(data) &&
    'weights' in (data as object)
  ) {
    const model = data as TNA;
    if (!model.data) {
      throw new Error(
        'markovOrderTest: TNA model does not contain data. Rebuild with buildTna().',
      );
    }
    return sequenceDataToTrajectories(model.data);
  }
  if (!Array.isArray(data)) {
    throw new Error('markovOrderTest: data must be an array of trajectories');
  }
  // `SequenceData` = (string|null)[][]; both shapes are Array<Array<...>>.
  return sequenceDataToTrajectories(data as SequenceData);
}

/** Convert tnaj SequenceData → trajectories, mirroring `.hon_parse_input`. */
function sequenceDataToTrajectories(data: SequenceData | string[][]): string[][] {
  const out: string[][] = [];
  for (const rawSeq of data) {
    if (!Array.isArray(rawSeq)) continue;
    // Strip trailing nulls/NA like R does (keep up to last non-null).
    let lastNonNull = -1;
    for (let i = 0; i < rawSeq.length; i++) {
      const v = rawSeq[i];
      if (v !== null && v !== undefined && (typeof v !== 'number' || !Number.isNaN(v))) {
        lastNonNull = i;
      }
    }
    if (lastNonNull < 0) continue;
    const traj: string[] = [];
    for (let i = 0; i <= lastNonNull; i++) {
      const v = rawSeq[i];
      if (v === null || v === undefined) continue;
      traj.push(String(v));
    }
    if (traj.length >= 2) out.push(traj);
  }
  return out;
}

/* -------- helpers: kgram counts, transition matrix, log-likelihood -------- */

interface KgramCounts {
  nodes: string[];
  nodeCounts: Map<string, number>;
  edges: { from: string; to: string; weight: number }[];
}

/** Port of `.mogen_count_kgrams`. */
export function kgramCounts(trajectories: string[][], k: number): KgramCounts {
  if (k < 1) throw new Error('kgramCounts: k must be >= 1');
  const nodeCounts = new Map<string, number>();
  const edgeCounts = new Map<string, number>(); // key = from + \x02 + to
  const EDGE_SEP = '\x02';

  for (const traj of trajectories) {
    const n = traj.length;
    if (n < k) continue;
    const kgrams: string[] = [];
    for (let i = 0; i + k <= n; i++) {
      const kg = traj.slice(i, i + k).join(HON_SEP);
      kgrams.push(kg);
      nodeCounts.set(kg, (nodeCounts.get(kg) ?? 0) + 1);
    }
    for (let i = 0; i + 1 < kgrams.length; i++) {
      const key = `${kgrams[i]}${EDGE_SEP}${kgrams[i + 1]}`;
      edgeCounts.set(key, (edgeCounts.get(key) ?? 0) + 1);
    }
  }
  // R's node order = names(table(all_nodes)), which is lexicographic on R's
  // default locale. For parity we sort ASCII/binary (same as R's C locale).
  const nodes = Array.from(nodeCounts.keys()).sort();
  const edges: { from: string; to: string; weight: number }[] = [];
  for (const [key, weight] of edgeCounts) {
    const sepIdx = key.indexOf(EDGE_SEP);
    edges.push({
      from: key.slice(0, sepIdx),
      to: key.slice(sepIdx + 1),
      weight,
    });
  }
  return { nodes, nodeCounts, edges };
}

/** Port of `.mogen_transition_matrix`. Returns a row-stochastic Matrix +
 *  the aligned node list (same object as `nodes`). */
// Soft cap (n×n × 8 bytes; n=5800 ⇒ ~257 MiB ≈ 269 MB on the wire).
// The kernel pre-checks this because V8's allocation failure for
// new Float64Array(huge) bubbles up as the opaque
// "Array buffer allocation failed" — surfacing a clear error
// here lets the UI suggest lowering maxOrder instead of crashing.
const KGRAM_MATRIX_MAX_N = 5800;

export function transitionMatrixFromKgrams(
  nodes: string[],
  edges: { from: string; to: string; weight: number }[],
): Matrix {
  const n = nodes.length;
  if (n > KGRAM_MATRIX_MAX_N) {
    const mb = Math.round((n * n * 8) / (1024 * 1024));
    throw new Error(
      `transitionMatrixFromKgrams: ${n} distinct k-grams would need a ` +
      `${n}×${n} matrix (~${mb} MB). This usually means maxOrder is too ` +
      `high for the dataset. Try lowering maxOrder, or pruning rare ` +
      `contexts before testing.`
    );
  }
  const mat = new Matrix(n, n);
  if (n === 0) return mat;
  const idx = new Map<string, number>();
  for (let i = 0; i < n; i++) idx.set(nodes[i]!, i);
  for (const e of edges) {
    const r = idx.get(e.from);
    const c = idx.get(e.to);
    if (r === undefined || c === undefined) continue;
    mat.set(r, c, mat.get(r, c) + e.weight);
  }
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let j = 0; j < n; j++) s += mat.get(i, j);
    if (s > 0) {
      for (let j = 0; j < n; j++) mat.set(i, j, mat.get(i, j) / s);
    }
  }
  return mat;
}

/** Port of `.mogen_layer_dof`: per row, max(nonzero−1, 0); sum across rows. */
export function layerDof(mat: Matrix): number {
  let dof = 0;
  for (let i = 0; i < mat.rows; i++) {
    let nz = 0;
    for (let j = 0; j < mat.cols; j++) {
      if (mat.get(i, j) > 0) nz++;
    }
    dof += Math.max(nz - 1, 0);
  }
  return dof;
}

/** Port of `.mogen_marginal`: names(table(unlist(...))) / sum. */
export function marginalDistribution(trajectories: string[][]): {
  states: string[];
  probs: Float64Array;
} {
  const counts = new Map<string, number>();
  let total = 0;
  for (const t of trajectories) {
    for (const s of t) {
      counts.set(s, (counts.get(s) ?? 0) + 1);
      total++;
    }
  }
  const states = Array.from(counts.keys()).sort();
  const probs = new Float64Array(states.length);
  for (let i = 0; i < states.length; i++) {
    probs[i] = (counts.get(states[i]!) ?? 0) / total;
  }
  return { states, probs };
}

/**
 * Port of `.mogen_log_likelihood`. `transMats[0]` is the order-0 marginal
 * (as a 1×nStates Matrix with column names = `transitionNodes[0]`), and
 * `transMats[k]` is the order-k kgram transition matrix.
 */
export function logLikelihood(
  trajectories: string[][],
  k: number,
  transMats: Matrix[],
  transNodes: string[][],
): number {
  const p0Nodes = transNodes[0]!;
  const p0 = transMats[0]!;
  const p0Idx = new Map<string, number>();
  for (let i = 0; i < p0Nodes.length; i++) p0Idx.set(p0Nodes[i]!, i);

  // Precompute per-order row/col index maps
  const rowIdx: Map<string, number>[] = [new Map()];
  const colIdx: Map<string, number>[] = [new Map()];
  for (let ord = 1; ord <= k; ord++) {
    const nodes = transNodes[ord]!;
    const mR = new Map<string, number>();
    const mC = new Map<string, number>();
    for (let i = 0; i < nodes.length; i++) {
      mR.set(nodes[i]!, i);
      mC.set(nodes[i]!, i);
    }
    rowIdx.push(mR);
    colIdx.push(mC);
  }

  let total = 0;
  for (const traj of trajectories) {
    const n = traj.length;
    if (n === 0) continue;
    // Order 0: initial state probability
    const firstState = traj[0]!;
    const fi = p0Idx.get(firstState);
    let ll: number;
    if (fi !== undefined && p0.get(0, fi) > 0) {
      ll = Math.log(p0.get(0, fi));
    } else {
      ll = LOG_EPS_R;
    }
    if (n < 2) {
      total += ll;
      continue;
    }
    for (let step = 2; step <= n; step++) {
      const orderUsed = Math.min(step - 1, k);
      if (orderUsed === 0) {
        // Unreachable because step>=2 → orderUsed>=1 when k>=1;
        // matches R's `if (order_used == 0L)` branch only for k=0.
        const s = traj[step - 1]!;
        const si = p0Idx.get(s);
        if (si !== undefined && p0.get(0, si) > 0) {
          ll += Math.log(p0.get(0, si));
        } else {
          ll += LOG_EPS_R;
        }
      } else {
        const srcStart = step - orderUsed; // 1-based in R
        const srcKey = traj.slice(srcStart - 1, step - 1).join(HON_SEP);
        const tgtKey = traj.slice(srcStart, step).join(HON_SEP);
        const tm = transMats[orderUsed]!;
        const r = rowIdx[orderUsed]!.get(srcKey);
        const c = colIdx[orderUsed]!.get(tgtKey);
        if (r !== undefined && c !== undefined) {
          const p = tm.get(r, c);
          ll += p > 0 ? Math.log(p) : LOG_EPS_R;
        } else {
          ll += LOG_EPS_R;
        }
      }
    }
    total += ll;
  }
  return total;
}

/* -------- tuple extraction, G², permutation -------- */

interface Tuples {
  x: string[];
  w: string[];
  s: string[];
  /** Context → sorted list of tuple indices for that w. */
  byContext: Map<string, number[]>;
}

/** Port of `.mot_extract_tuples`. */
export function extractTuples(trajectories: string[][], k: number): Tuples {
  if (k < 1) throw new Error('extractTuples: k must be >= 1');
  const x: string[] = [];
  const w: string[] = [];
  const s: string[] = [];
  for (const traj of trajectories) {
    const n = traj.length;
    if (n < k + 1) continue;
    const lastPos = n - k;
    for (let p = 1; p <= lastPos; p++) {
      // p is 1-based like R. traj is 0-based in JS.
      x.push(traj[p - 1]!);
      s.push(traj[p - 1 + k]!);
      if (k === 1) {
        w.push('');
      } else {
        // paste(traj[(p+1):(p+k-1)], collapse = HON_SEP) in R (1-based)
        // → traj[p..p+k-2] in 0-based terms
        const start0 = p; // 0-based index for R's traj[p+1]
        const end0 = p + k - 1; // 0-based exclusive for R's traj[p+k-1]
        w.push(traj.slice(start0, end0).join(HON_SEP));
      }
    }
  }
  const byContext = new Map<string, number[]>();
  for (let i = 0; i < w.length; i++) {
    const key = w[i]!;
    const arr = byContext.get(key);
    if (arr) arr.push(i);
    else byContext.set(key, [i]);
  }
  return { x, w, s, byContext };
}

/** G² on one (x, s) sub-table. Mirrors `.mot_g2_one_w`.
 *
 *  Bit-parity with R: R's `table(x, s)` sorts row/column labels alphabetically
 *  (the `dimnames` are the `sort()`-order of unique levels), and R's
 *  `tab[nz]` extracts elements in **column-major** order. We replicate both
 *  to ensure the floating-point summation sequence matches. */
function g2OneContext(xVec: string[], sVec: string[]): { stat: number; df: number } {
  if (xVec.length === 0) return { stat: 0, df: 0 };
  const rowSet = new Set<string>();
  const colSet = new Set<string>();
  for (const v of xVec) rowSet.add(v);
  for (const v of sVec) colSet.add(v);
  const rowLabels = Array.from(rowSet).sort();
  const colLabels = Array.from(colSet).sort();
  const rowIdx = new Map<string, number>();
  const colIdx = new Map<string, number>();
  for (let i = 0; i < rowLabels.length; i++) rowIdx.set(rowLabels[i]!, i);
  for (let i = 0; i < colLabels.length; i++) colIdx.set(colLabels[i]!, i);
  const nR = rowLabels.length;
  const nC = colLabels.length;
  if (nR < 2 || nC < 2) return { stat: 0, df: 0 };
  const tab = new Array<number>(nR * nC).fill(0);
  for (let i = 0; i < xVec.length; i++) {
    const r = rowIdx.get(xVec[i]!)!;
    const c = colIdx.get(sVec[i]!)!;
    tab[r * nC + c]!++;
  }
  const rs = new Array<number>(nR).fill(0);
  const cs = new Array<number>(nC).fill(0);
  let total = 0;
  for (let r = 0; r < nR; r++) {
    for (let c = 0; c < nC; c++) {
      const v = tab[r * nC + c]!;
      rs[r]! += v;
      cs[c]! += v;
      total += v;
    }
  }
  if (total === 0) return { stat: 0, df: 0 };
  // R's `tab[nz]` with nz a logical matrix returns elements in column-major
  // order (R's native storage). Iterate c-major to match the exact summation
  // sequence and produce bit-identical g2 stats across R/JS.
  let sumTerms = 0;
  for (let c = 0; c < nC; c++) {
    for (let r = 0; r < nR; r++) {
      const v = tab[r * nC + c]!;
      if (v <= 0) continue;
      const e = (rs[r]! * cs[c]!) / total;
      if (e <= 0) continue;
      sumTerms += v * Math.log(v / e);
    }
  }
  const g2 = 2 * sumTerms;
  const df = (nR - 1) * (nC - 1);
  return { stat: g2, df };
}

/** Port of `.mot_g2`. Aggregates G² across all w-contexts. */
export function g2Statistic(tuples: Tuples): { stat: number; df: number } {
  if (tuples.x.length === 0) return { stat: 0, df: 0 };
  let totalStat = 0;
  let totalDf = 0;
  for (const [, idxList] of tuples.byContext) {
    const xSub = new Array<string>(idxList.length);
    const sSub = new Array<string>(idxList.length);
    for (let i = 0; i < idxList.length; i++) {
      const ti = idxList[i]!;
      xSub[i] = tuples.x[ti]!;
      sSub[i] = tuples.s[ti]!;
    }
    const { stat, df } = g2OneContext(xSub, sSub);
    totalStat += stat;
    totalDf += df;
  }
  return { stat: totalStat, df: totalDf };
}

/**
 * Within-w permutation null. If `replayFlatIndices` is supplied, each entry
 * `replayFlatIndices[p]` is a length-nTuples integer vector; we set
 * `s[t] = s_orig[replayFlatIndices[p][t]]` for that permutation (the x/w
 * columns never change). If absent, use the RNG to shuffle s within each
 * context (singletons skipped, matching R's `if (length(idx) > 1L)` check).
 */
export function withinWPermutation(
  tuples: Tuples,
  nPerm: number,
  rng: SeededRNG,
  replayFlatIndices?: number[][],
): number[] {
  if (tuples.x.length === 0) return [];
  const nT = tuples.s.length;
  const sOrig = tuples.s.slice();
  const out = new Array<number>(nPerm);

  const sBuf = new Array<string>(nT);
  for (let p = 0; p < nPerm; p++) {
    // Reset to original s
    for (let i = 0; i < nT; i++) sBuf[i] = sOrig[i]!;

    if (replayFlatIndices && replayFlatIndices[p]) {
      const map = replayFlatIndices[p]!;
      for (let i = 0; i < nT; i++) {
        sBuf[i] = sOrig[map[i]!]!;
      }
    } else {
      // Shuffle s within each context; singletons unchanged
      for (const [, idxList] of tuples.byContext) {
        if (idxList.length <= 1) continue;
        // Fisher-Yates shuffle of positions inside this context
        const pick = idxList.slice();
        // Shuffle 'pick' then write sBuf[idxList[i]] = sOrig[pick[i]]
        for (let k = pick.length - 1; k > 0; k--) {
          const j = Math.floor(rng.random() * (k + 1));
          const tmp = pick[k]!;
          pick[k] = pick[j]!;
          pick[j] = tmp;
        }
        for (let i = 0; i < idxList.length; i++) {
          sBuf[idxList[i]!] = sOrig[pick[i]!]!;
        }
      }
    }

    // Recompute G² on (x, w, sBuf)
    let totalStat = 0;
    for (const [, idxList] of tuples.byContext) {
      const xSub = new Array<string>(idxList.length);
      const sSub = new Array<string>(idxList.length);
      for (let i = 0; i < idxList.length; i++) {
        const ti = idxList[i]!;
        xSub[i] = tuples.x[ti]!;
        sSub[i] = sBuf[ti]!;
      }
      totalStat += g2OneContext(xSub, sSub).stat;
    }
    out[p] = totalStat;
  }
  return out;
}

/* -------- χ² upper-tail CDF (pchisq(q, df, lower.tail=FALSE)) -------- */

export function logGamma(x: number): number {
  // Lanczos approximation — sufficient precision for our p-values (1e-14).
  const g = 7;
  const c = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028,
    771.32342877765313, -176.61502916214059, 12.507343278686905,
    -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7,
  ];
  if (x < 0.5) {
    return Math.log(Math.PI / Math.sin(Math.PI * x)) - logGamma(1 - x);
  }
  x -= 1;
  let a = c[0]!;
  const t = x + g + 0.5;
  for (let i = 1; i < g + 2; i++) a += c[i]! / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

/** Regularised upper incomplete gamma Q(a, x) via series + continued fraction. */
function regIncGammaUpper(a: number, x: number): number {
  if (x < 0 || a <= 0) return Number.NaN;
  if (x === 0) return 1;
  if (x < a + 1) {
    // Series for P(a,x), then Q = 1 − P
    let term = 1 / a;
    let sum = term;
    for (let n = 1; n < 1000; n++) {
      term *= x / (a + n);
      sum += term;
      if (Math.abs(term) < Math.abs(sum) * 1e-16) break;
    }
    const P = sum * Math.exp(-x + a * Math.log(x) - logGamma(a));
    return 1 - P;
  } else {
    // Lentz's continued fraction for Q directly
    const FPMIN = 1e-300;
    let b = x + 1 - a;
    let c = 1 / FPMIN;
    let d = 1 / b;
    let h = d;
    for (let n = 1; n < 1000; n++) {
      const an = -n * (n - a);
      b += 2;
      d = an * d + b;
      if (Math.abs(d) < FPMIN) d = FPMIN;
      c = b + an / c;
      if (Math.abs(c) < FPMIN) c = FPMIN;
      d = 1 / d;
      const delta = d * c;
      h *= delta;
      if (Math.abs(delta - 1) < 1e-16) break;
    }
    return h * Math.exp(-x + a * Math.log(x) - logGamma(a));
  }
}

/** pchisq(q, df, lower.tail=FALSE) — matches R. */
export function pchisqUpper(q: number, df: number): number {
  if (!Number.isFinite(q) || q < 0 || df <= 0) return Number.NaN;
  if (q === 0) return 1;
  return regIncGammaUpper(df / 2, q / 2);
}

/* -------- main: markovOrderTest -------- */

export function markovOrderTest(
  data: MarkovOrderInput,
  options: MarkovOrderOptions = {},
): MarkovOrderResult {
  const {
    maxOrder: maxOrderReq = 3,
    nPerm = 500,
    alpha = 0.05,
    seed,
    replay,
  } = options;

  if (maxOrderReq < 1) throw new Error("'maxOrder' must be >= 1");
  if (nPerm < 1) throw new Error("'nPerm' must be >= 1");
  if (!(alpha > 0 && alpha < 1)) throw new Error("'alpha' must be in (0, 1)");

  const trajectories = extractTrajectories(data);
  const nSeqs = trajectories.length;
  if (nSeqs < 1) {
    // Diagnose the input so the caller knows whether it was empty or
    // entirely-singletons. extractTrajectories drops sequences with < 2
    // states (you can't measure transitions in a length-1 sequence).
    const raw = Array.isArray(data) ? (data as unknown[]) : [];
    let nInput = raw.length;
    let nLen1 = 0;
    let nLen0 = 0;
    if (Array.isArray(raw)) {
      for (const s of raw) {
        if (!Array.isArray(s)) continue;
        const len = (s as unknown[]).filter((v) => v !== null && v !== undefined && v !== '').length;
        if (len === 0) nLen0++;
        else if (len === 1) nLen1++;
      }
    }
    throw new Error(
      `markovOrderTest: 0 usable sequences (transitions need length >= 2). ` +
      `Input had ${nInput} sequences (${nLen0} empty, ${nLen1} singletons). ` +
      `Rebuild with a larger gap, or pick a Session column that produces multi-step sessions.`
    );
  }

  const seqLens = trajectories.map((t) => t.length);
  const longest = Math.max(...seqLens);
  let maxOrder = Math.trunc(maxOrderReq);
  if (maxOrder >= longest) {
    maxOrder = longest - 1;
    // eslint-disable-next-line no-console
    console.warn(
      `max_order capped at ${maxOrder} (longest sequence = ${longest})`,
    );
  }

  // --- Fit models (marginal + kgram transitions) ---
  const { states, probs: marginalProbs } = marginalDistribution(trajectories);
  // Store marginal as 1×nStates matrix so transMats[0] uniform.
  const p0Mat = new Matrix(1, states.length);
  for (let i = 0; i < states.length; i++) p0Mat.set(0, i, marginalProbs[i]!);
  const transMats: Matrix[] = [p0Mat];
  const transNodes: string[][] = [states.slice()];
  const layerDofs: number[] = [Math.max(states.length - 1, 0)];

  for (let k = 1; k <= maxOrder; k++) {
    const kg = kgramCounts(trajectories, k);
    const tm = transitionMatrixFromKgrams(kg.nodes, kg.edges);
    transMats.push(tm);
    transNodes.push(kg.nodes.slice());
    layerDofs.push(layerDof(tm));
  }

  // Log-likelihoods for orders 0..maxOrder
  const logliks: number[] = [];
  for (let k = 0; k <= maxOrder; k++) {
    logliks.push(
      logLikelihood(
        trajectories,
        k,
        transMats.slice(0, k + 1),
        transNodes.slice(0, k + 1),
      ),
    );
  }

  // --- Per-order test ---
  const rng = new SeededRNG(seed ?? 42);
  const perOrder: Array<{
    stat: number;
    df: number;
    null: number[];
    pPerm: number;
    pAsymp: number;
    nTuples: number;
  }> = [];

  for (let k = 1; k <= maxOrder; k++) {
    const tuples = extractTuples(trajectories, k);
    const g2 = g2Statistic(tuples);
    let nullStats: number[] = [];
    let pPerm = Number.NaN;
    let pAsymp = Number.NaN;
    if (tuples.x.length > 0 && g2.df > 0) {
      const replayBlock =
        replay && replay.permIndices ? replay.permIndices[k - 1] : undefined;
      nullStats = withinWPermutation(tuples, nPerm, rng, replayBlock);
      let geCount = 0;
      for (const ns of nullStats) {
        if (ns >= g2.stat) geCount++;
      }
      pPerm = (geCount + 1) / (nullStats.length + 1);
      pAsymp = pchisqUpper(g2.stat, g2.df);
    }
    perOrder.push({
      stat: g2.stat,
      df: g2.df,
      null: nullStats,
      pPerm,
      pAsymp,
      nTuples: tuples.x.length,
    });
  }

  // Sequential selection — optimalOrder = last k in a contiguous run of
  // rejections from k=1 (R's `lapply(seq_len(max_order), ...)` with `cont`).
  const sigVec = perOrder.map(
    (po) => !Number.isNaN(po.pPerm) && po.pPerm < alpha,
  );
  let optimalOrder = 0;
  let cont = true;
  for (let k = 1; k <= maxOrder; k++) {
    if (cont && sigVec[k - 1]) optimalOrder = k;
    else cont = false;
  }

  // IC panel
  const cumDof: number[] = [];
  let acc = 0;
  for (const d of layerDofs) {
    acc += d;
    cumDof.push(acc);
  }
  const nObs = seqLens.reduce((a, b) => a + b, 0);
  const aicVec = logliks.map((ll, k) => 2 * cumDof[k]! - 2 * ll);
  const bicVec = logliks.map((ll, k) => Math.log(nObs) * cumDof[k]! - 2 * ll);

  const testTable: MarkovOrderTestRow[] = [];
  for (let k = 0; k <= maxOrder; k++) {
    if (k === 0) {
      testTable.push({
        order: 0,
        loglik: logliks[0]!,
        AIC: aicVec[0]!,
        BIC: bicVec[0]!,
        df: Number.NaN,
        g2: Number.NaN,
        pPermutation: Number.NaN,
        pAsymptotic: Number.NaN,
        significant: false,
      });
    } else {
      const po = perOrder[k - 1]!;
      testTable.push({
        order: k,
        loglik: logliks[k]!,
        AIC: aicVec[k]!,
        BIC: bicVec[k]!,
        df: po.df,
        g2: po.stat,
        pPermutation: po.pPerm,
        pAsymptotic: po.pAsymp,
        significant: sigVec[k - 1]!,
      });
    }
  }

  // BIC / AIC optimum (minima over rows 0..maxOrder)
  let bicOrder = 0;
  let aicOrder = 0;
  for (let k = 1; k <= maxOrder; k++) {
    if (testTable[k]!.BIC < testTable[bicOrder]!.BIC) bicOrder = k;
    if (testTable[k]!.AIC < testTable[aicOrder]!.AIC) aicOrder = k;
  }

  return {
    optimalOrder,
    bicOrder,
    aicOrder,
    testTable,
    permutationNull: perOrder.map((po) => po.null),
    logliks,
    layerDofs,
    transitionMatrices: transMats,
    transitionNodes: transNodes,
    states,
    marginal: marginalProbs,
    nSequences: nSeqs,
    nObservations: nObs,
    nTuples: perOrder.map((po) => po.nTuples),
    nPerm,
    alpha,
    maxOrder,
  };
}
