/**
 * Simplicial complex construction — port of Nestimate::build_simplicial
 * (R/simplicial.R). Supports the canonical type = "clique" construction:
 *
 *   1. Symmetrize the adjacency: w[i,j] = max(|w[i,j]|, |w[j,i]|).
 *   2. Threshold: edge iff w > 0 AND (w >= threshold [inclusive] or
 *      w > threshold [exclusive]).
 *   3. Bron-Kerbosch to enumerate maximal cliques.
 *   4. Expand each maximal clique to all sub-simplices (faces) up to size
 *      maxDim + 1.
 *   5. Ensure every vertex appears as a 0-simplex.
 *
 * Plus `bettiNumbers` (rank computation on the integer boundary matrices via
 * fraction-free Bareiss elimination — bit-equivalent to R's `qr(bmat)$rank`
 * for the {-1,0,1}-valued boundary matrices produced here) and
 * `eulerCharacteristic` (sum of (-1)^k * f_k).
 *
 * Verified against Nestimate::build_simplicial 0.5.4 in
 * verify/per-verb/nestimate-simplicial/.
 */
import { Matrix } from '../core/matrix.js';
import type { TNA } from '../core/types.js';

export type SimplicialInput = Matrix | number[][] | TNA;

/** Minimal pathway-source shape — anything with a `path` field of the form
 *  "A -> B -> C" plus a node list. Matches the on-disk shape of tnaj's
 *  HonResult, HypaResult, and MogenTransitionRow[] (with explicit `nodes`). */
export interface PathwayLikeInput {
  /** Either pathway rows directly, or an HON-family result that exposes
   *  `edges` (HON), `scores` (HYPA), or `transitions` (MOGen-derived).
   *  Each row must have a `path` field; HYPA rows additionally have
   *  `anomaly` and `ratio` used for filtering and ordering. */
  paths?: { path: string; ratio?: number; anomaly?: 'over' | 'under' | 'normal' }[];
  /** First-order state alphabet — the node set of the resulting complex. */
  firstOrderStates?: string[];
  /** MOGen-style state alphabet. */
  states?: string[];
  /** HYPA-style nodes. */
  nodes?: string[];
}

export interface SimplicialOptions {
  /** Construction type. "clique" (default) on any matrix/TNA, or "pathway"
   *  for an HON-family input (PathwayLikeInput). */
  type?: 'clique' | 'pathway';
  /** Minimum non-zero absolute edge weight to include an edge. Default 0.
   *  Clique-mode only. */
  threshold?: number;
  /** Maximum simplex dimension (a k-simplex has k+1 nodes). Default 10. */
  maxDim?: number;
  /** Include edges with weight strictly greater than threshold when false;
   *  include weight >= threshold when true. Default true (matches R). */
  inclusive?: boolean;
  /** Optional node labels (used when x is a raw matrix without labels). */
  labels?: string[];
  /** Pathway-mode only: cap on the number of pathways read into the complex.
   *  Applied AFTER ordering/filtering. Default: no cap. */
  maxPathways?: number;
  /** Pathway-mode only, HYPA: which anomaly class to include. Default 'all'
   *  (every non-normal anomaly). */
  anomaly?: 'all' | 'over' | 'under';
}

export interface SimplicialComplex {
  /** All simplices as sorted 0-based vertex-index tuples. */
  simplices: number[][];
  /** Node labels (length nNodes). */
  nodes: string[];
  nNodes: number;
  nSimplices: number;
  /** Maximum simplex dimension k where a k-simplex has k+1 vertices. */
  dimension: number;
  /** Counts per dimension, indices 0..dimension. */
  fVector: number[];
  /** Density = nSimplices / sum_{d=0..dim} C(nNodes, d+1). */
  density: number;
  /** Mean simplex dimension. */
  meanDim: number;
  type: 'clique' | 'pathway' | 'vr';
}

/* ── matrix extraction ──────────────────────────────────────────── */

function extractAdjacency(x: SimplicialInput, labelsOpt?: string[]): {
  mat: Matrix;
  labels: string[];
} {
  if (x instanceof Matrix) {
    if (!x.isSquare) throw new Error('buildSimplicial: matrix must be square');
    const n = x.rows;
    const labels = labelsOpt && labelsOpt.length === n
      ? labelsOpt.slice()
      : Array.from({ length: n }, (_, i) => `V${i + 1}`);
    return { mat: x.clone(), labels };
  }
  if (Array.isArray(x)) {
    const mat = Matrix.from2D(x);
    if (!mat.isSquare) throw new Error('buildSimplicial: matrix must be square');
    const n = mat.rows;
    const labels = labelsOpt && labelsOpt.length === n
      ? labelsOpt.slice()
      : Array.from({ length: n }, (_, i) => `V${i + 1}`);
    return { mat, labels };
  }
  const tna = x as TNA;
  if (!tna.weights || !(tna.weights instanceof Matrix)) {
    throw new Error('buildSimplicial: TNA has no weight matrix');
  }
  const labels = tna.labels && tna.labels.length === tna.weights.rows
    ? tna.labels.slice()
    : Array.from({ length: tna.weights.rows }, (_, i) => `V${i + 1}`);
  return { mat: tna.weights.clone(), labels };
}

/* ── adjacency thresholding ─────────────────────────────────────── */

/** Boolean undirected adjacency. Mirrors Nestimate's `.sc_threshold_adjacency`
 *  followed by `adj | t(adj)` and diag(adj) <- FALSE. */
function symmetricThresholdAdjacency(
  mat: Matrix,
  threshold: number,
  inclusive: boolean,
): boolean[][] {
  const n = mat.rows;
  const out: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const w = Math.max(Math.abs(mat.get(i, j)), Math.abs(mat.get(j, i)));
      const keep = inclusive ? (w > 0 && w >= threshold) : (w > 0 && w > threshold);
      if (keep) { out[i]![j] = true; out[j]![i] = true; }
    }
  }
  return out;
}

/* ── Bron-Kerbosch maximal cliques (undirected) ─────────────────── */

function maximalCliques(adj: boolean[][]): number[][] {
  const n = adj.length;
  const neighbors: Set<number>[] = adj.map(row => {
    const s = new Set<number>();
    for (let j = 0; j < n; j++) if (row[j]) s.add(j);
    return s;
  });
  const result: number[][] = [];

  function bk(R: number[], P: Set<number>, X: Set<number>): void {
    if (P.size === 0 && X.size === 0) {
      result.push(R.slice().sort((a, b) => a - b));
      return;
    }
    // Pivot: maximize |P ∩ N(u)|
    let pivot = -1;
    let best = -1;
    for (const u of [...P, ...X]) {
      let c = 0;
      const nu = neighbors[u]!;
      for (const v of P) if (nu.has(v)) c++;
      if (c > best) { best = c; pivot = u; }
    }
    const pivotNbrs = pivot >= 0 ? neighbors[pivot]! : new Set<number>();
    const candidates: number[] = [];
    for (const v of P) if (!pivotNbrs.has(v)) candidates.push(v);
    for (const v of candidates) {
      const nv = neighbors[v]!;
      const newP = new Set<number>();
      const newX = new Set<number>();
      for (const u of P) if (nv.has(u)) newP.add(u);
      for (const u of X) if (nv.has(u)) newX.add(u);
      bk([...R, v], newP, newX);
      P.delete(v);
      X.add(v);
    }
  }

  bk([], new Set(Array.from({ length: n }, (_, i) => i)), new Set());

  // Isolated vertices: igraph returns size-1 cliques for every node not in a
  // larger clique. Bron-Kerbosch with size-1 fallback handles them naturally
  // (a vertex with no neighbors is a clique of size 1).
  for (let v = 0; v < n; v++) {
    if (neighbors[v]!.size === 0) {
      result.push([v]);
    }
  }
  return result;
}

/* ── face expansion ─────────────────────────────────────────────── */

function combinations<T>(arr: T[], k: number, out: T[][], buf: T[] = [], start = 0): void {
  if (buf.length === k) { out.push(buf.slice()); return; }
  for (let i = start; i <= arr.length - (k - buf.length); i++) {
    buf.push(arr[i]!);
    combinations(arr, k, out, buf, i + 1);
    buf.pop();
  }
}

function expandToFaces(maximal: number[][], maxDim: number): number[][] {
  const seen = new Set<string>();
  const result: number[][] = [];
  for (const simplex of maximal) {
    const sorted = simplex.slice().sort((a, b) => a - b);
    const maxSize = Math.min(sorted.length, maxDim + 1);
    for (let size = 1; size <= maxSize; size++) {
      if (size === sorted.length) {
        const key = sorted.join(',');
        if (!seen.has(key)) { seen.add(key); result.push(sorted.slice()); }
      } else {
        const combos: number[][] = [];
        combinations(sorted, size, combos);
        for (const face of combos) {
          const key = face.join(',');
          if (!seen.has(key)) { seen.add(key); result.push(face); }
        }
      }
    }
  }
  return result;
}

/* ── constructor ────────────────────────────────────────────────── */

function choose(n: number, k: number): number {
  if (k < 0 || k > n) return 0;
  if (k === 0 || k === n) return 1;
  k = Math.min(k, n - k);
  let res = 1;
  for (let i = 0; i < k; i++) res = (res * (n - i)) / (i + 1);
  return Math.round(res);
}

function makeComplex(
  simplicesIn: number[][],
  nodes: string[],
  type: 'clique' | 'pathway' | 'vr',
): SimplicialComplex {
  // Ensure every vertex appears as a 0-simplex.
  const seen = new Set<string>();
  const simplices: number[][] = [];
  for (const s of simplicesIn) {
    const sorted = s.slice().sort((a, b) => a - b);
    const key = sorted.join(',');
    if (!seen.has(key)) { seen.add(key); simplices.push(sorted); }
  }
  for (let i = 0; i < nodes.length; i++) {
    if (!seen.has(String(i))) {
      seen.add(String(i));
      simplices.push([i]);
    }
  }

  const dims = simplices.map(s => s.length - 1);
  const maxD = dims.length > 0 ? Math.max(...dims) : 0;
  const fVector = new Array<number>(maxD + 1).fill(0);
  for (const d of dims) fVector[d]!++;

  let maxPossible = 0;
  for (let d = 0; d <= maxD; d++) maxPossible += choose(nodes.length, d + 1);
  const density = maxPossible > 0 ? simplices.length / maxPossible : 0;
  const meanDim = simplices.length > 0
    ? dims.reduce((a, b) => a + b, 0) / simplices.length
    : 0;

  return {
    simplices,
    nodes,
    nNodes: nodes.length,
    nSimplices: simplices.length,
    dimension: maxD,
    fVector,
    density,
    meanDim,
    type,
  };
}

export function buildSimplicial(
  x: SimplicialInput | PathwayLikeInput,
  options: SimplicialOptions = {},
): SimplicialComplex {
  const { type = 'clique', threshold = 0, maxDim = 10, inclusive = true, labels } = options;
  if (type === 'pathway') {
    return buildSimplicialPathway(x as PathwayLikeInput, options);
  }
  if (type !== 'clique') {
    throw new Error(`buildSimplicial: type='${type}' not implemented`);
  }
  const { mat, labels: nodeLabels } = extractAdjacency(x as SimplicialInput, labels);
  const adj = symmetricThresholdAdjacency(mat, threshold, inclusive);
  const maximal = maximalCliques(adj);
  const faces = expandToFaces(maximal, maxDim);
  return makeComplex(faces, nodeLabels, 'clique');
}

/** Pathway-mode simplicial complex.
 *
 *  Port of Nestimate::.build_simplicial_pathway (R/simplicial.R:184-274).
 *
 *  Accepts:
 *   - HON-style: `{ edges: [{ path, fromOrder, count }, ...], firstOrderStates }`
 *     — uses higher-order edges only (`fromOrder > 1`), ordered by descending count.
 *   - HYPA-style: `{ scores: [{ path, anomaly, ratio }, ...], nodes }` — filters
 *     by anomaly class, orders by |ratio|.
 *   - MOGen-style derived: `{ transitions: [{ path }, ...], states }` — uses the
 *     already-computed mogen_transitions output.
 *   - Raw: `{ paths: [{ path, ... }], firstOrderStates | states | nodes }` —
 *     bypass auto-detection.
 *
 *  Each `path` is "A -> B -> C" (space-arrow-space). We split on `->`, trim,
 *  dedupe, map to vertex indices, and expand to all faces up to `maxDim+1`.
 *
 *  Vertex order in the resulting complex matches the input node list
 *  (firstOrderStates / states / nodes), so the simplex tuples are
 *  interpretable per-input. */
export function buildSimplicialPathway(
  input: PathwayLikeInput | {
    edges?: { path: string; fromOrder?: number; count?: number }[];
    scores?: { path: string; anomaly?: 'over' | 'under' | 'normal'; ratio?: number }[];
    transitions?: { path: string }[];
    firstOrderStates?: string[];
    states?: string[];
    nodes?: string[];
  },
  options: SimplicialOptions = {},
): SimplicialComplex {
  const { maxDim = 10, maxPathways, anomaly = 'all' } = options;

  // Resolve nodes and raw path list, dispatching by input shape.
  let nodes: string[];
  let rawPaths: string[] = [];
  type AnyInput = PathwayLikeInput & {
    edges?: { path: string; fromOrder?: number; count?: number }[];
    scores?: { path: string; anomaly?: 'over' | 'under' | 'normal'; ratio?: number }[];
    transitions?: { path: string }[];
  };
  const i = input as AnyInput;

  if (i.edges && Array.isArray(i.edges)) {
    // HON: higher-order edges only.
    const hoEdges = i.edges.filter(e => (e.fromOrder ?? 1) > 1);
    hoEdges.sort((a, b) => (b.count ?? 0) - (a.count ?? 0));
    const capped = maxPathways != null ? hoEdges.slice(0, maxPathways) : hoEdges;
    nodes = i.firstOrderStates ?? i.nodes ?? [];
    rawPaths = capped.map(e => e.path);
  } else if (i.scores && Array.isArray(i.scores)) {
    // HYPA: filter by anomaly, order by ratio (descending for over/all, ascending for under).
    let filtered = i.scores;
    if (anomaly === 'all') {
      filtered = filtered.filter(s => s.anomaly !== 'normal');
    } else {
      filtered = filtered.filter(s => s.anomaly === anomaly);
    }
    if (anomaly === 'under') {
      filtered.sort((a, b) => (a.ratio ?? 0) - (b.ratio ?? 0));
    } else {
      filtered.sort((a, b) => (b.ratio ?? 0) - (a.ratio ?? 0));
    }
    const capped = maxPathways != null ? filtered.slice(0, maxPathways) : filtered;
    // HYPA `nodes` are arrow-encoded k-grams — recover first-order state alphabet from labels.
    const parts = new Set<string>();
    if (i.nodes) {
      for (const lbl of i.nodes) {
        for (const part of lbl.split('').join(' -> ').split(' -> ')) {
          if (part) parts.add(part);
        }
      }
    }
    nodes = i.firstOrderStates ?? Array.from(parts).sort();
    rawPaths = capped.map(s => s.path);
  } else if (i.transitions && Array.isArray(i.transitions)) {
    // MOGen: pre-computed transitions of the form "A -> B -> C".
    const capped = maxPathways != null ? i.transitions.slice(0, maxPathways) : i.transitions;
    nodes = i.states ?? i.nodes ?? [];
    rawPaths = capped.map(t => t.path);
  } else if (i.paths && Array.isArray(i.paths)) {
    // Generic: caller-supplied paths.
    const capped = maxPathways != null ? i.paths.slice(0, maxPathways) : i.paths;
    nodes = i.firstOrderStates ?? i.states ?? i.nodes ?? [];
    rawPaths = capped.map(p => p.path);
  } else {
    throw new Error(
      'buildSimplicial(type=\'pathway\'): input must expose `edges` (HON), ' +
      '`scores` (HYPA), `transitions` (MOGen), or `paths` (generic).',
    );
  }
  if (nodes.length === 0) {
    throw new Error('buildSimplicial(type=\'pathway\'): node alphabet is empty');
  }

  const nodeIdx = new Map<string, number>();
  nodes.forEach((s, idx) => nodeIdx.set(s, idx));

  // Parse "A -> B -> C" into deduped vertex-index tuples (size ≥ 2).
  const simplicesRaw: number[][] = [];
  for (const p of rawPaths) {
    const parts = p.split('->').map(s => s.trim());
    const seen = new Set<string>();
    const idxs: number[] = [];
    for (const part of parts) {
      if (seen.has(part)) continue;
      seen.add(part);
      const idx = nodeIdx.get(part);
      if (idx === undefined) continue; // ignore parts outside the alphabet
      idxs.push(idx);
    }
    if (idxs.length >= 2) {
      idxs.sort((a, b) => a - b);
      simplicesRaw.push(idxs);
    }
  }

  // Expand each (deduped) path to all faces up to maxDim+1.
  // Note: simplicesRaw entries can be > maxDim+1 vertices — expandToFaces
  // already caps to maxDim+1 via its inner loop.
  const faces = expandToFaces(simplicesRaw, maxDim);
  return makeComplex(faces, nodes, 'pathway');
}

/* ── Betti numbers ──────────────────────────────────────────────── */

/** Integer-matrix rank via fraction-free Bareiss elimination.
 *
 *  The boundary matrices generated by `bettiNumbers` are signed integer with
 *  entries in {-1, 0, +1}. Bareiss elimination keeps all intermediate
 *  quantities as exact integers (modulo Number precision, which is exact for
 *  |x| < 2^53), so the resulting rank is bit-identical to LAPACK's `qr()`
 *  applied to the same matrix at any sensible tolerance. */
function integerRank(matIn: number[][]): number {
  const m = matIn.length;
  if (m === 0) return 0;
  const n = matIn[0]!.length;
  if (n === 0) return 0;
  // Work on a mutable copy.
  const A: number[][] = matIn.map(row => row.slice());
  let prev = 1;
  let rank = 0;
  let col = 0;
  let row = 0;
  while (row < m && col < n) {
    // Find pivot in column `col`, rows >= row.
    let p = -1;
    for (let r = row; r < m; r++) {
      if (A[r]![col] !== 0) { p = r; break; }
    }
    if (p < 0) { col++; continue; }
    if (p !== row) {
      const tmp = A[row]!; A[row] = A[p]!; A[p] = tmp;
    }
    const pivot = A[row]![col]!;
    for (let r = row + 1; r < m; r++) {
      const a = A[r]![col]!;
      if (a !== 0) {
        for (let c = col; c < n; c++) {
          // Bareiss update: A[r][c] = (pivot * A[r][c] - a * A[row][c]) / prev
          const num = pivot * A[r]![c]! - a * A[row]![c]!;
          A[r]![c] = num / prev;
        }
      } else {
        // Row already zero in pivot column — still need the Bareiss scaling
        // for downstream rows to remain integer. With a = 0 the update
        // simplifies to A[r][c] = (pivot * A[r][c]) / prev.
        for (let c = col; c < n; c++) {
          A[r]![c] = (pivot * A[r]![c]!) / prev;
        }
      }
    }
    prev = pivot;
    rank++;
    row++;
    col++;
  }
  return rank;
}

export function bettiNumbers(sc: SimplicialComplex): number[] {
  const maxD = sc.dimension;
  const dims = sc.simplices.map(s => s.length - 1);
  const byDim: number[][][] = Array.from({ length: maxD + 1 }, () => []);
  for (let i = 0; i < sc.simplices.length; i++) {
    byDim[dims[i]!]!.push(sc.simplices[i]!);
  }

  const boundaryRanks = new Array<number>(maxD + 2).fill(0);
  for (let d = 1; d <= maxD; d++) {
    const kSimps = byDim[d]!;
    const km1Simps = byDim[d - 1]!;
    if (kSimps.length === 0 || km1Simps.length === 0) { boundaryRanks[d] = 0; continue; }
    const km1Idx = new Map<string, number>();
    for (let i = 0; i < km1Simps.length; i++) km1Idx.set(km1Simps[i]!.join(','), i);
    const bmat: number[][] = Array.from({ length: km1Simps.length }, () => new Array<number>(kSimps.length).fill(0));
    for (let j = 0; j < kSimps.length; j++) {
      const simplex = kSimps[j]!; // already sorted
      for (let i = 0; i < simplex.length; i++) {
        const face: number[] = [];
        for (let q = 0; q < simplex.length; q++) if (q !== i) face.push(simplex[q]!);
        const rIdx = km1Idx.get(face.join(','));
        if (rIdx !== undefined) {
          // R uses (-1)^(i+1) with 1-based i; JS i is 0-based, so use (-1)^(i+2) === (-1)^i.
          bmat[rIdx]![j] = (i % 2 === 0) ? 1 : -1;
        }
      }
    }
    boundaryRanks[d] = integerRank(bmat);
  }

  const betti = new Array<number>(maxD + 1).fill(0);
  for (let d = 0; d <= maxD; d++) {
    const nK = byDim[d]!.length;
    const nullityK = nK - boundaryRanks[d]!;
    const rankKp1 = d < maxD ? boundaryRanks[d + 1]! : 0;
    betti[d] = Math.max(nullityK - rankKp1, 0);
  }
  return betti;
}

export function eulerCharacteristic(sc: SimplicialComplex): number {
  let chi = 0;
  for (let d = 0; d < sc.fVector.length; d++) {
    chi += (d % 2 === 0 ? 1 : -1) * sc.fVector[d]!;
  }
  return chi;
}

/* ── simplicial degree ──────────────────────────────────────────────
 * Port of Nestimate::simplicial_degree (R/simplicial.R:926). For each
 * node v, counts how many d-simplices contain v across all d ∈ [0, k].
 * Returns one row per node, sorted by `total` descending (R order).
 *
 * `total = sum(byDim[1..])` — d0 (the vertex itself) is excluded from
 * the total by R's design (line 951: `mat[, -1L, drop = FALSE]`).
 *
 * `normalized=true` divides each d-count by C(n-1, d), the maximum
 * possible number of d-simplices that can contain a given vertex in an
 * n-node complex. Matches R lines 941-946.
 * ─────────────────────────────────────────────────────────────────── */

export interface SimplicialDegreeRow {
  /** 0-based vertex index. */
  index: number;
  /** Node label from sc.nodes. */
  node: string;
  /** Per-dimension counts: byDim[d] is the count of d-simplices containing this node. Length = sc.dimension + 1. */
  byDim: number[];
  /** Sum of byDim[1..]. The d0 self-count is excluded — matches R's `rowSums(mat[, -1L])`. */
  total: number;
}

export interface SimplicialDegreeOptions {
  /** Divide each d-count by C(n-1, d). Default false. */
  normalized?: boolean;
}

export function simplicialDegree(
  sc: SimplicialComplex,
  options: SimplicialDegreeOptions = {},
): SimplicialDegreeRow[] {
  const { normalized = false } = options;
  const n = sc.nNodes;
  const maxD = sc.dimension;
  // mat[v][d] = count of d-simplices containing vertex v
  const mat: number[][] = Array.from({ length: n }, () => new Array<number>(maxD + 1).fill(0));
  for (const simplex of sc.simplices) {
    const d = simplex.length - 1;
    for (const v of simplex) mat[v]![d]!++;
  }
  if (normalized && n > 1) {
    for (let d = 0; d <= maxD; d++) {
      const denom = choose(n - 1, d);
      if (denom > 0) {
        for (let v = 0; v < n; v++) mat[v]![d] = mat[v]![d]! / denom;
      }
    }
  }
  const rows: SimplicialDegreeRow[] = [];
  for (let v = 0; v < n; v++) {
    const byDim = mat[v]!.slice();
    let total = 0;
    for (let d = 1; d <= maxD; d++) total += byDim[d]!;
    rows.push({ index: v, node: sc.nodes[v]!, byDim, total });
  }
  // R: df[order(-df$total), ]. Stable sort by total descending.
  rows.sort((a, b) => b.total - a.total);
  return rows;
}

/* ── q-analysis (Atkin) ─────────────────────────────────────────────
 * Port of Nestimate::q_analysis (R/simplicial.R:983).
 *
 * Two maximal simplices are q-connected if they share a face of
 * dimension ≥ q. At each q ∈ [0, maxQ] we count the connected
 * components of the q-adjacency graph over maximal simplices.
 *
 * Returns:
 *  - structureVector[v] = max dimension of any simplex containing v
 *  - qVector[q] = number of components at q-connectivity level q
 *  - maxQ = max simplex dimension among maximal simplices
 *
 * Note on indexing: R reports qVector indexed from max_q DOWN to 0
 * (names "q_3"..."q_0"). tnaj indexes the array 0..maxQ for JS
 * convenience — qVector[0] is the count at q=0, qVector[maxQ] at the top.
 * ─────────────────────────────────────────────────────────────────── */

export interface QAnalysis {
  /** Component count at each q-level, indexed 0..maxQ. */
  qVector: number[];
  /** Max simplex dimension among maximal simplices in the complex. */
  maxQ: number;
  /** Per-node: max dimension of any simplex containing v. Length = sc.nNodes. */
  structureVector: number[];
}

function countComponents(adj: boolean[][]): number {
  const n = adj.length;
  if (n === 0) return 0;
  const visited = new Array<boolean>(n).fill(false);
  let components = 0;
  for (let start = 0; start < n; start++) {
    if (visited[start]) continue;
    components++;
    // BFS — matches Nestimate's .count_components (R:1046)
    const queue: number[] = [start];
    visited[start] = true;
    while (queue.length > 0) {
      const v = queue.shift()!;
      const row = adj[v]!;
      for (let u = 0; u < n; u++) {
        if (row[u] && !visited[u]) { visited[u] = true; queue.push(u); }
      }
    }
  }
  return components;
}

export function qAnalysis(sc: SimplicialComplex): QAnalysis {
  const simplices = sc.simplices;
  const dims = simplices.map(s => s.length - 1);

  // Structure vector: max simplex dimension per node. R:990-996.
  const structureVector = new Array<number>(sc.nNodes).fill(-1);
  for (let i = 0; i < simplices.length; i++) {
    const d = dims[i]!;
    for (const v of simplices[i]!) {
      if (d > structureVector[v]!) structureVector[v] = d;
    }
  }
  // Vertices that appear in no simplex stay at -1 in R; in tnaj
  // buildSimplicial always emits every vertex as a 0-simplex, so the
  // minimum is 0 in practice.

  // Maximal simplex detection. A simplex i is maximal iff no other
  // simplex j with dim(j) > dim(i) has si ⊂ sj. R:1000-1006.
  // Using sorted vertex tuples + set-inclusion test.
  const simplexSets = simplices.map(s => new Set(s));
  const isMaximal: boolean[] = new Array(simplices.length).fill(true);
  for (let i = 0; i < simplices.length; i++) {
    const si = simplices[i]!;
    const di = dims[i]!;
    for (let j = 0; j < simplices.length; j++) {
      if (j === i) continue;
      if (dims[j]! <= di) continue;
      const sj = simplexSets[j]!;
      let contained = true;
      for (const v of si) { if (!sj.has(v)) { contained = false; break; } }
      if (contained) { isMaximal[i] = false; break; }
    }
  }

  const maximalIdx: number[] = [];
  for (let i = 0; i < simplices.length; i++) if (isMaximal[i]) maximalIdx.push(i);
  const nMax = maximalIdx.length;
  const maxQ = nMax > 0 ? Math.max(...maximalIdx.map(i => dims[i]!)) : 0;

  if (nMax <= 1) {
    // R:1014-1020 — degenerate case, every q-level has one component.
    const qVector = new Array<number>(maxQ + 1).fill(1);
    return { qVector, maxQ, structureVector };
  }

  // shared_dim[i][j] = dim of shared face between maximal[i] and maximal[j].
  // R uses -1 for "no shared face"; size of intersection minus 1.
  const shared: number[][] = Array.from({ length: nMax }, () => new Array<number>(nMax).fill(-1));
  for (let i = 0; i < nMax - 1; i++) {
    const a = simplexSets[maximalIdx[i]!]!;
    for (let j = i + 1; j < nMax; j++) {
      const b = simplexSets[maximalIdx[j]!]!;
      let common = 0;
      for (const v of a) if (b.has(v)) common++;
      const dim = common - 1;
      shared[i]![j] = dim;
      shared[j]![i] = dim;
    }
  }

  // For each q in 0..maxQ, build adj_q and count components.
  const qVector = new Array<number>(maxQ + 1).fill(0);
  for (let q = 0; q <= maxQ; q++) {
    const adj: boolean[][] = Array.from({ length: nMax }, () => new Array<boolean>(nMax).fill(false));
    for (let i = 0; i < nMax; i++) {
      for (let j = 0; j < nMax; j++) {
        if (i !== j && shared[i]![j]! >= q) adj[i]![j] = true;
      }
    }
    qVector[q] = countComponents(adj);
  }

  return { qVector, maxQ, structureVector };
}

/* ── persistent homology ────────────────────────────────────────────
 * Port of Nestimate::persistent_homology (R/simplicial.R:820).
 *
 * Builds a filtered complex (clique or Vietoris-Rips), runs standard
 * left-to-right boundary-matrix reduction over Z/2, and returns:
 *  - persistence: birth/death pairs (sorted by -persistence)
 *  - bettiCurve: Betti numbers across a threshold grid
 *  - thresholds: the grid itself
 *  - mode: 'clique' or 'vr'
 *
 * Modes differ semantically:
 *  - clique mode treats `x` as a similarity/weight matrix; high weights
 *    enter early. Internal filtration is ascending in (max_w - weight)
 *    space; user-facing thresholds DESCEND from max_w to ~0. Essential
 *    features get death=0, persistence=birth (R:870-872).
 *  - vr mode treats `x` as a distance matrix; small distances enter
 *    early. Internal filtration matches user-facing (ascending).
 *    Essential features keep death=Infinity (R:881).
 *
 * The internal reduction algorithm is the package's documented
 * sequential exception alongside the MMM EM loop — column j depends
 * on already-reduced columns 1..j-1.
 * ─────────────────────────────────────────────────────────────────── */

export interface PersistencePair {
  /** Dimension of the topological feature that's born here. */
  dimension: number;
  /** User-facing birth threshold. */
  birth: number;
  /** User-facing death threshold. `Infinity` for essential features in VR mode; 0 in clique mode. */
  death: number;
  /** birth - death (clique, descending) or death - birth (VR, ascending). `Infinity` for VR-mode essential features. */
  persistence: number;
}

export interface BettiCurveRow {
  threshold: number;
  dimension: number;
  betti: number;
}

export interface PersistentHomologyResult {
  bettiCurve: BettiCurveRow[];
  persistence: PersistencePair[];
  thresholds: number[];
  mode: 'clique' | 'vr';
}

export interface PersistentHomologyOptions {
  /** Number of threshold grid points for the Betti curve. Default 20. */
  nSteps?: number;
  /** Max simplex dimension to track. Default 3. */
  maxDim?: number;
  /** 'clique' (default) treats x as similarity matrix. 'vr' treats x as distance matrix. */
  type?: 'clique' | 'vr';
  /** VR-only: maximum distance to include. Default = max finite entry. */
  maxScale?: number;
  /** Optional node labels for raw-matrix inputs. */
  labels?: string[];
}

/** Internal filtered-complex shape consumed by the Z/2 reduction. */
interface FilteredComplex {
  /** Simplices in filtration order (ascending filt_asc, then dim). */
  simplices: number[][];
  /** Dimension of each simplex. Parallel array. */
  dim: number[];
  /** Ascending filtration value for each simplex (vertex=0; higher k = enters later). */
  filtAsc: number[];
  /** Comma-joined sorted vertex key for each simplex. */
  key: string[];
  nodes: string[];
  /** Max filt_asc across all simplices. */
  maxFilt: number;
  /** Max user-facing weight (clique) or max scale (VR). */
  maxW: number;
  mode: 'clique' | 'vr';
}

/** Build a clique filtration. Edge weights → ascending filt_asc via
 *  max_w - min(edge weights in simplex). Vertices get filt_asc = 0.
 *  Mirrors Nestimate::.filter_clique_complex (R:502-543). */
function filterCliqueComplex(mat: Matrix, maxDim: number, nodes: string[]): FilteredComplex {
  const n = mat.rows;
  // Symmetrize and zero-diagonal — matches R lines 510-511 (after the
  // outer persistent_homology has already called abs() and pmax()).
  const sym: number[][] = Array.from({ length: n }, () => new Array<number>(n).fill(0));
  let maxW = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const w = mat.get(i, j);
      sym[i]![j] = w;
      if (w > maxW) maxW = w;
    }
  }
  const adj: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (i !== j && sym[i]![j]! > 0) adj[i]![j] = true;
  }
  if (!hasAnyEdge(adj)) {
    // No edges → only 0-simplices. R:513-520.
    const simplices = Array.from({ length: n }, (_, i) => [i]);
    return {
      simplices, dim: new Array<number>(n).fill(0),
      filtAsc: new Array<number>(n).fill(0),
      key: simplices.map(s => s.join(',')),
      nodes, maxFilt: 0, maxW, mode: 'clique',
    };
  }
  // Enumerate all cliques up to maxDim+1 vertices.
  const maximal = maximalCliques(adj);
  const allSimplices = expandToFaces(maximal, maxDim);
  const filt = new Array<number>(allSimplices.length);
  const dim = new Array<number>(allSimplices.length);
  for (let j = 0; j < allSimplices.length; j++) {
    const s = allSimplices[j]!;
    dim[j] = s.length - 1;
    if (s.length === 1) { filt[j] = 0; continue; }
    let minW = Infinity;
    for (let a = 0; a < s.length - 1; a++) {
      for (let b = a + 1; b < s.length; b++) {
        const w = sym[s[a]!]![s[b]!]!;
        if (w < minW) minW = w;
      }
    }
    filt[j] = maxW - minW;
  }
  return finalizeFiltration(allSimplices, dim, filt, nodes, maxW, 'clique');
}

/** Build a Vietoris-Rips filtration. filt(σ) = max pairwise distance.
 *  Mirrors Nestimate::.filter_vr_complex (R:546-595). */
function filterVrComplex(d: Matrix, maxDim: number, nodes: string[], maxScale?: number): FilteredComplex {
  const n = d.rows;
  // Symmetrize and zero-diagonal.
  const dist: number[][] = Array.from({ length: n }, () => new Array<number>(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const a = d.get(i, j);
      const b = d.get(j, i);
      const w = Math.max(a, b);
      if (w < 0) throw new Error('persistentHomology(type="vr"): distance matrix must be non-negative');
      dist[i]![j] = w;
    }
  }
  let maxFinite = 0;
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const w = dist[i]![j]!;
    if (Number.isFinite(w) && w > maxFinite) maxFinite = w;
  }
  const cap = maxScale != null ? maxScale : maxFinite;
  if (cap < 0) throw new Error('persistentHomology(type="vr"): maxScale must be ≥ 0');
  const adj: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (i !== j && Number.isFinite(dist[i]![j]!) && dist[i]![j]! >= 0 && dist[i]![j]! <= cap) {
      adj[i]![j] = true;
    }
  }
  const maximal = maximalCliques(adj);
  const allSimplices = expandToFaces(maximal, maxDim);
  const filt = new Array<number>(allSimplices.length);
  const dim = new Array<number>(allSimplices.length);
  for (let j = 0; j < allSimplices.length; j++) {
    const s = allSimplices[j]!;
    dim[j] = s.length - 1;
    if (s.length === 1) { filt[j] = 0; continue; }
    let maxD = 0;
    for (let a = 0; a < s.length - 1; a++) {
      for (let b = a + 1; b < s.length; b++) {
        const w = dist[s[a]!]![s[b]!]!;
        if (w > maxD) maxD = w;
      }
    }
    filt[j] = maxD;
  }
  return finalizeFiltration(allSimplices, dim, filt, nodes, cap, 'vr');
}

function hasAnyEdge(adj: boolean[][]): boolean {
  const n = adj.length;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (adj[i]![j]) return true;
  return false;
}

function finalizeFiltration(
  simplices: number[][], dim: number[], filt: number[],
  nodes: string[], maxW: number, mode: 'clique' | 'vr',
): FilteredComplex {
  // Stable sort by (filtAsc asc, dim asc) so faces precede cofaces.
  const ord = Array.from({ length: simplices.length }, (_, i) => i);
  ord.sort((a, b) => {
    const da = filt[a]! - filt[b]!;
    if (da !== 0) return da;
    return dim[a]! - dim[b]!;
  });
  const sSim = ord.map(i => simplices[i]!);
  const sDim = ord.map(i => dim[i]!);
  const sFilt = ord.map(i => filt[i]!);
  const keys = sSim.map(s => s.join(','));
  return {
    simplices: sSim, dim: sDim, filtAsc: sFilt, key: keys, nodes,
    maxFilt: sFilt.length > 0 ? sFilt[sFilt.length - 1]! : 0,
    maxW, mode,
  };
}

/** Standard left-to-right boundary-matrix reduction over Z/2.
 *  Mirrors Nestimate::.persistence_pairs_z2 (R:651-733). */
function persistencePairsZ2(fc: FilteredComplex): { pairs: PersistencePair[]; essential: PersistencePair[] } {
  const N = fc.simplices.length;
  if (N === 0) return { pairs: [], essential: [] };

  const keyToIdx = new Map<string, number>();
  for (let i = 0; i < N; i++) keyToIdx.set(fc.key[i]!, i);

  // Boundary column for each simplex: sorted indices of (k-1)-faces.
  const D: number[][] = new Array<number[]>(N);
  for (let j = 0; j < N; j++) {
    if (fc.dim[j]! < 1) { D[j] = []; continue; }
    const s = fc.simplices[j]!;
    const faceIdx: number[] = [];
    for (let i = 0; i < s.length; i++) {
      // face omitting vertex i, then sorted-join key
      const face: number[] = [];
      for (let q = 0; q < s.length; q++) if (q !== i) face.push(s[q]!);
      face.sort((a, b) => a - b);
      const k = face.join(',');
      const idx = keyToIdx.get(k);
      if (idx !== undefined) faceIdx.push(idx);
    }
    faceIdx.sort((a, b) => a - b);
    D[j] = faceIdx;
  }

  const lowToCol = new Int32Array(N); // 0 = unassigned; columns are 1-indexed inside this array
  const pairedB: number[] = [];
  const pairedD: number[] = [];

  for (let j = 0; j < N; j++) {
    let col = D[j]!;
    while (col.length > 0) {
      const l = col[col.length - 1]!;
      const iPlus1 = lowToCol[l]!;
      if (iPlus1 === 0) break;
      const i = iPlus1 - 1;
      // Z/2 symmetric difference of two sorted integer arrays.
      col = symDiffSorted(col, D[i]!);
    }
    D[j] = col;
    if (col.length > 0) {
      const l = col[col.length - 1]!;
      lowToCol[l] = j + 1;
      pairedB.push(l);
      pairedD.push(j);
    }
  }

  const pairedSet = new Set<number>([...pairedB, ...pairedD]);
  const essentialIdx: number[] = [];
  for (let i = 0; i < N; i++) if (!pairedSet.has(i)) essentialIdx.push(i);

  const pairs: PersistencePair[] = [];
  for (let p = 0; p < pairedB.length; p++) {
    const b = pairedB[p]!;
    const d = pairedD[p]!;
    const persistence = fc.filtAsc[d]! - fc.filtAsc[b]!;
    if (persistence > 0) {
      pairs.push({
        dimension: fc.dim[b]!,
        birth: fc.filtAsc[b]!,
        death: fc.filtAsc[d]!,
        persistence,
      });
    }
  }
  const essential: PersistencePair[] = essentialIdx.map(i => ({
    dimension: fc.dim[i]!,
    birth: fc.filtAsc[i]!,
    death: Infinity,
    persistence: Infinity,
  }));
  return { pairs, essential };
}

function symDiffSorted(a: number[], b: number[]): number[] {
  const out: number[] = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i]! === b[j]!) { i++; j++; }
    else if (a[i]! < b[j]!) { out.push(a[i]!); i++; }
    else { out.push(b[j]!); j++; }
  }
  while (i < a.length) out.push(a[i++]!);
  while (j < b.length) out.push(b[j++]!);
  return out;
}

/** Betti curve over the threshold grid. R:736-760. */
function bettiCurveFromPairs(
  persistence: PersistencePair[], thresholds: number[], maxDim: number, mode: 'clique' | 'vr',
): BettiCurveRow[] {
  const rows: BettiCurveRow[] = [];
  for (let d = 0; d <= maxDim; d++) {
    const subset = persistence.filter(p => p.dimension === d);
    for (const t of thresholds) {
      let alive = 0;
      if (mode === 'clique') {
        // R:746-750 — descending thresholds. Alive iff birth >= t AND death < t.
        for (const p of subset) if (p.birth >= t && p.death < t) alive++;
      } else {
        // R:751-756 — ascending thresholds. Alive iff birth <= t AND death > t.
        for (const p of subset) if (p.birth <= t && p.death > t) alive++;
      }
      rows.push({ threshold: t, dimension: d, betti: alive });
    }
  }
  return rows;
}

export function persistentHomology(
  x: SimplicialInput,
  options: PersistentHomologyOptions = {},
): PersistentHomologyResult {
  const { nSteps = 20, maxDim = 3, type = 'clique', maxScale, labels } = options;
  if (!Number.isInteger(nSteps) || nSteps < 1) {
    throw new Error('persistentHomology: nSteps must be a positive integer');
  }
  if (!Number.isInteger(maxDim) || maxDim < 0) {
    throw new Error('persistentHomology: maxDim must be a non-negative integer');
  }
  const { mat, labels: nodeLabels } = extractAdjacency(x, labels);

  let fc: FilteredComplex;
  if (type === 'vr') {
    fc = filterVrComplex(mat, maxDim, nodeLabels, maxScale);
    // R:839-843 — abort if VR produced no usable filtration.
    if (fc.maxW === 0 && fc.maxFilt === 0 && fc.dim.every(d => d === 0)) {
      throw new Error('persistentHomology(type="vr"): all distances are zero or excluded; cannot build filtration');
    }
  } else {
    // Clique mode: abs() + symmetric max, then build filtration. R:845-852.
    const n = mat.rows;
    const cMat = new Matrix(n, n);
    let nonzero = false;
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const w = Math.max(Math.abs(mat.get(i, j)), Math.abs(mat.get(j, i)));
      cMat.set(i, j, w);
      if (w > 0) nonzero = true;
    }
    if (!nonzero) throw new Error('persistentHomology(type="clique"): all weights are zero; cannot build filtration');
    fc = filterCliqueComplex(cMat, maxDim, nodeLabels);
  }

  const reduced = persistencePairsZ2(fc);

  // Map ascending-internal pairs to user-facing scale + thresholds. R:858-886.
  let persistence: PersistencePair[];
  let thresholds: number[];
  if (fc.mode === 'clique') {
    const maxW = fc.maxW;
    const inverted: PersistencePair[] = reduced.pairs.map(p => ({
      dimension: p.dimension,
      birth: maxW - p.birth,
      death: maxW - p.death,
      persistence: (maxW - p.birth) - (maxW - p.death),
    }));
    const essentialClique: PersistencePair[] = reduced.essential.map(p => ({
      dimension: p.dimension,
      birth: maxW - p.birth,
      death: 0,
      persistence: maxW - p.birth,
    }));
    persistence = inverted.concat(essentialClique);
    thresholds = linspace(maxW, maxW * 0.01, nSteps);
  } else {
    persistence = reduced.pairs.concat(reduced.essential);
    const top = Math.max(fc.maxFilt, Number.EPSILON);
    thresholds = linspace(0, top, nSteps);
  }
  // Sort by -persistence (Inf first). R:889.
  persistence.sort((a, b) => {
    if (a.persistence === b.persistence) return 0;
    if (a.persistence === Infinity) return -1;
    if (b.persistence === Infinity) return 1;
    return b.persistence - a.persistence;
  });
  // Defensive drop above max_dim. R:893.
  persistence = persistence.filter(p => p.dimension <= maxDim);

  const bettiCurve = bettiCurveFromPairs(persistence, thresholds, maxDim, fc.mode);
  return { bettiCurve, persistence, thresholds, mode: fc.mode };
}

function linspace(from: number, to: number, n: number): number[] {
  if (n <= 0) return [];
  if (n === 1) return [from];
  const step = (to - from) / (n - 1);
  const out = new Array<number>(n);
  for (let i = 0; i < n; i++) out[i] = from + step * i;
  out[n - 1] = to; // exact endpoint
  return out;
}

/* ── bottleneck distance ─────────────────────────────────────────────
 * Port of Nestimate::bottleneck_distance (R/ph_distances.R:51).
 *
 * W∞(D₁, D₂) = inf_γ sup_{p ∈ D₁} ||p − γ(p)||_∞ over bijections
 * γ: D₁ ∪ Δ → D₂ ∪ Δ, with Δ the diagonal. Per dimension, computed via
 * binary search on candidate ε values + Kuhn bipartite matching for the
 * feasibility check.
 *
 * Essential pairs (death = Inf for VR; death = 0 for clique) are matched
 * one-to-one in sorted birth order. A different essential count between
 * the two diagrams in some dimension returns Infinity for that dimension.
 * ─────────────────────────────────────────────────────────────────── */

export type BottleneckInput = PersistentHomologyResult | PersistencePair[];

export interface BottleneckOptions {
  /** Dimensions to compare. Default: union of dimensions in either diagram. */
  dimension?: number[];
  /** Binary-search tolerance. Default sqrt(Number.EPSILON). */
  tol?: number;
}

function toPairs(d: BottleneckInput): PersistencePair[] {
  if (Array.isArray(d)) return d;
  return d.persistence;
}

function isEssentialPair(p: PersistencePair): boolean {
  return !Number.isFinite(p.death) || p.death === 0;
}

function bottleneckFinite(
  p1: PersistencePair[], p2: PersistencePair[], tol: number,
): number {
  const n1 = p1.length, n2 = p2.length;
  if (n1 === 0 && n2 === 0) return 0;
  if (n1 === 0) {
    let max = 0;
    for (const p of p2) {
      const v = Math.abs(p.death - p.birth) / 2;
      if (v > max) max = v;
    }
    return max;
  }
  if (n2 === 0) {
    let max = 0;
    for (const p of p1) {
      const v = Math.abs(p.death - p.birth) / 2;
      if (v > max) max = v;
    }
    return max;
  }

  // Pairwise L_∞ distances p1 × p2.
  const dPair: number[][] = Array.from({ length: n1 }, () => new Array<number>(n2).fill(0));
  for (let i = 0; i < n1; i++) for (let j = 0; j < n2; j++) {
    const db = Math.abs(p1[i]!.birth - p2[j]!.birth);
    const dd = Math.abs(p1[i]!.death - p2[j]!.death);
    dPair[i]![j] = Math.max(db, dd);
  }
  const dDiag1 = p1.map(p => Math.abs(p.death - p.birth) / 2);
  const dDiag2 = p2.map(p => Math.abs(p.death - p.birth) / 2);

  // Candidate ε values: pairwise distances + diagonal projections + 0.
  const cands = new Set<number>([0]);
  for (let i = 0; i < n1; i++) for (let j = 0; j < n2; j++) cands.add(dPair[i]![j]!);
  for (const v of dDiag1) cands.add(v);
  for (const v of dDiag2) cands.add(v);
  const sorted = Array.from(cands).sort((a, b) => a - b);

  // Feasibility at largest + tol must hold (else return Inf).
  if (!bottleneckFeasible(p1, p2, dPair, dDiag1, dDiag2, sorted[sorted.length - 1]! + tol)) {
    return Infinity;
  }
  // Binary search for the smallest feasible ε.
  let lo = 0, hi = sorted.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (bottleneckFeasible(p1, p2, dPair, dDiag1, dDiag2, sorted[mid]! + tol)) hi = mid;
    else lo = mid + 1;
  }
  return sorted[lo]!;
}

/** Build the augmented bipartite graph and run Kuhn matching. */
function bottleneckFeasible(
  p1: PersistencePair[], p2: PersistencePair[],
  dPair: number[][], dDiag1: number[], dDiag2: number[], eps: number,
): boolean {
  const n1 = p1.length, n2 = p2.length;
  const L = n1 + n2;
  const R = n1 + n2;
  // adj[L][R]
  const adj: boolean[][] = Array.from({ length: L }, () => new Array<boolean>(R).fill(false));
  // p1[i] → p2[j]
  for (let i = 0; i < n1; i++) for (let j = 0; j < n2; j++) {
    if (dPair[i]![j]! <= eps) adj[i]![j] = true;
  }
  // p1[i] → diag(p1[i]) at col n2 + i
  for (let i = 0; i < n1; i++) {
    if (dDiag1[i]! <= eps) adj[i]![n2 + i] = true;
  }
  // diag(p2[j]) (row n1 + j) → p2[j]
  for (let j = 0; j < n2; j++) {
    if (dDiag2[j]! <= eps) adj[n1 + j]![j] = true;
  }
  // diag-to-diag block: always feasible (cost 0)
  for (let j = 0; j < n2; j++) for (let i = 0; i < n1; i++) {
    adj[n1 + j]![n2 + i] = true;
  }
  return kuhnMatchSize(adj) === L;
}

/** Kuhn bipartite cardinality matching via DFS augmenting paths. */
function kuhnMatchSize(adj: boolean[][]): number {
  const nL = adj.length;
  if (nL === 0) return 0;
  const nR = adj[0]!.length;
  if (nR === 0) return 0;
  const matchR = new Int32Array(nR).fill(-1);
  let count = 0;

  function tryAugment(u: number, visited: boolean[]): boolean {
    const row = adj[u]!;
    for (let v = 0; v < nR; v++) {
      if (!row[v] || visited[v]) continue;
      visited[v] = true;
      if (matchR[v] === -1 || tryAugment(matchR[v]!, visited)) {
        matchR[v] = u;
        return true;
      }
    }
    return false;
  }

  for (let u = 0; u < nL; u++) {
    const visited = new Array<boolean>(nR).fill(false);
    if (tryAugment(u, visited)) count++;
  }
  return count;
}

export function bottleneckDistance(
  d1: BottleneckInput, d2: BottleneckInput, options: BottleneckOptions = {},
): Record<string, number> {
  const { tol = Math.sqrt(Number.EPSILON) } = options;
  const p1 = toPairs(d1);
  const p2 = toPairs(d2);
  const dimsInDiagrams = new Set<number>();
  for (const p of p1) dimsInDiagrams.add(p.dimension);
  for (const p of p2) dimsInDiagrams.add(p.dimension);
  const dims = options.dimension
    ? options.dimension.map(d => Math.floor(d))
    : Array.from(dimsInDiagrams).sort((a, b) => a - b);

  const result: Record<string, number> = {};
  for (const k of dims) {
    const sub1 = p1.filter(p => p.dimension === k);
    const sub2 = p2.filter(p => p.dimension === k);
    const ess1 = sub1.filter(isEssentialPair);
    const ess2 = sub2.filter(isEssentialPair);
    const fin1 = sub1.filter(p => !isEssentialPair(p));
    const fin2 = sub2.filter(p => !isEssentialPair(p));

    let dimVal: number;
    if (ess1.length !== ess2.length) {
      dimVal = Infinity;
    } else {
      // 1-D optimal bottleneck on essentials: pair sorted births.
      let essCost = 0;
      if (ess1.length > 0) {
        const b1 = ess1.map(p => p.birth).sort((a, b) => a - b);
        const b2 = ess2.map(p => p.birth).sort((a, b) => a - b);
        for (let i = 0; i < b1.length; i++) {
          const d = Math.abs(b1[i]! - b2[i]!);
          if (d > essCost) essCost = d;
        }
      }
      const finCost = bottleneckFinite(fin1, fin2, tol);
      dimVal = Math.max(essCost, finCost);
    }
    result[`dim_${k}`] = dimVal;
  }
  return result;
}

/* ── persistence landscape ───────────────────────────────────────────
 * Port of Nestimate::persistence_landscape (R/ph_distances.R:265).
 *
 * Λ_{(b,d)}(t) = max(0, min(t − b, d − t)). The k-th landscape function
 * λ⁽ᵏ⁾(t) is the k-th largest of {Λ_{(bᵢ, dᵢ)}(t)}ᵢ at each t. Bubenik 2015.
 *
 * Essential pairs (death = Inf in VR, or death = 0 in clique) are dropped
 * since a tent function is undefined for an infinite-lived class on a
 * finite grid. A clique-mode pair with death = 0 and birth = 0 is kept
 * (it sits at the origin and contributes a zero tent).
 * ─────────────────────────────────────────────────────────────────── */

export interface PersistenceLandscapeOptions {
  /** Highest landscape index to compute. Default 5. */
  kMax?: number;
  /** Dimension to compute the landscape for. Default 1. */
  dimension?: number;
  /** Evaluation grid. Default: 200 evenly-spaced points covering the pair span. */
  tGrid?: number[];
}

export interface LandscapeRow {
  k: number;
  t: number;
  value: number;
}

export interface PersistenceLandscape {
  landscape: LandscapeRow[];
  dimension: number;
  kMax: number;
  tGrid: number[];
}

export function persistenceLandscape(
  ph: PersistentHomologyResult | PersistencePair[],
  options: PersistenceLandscapeOptions = {},
): PersistenceLandscape {
  const { kMax = 5, dimension = 1 } = options;
  if (!Number.isInteger(kMax) || kMax < 1) {
    throw new Error('persistenceLandscape: kMax must be a positive integer');
  }
  if (!Number.isInteger(dimension) || dimension < 0) {
    throw new Error('persistenceLandscape: dimension must be a non-negative integer');
  }
  const pairs = (Array.isArray(ph) ? ph : ph.persistence).filter(p => p.dimension === dimension);
  // Drop essential pairs; clique-mode (death=0, birth>0) is essential.
  const finite = pairs.filter(p => Number.isFinite(p.death) && !(p.death === 0 && p.birth > 0));

  if (finite.length === 0) {
    const tGrid = options.tGrid ?? linspace(0, 1, 200);
    const landscape: LandscapeRow[] = [];
    for (let k = 1; k <= kMax; k++) {
      for (const t of tGrid) landscape.push({ k, t, value: 0 });
    }
    return { landscape, dimension, kMax, tGrid };
  }

  // Normalise orientation: birth ≤ death (clique mode can store the other way).
  const bd = finite.map(p => {
    const lo = Math.min(p.birth, p.death);
    const hi = Math.max(p.birth, p.death);
    return { lo, hi };
  });

  let tGrid: number[];
  if (options.tGrid) {
    tGrid = options.tGrid.slice();
  } else {
    let minB = Infinity, maxD = -Infinity;
    for (const p of bd) { if (p.lo < minB) minB = p.lo; if (p.hi > maxD) maxD = p.hi; }
    if (!Number.isFinite(minB)) minB = 0;
    if (!Number.isFinite(maxD)) maxD = 1;
    tGrid = linspace(minB, maxD, 200);
  }

  const nT = tGrid.length;
  const nPairs = bd.length;
  // tents[i, j] = tent value of pair i at tGrid[j].
  const lambda: number[][] = Array.from({ length: kMax }, () => new Array<number>(nT).fill(0));
  for (let j = 0; j < nT; j++) {
    const t = tGrid[j]!;
    const col = new Array<number>(nPairs);
    for (let i = 0; i < nPairs; i++) {
      const { lo, hi } = bd[i]!;
      col[i] = Math.max(0, Math.min(t - lo, hi - t));
    }
    col.sort((a, b) => b - a);
    for (let k = 0; k < kMax; k++) {
      lambda[k]![j] = k < col.length ? col[k]! : 0;
    }
  }

  const landscape: LandscapeRow[] = [];
  for (let k = 0; k < kMax; k++) {
    for (let j = 0; j < nT; j++) {
      landscape.push({ k: k + 1, t: tGrid[j]!, value: lambda[k]![j]! });
    }
  }
  return { landscape, dimension, kMax, tGrid };
}
