/**
 * Higher-Order Network (HON) — port of Nestimate::build_hon (R/hon.R, 0.5.1).
 *
 * Implements both BuildHON (Xu, Wickramarathne & Chawla 2016) and BuildHON+
 * (Saebi et al. 2020) algorithms. The latter is the default — it lazily
 * builds higher-order observations and applies a MaxDivergence pre-check
 * to prune branches that cannot possibly exceed the KLD threshold.
 *
 * Algorithm:
 *   1. Parse trajectories (strip nulls, optional collapse_repeats).
 *   2. Build observation counts and probability distributions per source key.
 *   3. Recursively extend each first-order source. Extension is justified
 *      iff KL-divergence between the extended distribution and the current
 *      valid distribution exceeds an adaptive threshold = order/log2(1+N).
 *   4. Build the network from accepted rules. Rewire edges so higher-order
 *      nodes are properly connected (.hon_rewire and .hon_rewire_tails).
 *   5. Emit an adjacency matrix in arrow notation plus the edge list.
 */
import { Matrix } from '../core/matrix.js';
import type { SequenceData, TNA } from '../core/types.js';
import { extractTrajectories } from './markov.js';

const HON_SEP = '\x01';

export type HonInput = string[][] | SequenceData | TNA;
export type HonMethod = 'hon+' | 'hon';

export interface HonOptions {
  /** Maximum HON order (default 5). */
  maxOrder?: number;
  /** Minimum count for a transition to be retained (default 1). */
  minFreq?: number;
  /** Collapse adjacent duplicate states within each trajectory (default false). */
  collapseRepeats?: boolean;
  /** Algorithm: "hon+" (default, parameter-free with MaxDivergence pruning)
   *  or "hon" (original BuildHON with eager observation building). */
  method?: HonMethod;
}

export interface HonEdgeRow {
  /** Full state path in arrow notation (e.g. "A -> B -> C"). */
  path: string;
  /** Source context in arrow notation. */
  from: string;
  /** Predicted next state. */
  to: string;
  /** Raw observation count. */
  count: number;
  /** Transition probability. */
  probability: number;
  /** Order (length) of the source tuple. */
  fromOrder: number;
  /** Order (length) of the target tuple, after rewiring. */
  toOrder: number;
}

export interface HonResult {
  /** Adjacency matrix (rows = from, cols = to), arrow-notation labels. */
  matrix: Matrix;
  nodes: string[];
  edges: HonEdgeRow[];
  nNodes: number;
  nEdges: number;
  firstOrderStates: string[];
  maxOrderRequested: number;
  maxOrderObserved: number;
  minFreq: number;
  nTrajectories: number;
  directed: true;
  method: HonMethod;
}

/* ── Encoding helpers ─────────────────────────────────────────────── */

function honEncode(parts: string[]): string {
  return parts.join(HON_SEP);
}

function honDecode(key: string): string[] {
  return key.split(HON_SEP);
}

/** Number of state tokens in an encoded key (= number of separators + 1). */
function honKeyLen(key: string): number {
  let n = 1;
  for (let i = 0; i < key.length; i++) {
    if (key.charCodeAt(i) === 1) n++;
  }
  return n;
}

function arrowNotation(seq: string[]): string {
  return seq.join(' -> ');
}

/* ── Input parsing ────────────────────────────────────────────────── */

function honParseInput(data: HonInput, collapseRepeats: boolean): string[][] {
  let raw: string[][];
  if (Array.isArray(data) && data.length > 0 && Array.isArray(data[0])) {
    raw = (data as (string | null)[][]).map(row => {
      const out: string[] = [];
      for (const v of row) if (v !== null && v !== undefined) out.push(v as string);
      return out;
    });
  } else {
    raw = extractTrajectories(data as TNA | SequenceData);
  }
  if (collapseRepeats) {
    raw = raw.map(traj => {
      if (traj.length <= 1) return traj;
      const out: string[] = [traj[0]!];
      for (let i = 1; i < traj.length; i++) {
        if (traj[i] !== traj[i - 1]) out.push(traj[i]!);
      }
      return out;
    });
  }
  return raw.filter(t => t.length >= 2);
}

/* ── Shared types ─────────────────────────────────────────────────── */

type CountMap = Map<string, Map<string, number>>;
type DistrMap = Map<string, Map<string, number>>;
type RulesMap = Map<string, Map<string, number>>;
/** suffix → { order → set<extKey> } */
type SourceCache = Map<string, Map<number, Set<string>>>;

/* ── KL-divergence + threshold ────────────────────────────────────── */

/** sum_t a(t) * log2(a(t) / b(t)). +Inf if any a(t) > 0 has b(t) = 0. */
function honKld(a: Map<string, number>, b: Map<string, number>): number {
  if (a.size === 0) return 0;
  let div = 0;
  for (const [t, pa] of a) {
    if (pa <= 0) continue;
    const pb = b.get(t) ?? 0;
    if (pb > 0) div += pa * Math.log2(pa / pb);
    else return Infinity;
  }
  return div;
}

function honKldThreshold(newOrder: number, extSourceKey: string, count: CountMap): number {
  const c = count.get(extSourceKey);
  let total = 0;
  if (c) for (const v of c.values()) total += v;
  return newOrder / Math.log2(1 + total);
}

/* ── Eager (method = "hon") observation/distribution builders ─────── */

function honBuildObservations(trajectories: string[][], maxOrder: number): CountMap {
  const count: CountMap = new Map();
  for (const traj of trajectories) {
    const n = traj.length;
    const maxLen = Math.min(maxOrder + 1, n);
    for (let order = 2; order <= maxLen; order++) {
      const nSubs = n - order + 1;
      for (let start = 0; start < nSubs; start++) {
        const subseq = traj.slice(start, start + order);
        const target = subseq[order - 1]!;
        const sourceKey = honEncode(subseq.slice(0, -1));
        let row = count.get(sourceKey);
        if (!row) { row = new Map(); count.set(sourceKey, row); }
        row.set(target, (row.get(target) ?? 0) + 1);
      }
    }
  }
  return count;
}

function honBuildDistributions(count: CountMap, minFreq: number): DistrMap {
  const distr: DistrMap = new Map();
  for (const [sourceKey, counts] of count) {
    // Zero-out below minFreq IN PLACE — matches pyHON BuildDistributions.
    for (const [t, c] of [...counts]) {
      if (c < minFreq) counts.set(t, 0);
    }
    let total = 0;
    for (const c of counts.values()) total += c;
    const d = new Map<string, number>();
    if (total > 0) {
      for (const [t, c] of counts) if (c > 0) d.set(t, c / total);
    }
    distr.set(sourceKey, d);
  }
  return distr;
}

function honBuildSourceCache(distr: DistrMap): SourceCache {
  const cache: SourceCache = new Map();
  for (const sourceKey of distr.keys()) {
    const source = honDecode(sourceKey);
    const srcLen = source.length;
    if (srcLen <= 1) continue;
    const newOrder = srcLen;
    for (let start = 1; start < srcLen; start++) {
      const currKey = honEncode(source.slice(start));
      let orderMap = cache.get(currKey);
      if (!orderMap) { orderMap = new Map(); cache.set(currKey, orderMap); }
      let set = orderMap.get(newOrder);
      if (!set) { set = new Set(); orderMap.set(newOrder, set); }
      set.add(sourceKey);
    }
  }
  return cache;
}

function honGetExtensions(currKey: string, newOrder: number, cache: SourceCache): string[] {
  return [...(cache.get(currKey)?.get(newOrder) ?? [])];
}

function honAddToRules(sourceKey: string, distr: DistrMap, rules: RulesMap) {
  const source = honDecode(sourceKey);
  if (source.length === 0) return;
  if (!rules.has(sourceKey)) {
    const d = distr.get(sourceKey);
    if (d) rules.set(sourceKey, new Map(d));
  }
  if (source.length > 1) {
    honAddToRules(honEncode(source.slice(0, -1)), distr, rules);
  }
}

function honExtendRule(
  validKey: string, currKey: string, order: number, maxOrder: number,
  distr: DistrMap, count: CountMap, cache: SourceCache, rules: RulesMap,
) {
  if (order >= maxOrder) {
    honAddToRules(validKey, distr, rules);
    return;
  }
  const validDistr = distr.get(validKey)!;
  const newOrder = order + 1;
  const extended = honGetExtensions(currKey, newOrder, cache);
  if (extended.length === 0) {
    honAddToRules(validKey, distr, rules);
    return;
  }
  for (const extKey of extended) {
    const extDistr = distr.get(extKey);
    if (extDistr && extDistr.size > 0 &&
        honKld(extDistr, validDistr) > honKldThreshold(newOrder, extKey, count)) {
      honExtendRule(extKey, extKey, newOrder, maxOrder, distr, count, cache, rules);
    } else {
      honExtendRule(validKey, extKey, newOrder, maxOrder, distr, count, cache, rules);
    }
  }
}

function honExtractRules(
  trajectories: string[][], maxOrder: number, minFreq: number,
): { rules: RulesMap; count: CountMap } {
  const count = honBuildObservations(trajectories, maxOrder);
  const distr = honBuildDistributions(count, minFreq);
  const cache = honBuildSourceCache(distr);
  const rules: RulesMap = new Map();
  for (const sourceKey of distr.keys()) {
    if (honKeyLen(sourceKey) === 1) {
      honAddToRules(sourceKey, distr, rules);
      honExtendRule(sourceKey, sourceKey, 1, maxOrder, distr, count, cache, rules);
    }
  }
  return { rules, count };
}

/* ── HON+ lazy observation builder + MaxDivergence pruning ────────── */

interface HonPlusState {
  count: CountMap;
  distr: DistrMap;
  /** source_key → list of (trajectory_index, 0-based source position) */
  startingPoints: Map<string, [number, number][]>;
  /** suffix → set of ext keys discovered so far */
  sourceToExt: Map<string, Set<string>>;
}

function honpBuildOrder1(trajectories: string[][], minFreq: number): HonPlusState {
  const count: CountMap = new Map();
  const startingPoints = new Map<string, [number, number][]>();
  for (let ti = 0; ti < trajectories.length; ti++) {
    const traj = trajectories[ti]!;
    for (let pos = 0; pos < traj.length - 1; pos++) {
      const sourceKey = honEncode([traj[pos]!]);
      const target = traj[pos + 1]!;
      let row = count.get(sourceKey);
      if (!row) { row = new Map(); count.set(sourceKey, row); }
      row.set(target, (row.get(target) ?? 0) + 1);
      let sp = startingPoints.get(sourceKey);
      if (!sp) { sp = []; startingPoints.set(sourceKey, sp); }
      sp.push([ti, pos]);
    }
  }
  const distr: DistrMap = new Map();
  for (const [sourceKey, counts] of count) {
    for (const [t, c] of [...counts]) if (c < minFreq) counts.set(t, 0);
    let total = 0;
    for (const c of counts.values()) total += c;
    const d = new Map<string, number>();
    if (total > 0) {
      for (const [t, c] of counts) if (c > 0) d.set(t, c / total);
    }
    distr.set(sourceKey, d);
  }
  return { count, distr, startingPoints, sourceToExt: new Map() };
}

function honpExtendObservation(
  sourceKey: string, state: HonPlusState,
  trajectories: string[][], minFreq: number,
) {
  const source = honDecode(sourceKey);
  const order = source.length;
  if (order > 1) {
    const suffixKey = honEncode(source.slice(1));
    const suffixCount = state.count.get(suffixKey);
    if (!suffixCount || suffixCount.size === 0) {
      honpExtendObservation(suffixKey, state, trajectories, minFreq);
    }
  }
  const sp = state.startingPoints.get(sourceKey);
  if (!sp || sp.length === 0) return;

  const localCount = new Map<string, Map<string, number>>();
  for (const [ti, pos] of sp) {
    const traj = trajectories[ti]!;
    // Need: pos-1 is a valid index AND target traj[pos+order] exists.
    if (pos >= 1 && pos + order < traj.length) {
      const extSource = traj.slice(pos - 1, pos + order); // length order + 1
      const target = traj[pos + order]!;
      const extKey = honEncode(extSource);
      let row = localCount.get(extKey);
      if (!row) { row = new Map(); localCount.set(extKey, row); }
      row.set(target, (row.get(target) ?? 0) + 1);
      let esp = state.startingPoints.get(extKey);
      if (!esp) { esp = []; state.startingPoints.set(extKey, esp); }
      esp.push([ti, pos - 1]);
    }
  }

  for (const [extKey, lc] of localCount) {
    for (const [t, c] of [...lc]) if (c < minFreq) lc.set(t, 0);
    state.count.set(extKey, lc);
    let total = 0;
    for (const v of lc.values()) total += v;
    if (total > 0) {
      const d = new Map<string, number>();
      for (const [t, c] of lc) if (c > 0) d.set(t, c / total);
      state.distr.set(extKey, d);
      const suffixKey = honEncode(honDecode(extKey).slice(1));
      let s2e = state.sourceToExt.get(suffixKey);
      if (!s2e) { s2e = new Set(); state.sourceToExt.set(suffixKey, s2e); }
      s2e.add(extKey);
    }
  }
}

function honpExtendSourceFast(
  currKey: string, state: HonPlusState,
  trajectories: string[][], minFreq: number,
): string[] {
  let s2e = state.sourceToExt.get(currKey);
  if (!s2e) {
    honpExtendObservation(currKey, state, trajectories, minFreq);
    s2e = state.sourceToExt.get(currKey);
    if (!s2e) return [];
  }
  return [...s2e].filter(k => {
    const d = state.distr.get(k);
    return d !== undefined && d.size > 0;
  });
}

function honpAddToRules(
  sourceKey: string, state: HonPlusState, rules: RulesMap,
  trajectories: string[][], minFreq: number,
) {
  const source = honDecode(sourceKey);
  for (let ord = 1; ord <= source.length; ord++) {
    const prefix = source.slice(0, ord);
    const prefixKey = honEncode(prefix);
    const d0 = state.distr.get(prefixKey);
    if (!d0 || d0.size === 0) {
      if (ord > 1) {
        const suffixKey = honEncode(prefix.slice(1));
        honpExtendSourceFast(suffixKey, state, trajectories, minFreq);
      }
    }
    const d = state.distr.get(prefixKey);
    if (d) rules.set(prefixKey, new Map(d));
  }
}

/** Singleton distribution that places all mass on the least-probable target. */
function honpMaxDivergence(distr: Map<string, number>): Map<string, number> {
  let minTarget = '';
  let minProb = Infinity;
  for (const [t, p] of distr) {
    if (p < minProb) { minProb = p; minTarget = t; }
  }
  return new Map([[minTarget, 1.0]]);
}

function honpExtendRule(
  validKey: string, currKey: string, order: number, maxOrder: number,
  state: HonPlusState, rules: RulesMap,
  trajectories: string[][], minFreq: number,
) {
  if (order >= maxOrder) {
    honpAddToRules(validKey, state, rules, trajectories, minFreq);
    return;
  }
  const validDistr = state.distr.get(validKey)!;
  const currDistr = state.distr.get(currKey);
  if (!currDistr || currDistr.size === 0) {
    honpAddToRules(validKey, state, rules, trajectories, minFreq);
    return;
  }
  // MaxDivergence pre-check: if even the worst-case singleton from currDistr
  // can't beat the threshold, prune the entire subtree.
  const maxDiv = honpMaxDivergence(currDistr);
  if (honKld(maxDiv, validDistr) < honKldThreshold(order + 1, currKey, state.count)) {
    honpAddToRules(validKey, state, rules, trajectories, minFreq);
    return;
  }
  const newOrder = order + 1;
  const extended = honpExtendSourceFast(currKey, state, trajectories, minFreq);
  if (extended.length === 0) {
    honpAddToRules(validKey, state, rules, trajectories, minFreq);
    return;
  }
  for (const extKey of extended) {
    const extDistr = state.distr.get(extKey);
    if (extDistr && extDistr.size > 0 &&
        honKld(extDistr, validDistr) > honKldThreshold(newOrder, extKey, state.count)) {
      honpExtendRule(extKey, extKey, newOrder, maxOrder, state, rules, trajectories, minFreq);
    } else {
      honpExtendRule(validKey, extKey, newOrder, maxOrder, state, rules, trajectories, minFreq);
    }
  }
}

function honpExtractRules(
  trajectories: string[][], maxOrder: number, minFreq: number,
): { rules: RulesMap; count: CountMap } {
  const state = honpBuildOrder1(trajectories, minFreq);
  const rules: RulesMap = new Map();
  for (const sourceKey of state.distr.keys()) {
    if (honKeyLen(sourceKey) === 1) {
      honpAddToRules(sourceKey, state, rules, trajectories, minFreq);
      honpExtendRule(sourceKey, sourceKey, 1, maxOrder, state, rules, trajectories, minFreq);
    }
  }
  return { rules, count: state.count };
}

/* ── Network building (rewiring) ──────────────────────────────────── */

type Graph = Map<string, Map<string, number>>;

function honBuildNetwork(rules: RulesMap): Graph {
  const graph: Graph = new Map();
  // Sort sources by tuple length ascending (then lex for determinism so
  // .hon_rewire processing matches R's stable ordering).
  const sources = [...rules.keys()].sort((a, b) => {
    const da = honKeyLen(a), db = honKeyLen(b);
    return da - db || a.localeCompare(b);
  });
  for (const sourceKey of sources) {
    const ruleDistr = rules.get(sourceKey)!;
    if (!graph.has(sourceKey)) graph.set(sourceKey, new Map());
    for (const [target, prob] of ruleDistr) {
      const targetKey = honEncode([target]);
      graph.get(sourceKey)!.set(targetKey, prob);
      const source = honDecode(sourceKey);
      if (source.length > 1) honRewire(graph, sourceKey, targetKey);
    }
  }
  honRewireTails(graph);
  return graph;
}

/** When a higher-order source A|B is added and A had a direct edge to B,
 *  redirect: A → B becomes A → A|B. */
function honRewire(graph: Graph, sourceKey: string, _targetKey: string) {
  const source = honDecode(sourceKey);
  const prevSourceKey = honEncode(source.slice(0, -1));
  const prevTargetKey = honEncode([source[source.length - 1]!]);
  const prevGraph = graph.get(prevSourceKey);
  if (!prevGraph || prevGraph.has(sourceKey)) return;
  if (prevGraph.has(prevTargetKey)) {
    prevGraph.set(sourceKey, prevGraph.get(prevTargetKey)!);
    prevGraph.delete(prevTargetKey);
  }
}

/** For each first-order target, look for the longest existing higher-order
 *  node matching source+target's suffixes; redirect to that node. */
function honRewireTails(graph: Graph) {
  const toAdd: { source: string; target: string; weight: number }[] = [];
  const toRemove: { source: string; target: string }[] = [];
  for (const [sourceKey, sourceGraph] of graph) {
    const source = honDecode(sourceKey);
    for (const [targetKey, weight] of sourceGraph) {
      const target = honDecode(targetKey);
      if (target.length !== 1) continue;
      let newTarget = [...source, ...target];
      while (newTarget.length > 1) {
        const newTargetKey = honEncode(newTarget);
        if (graph.has(newTargetKey)) {
          toAdd.push({ source: sourceKey, target: newTargetKey, weight });
          toRemove.push({ source: sourceKey, target: targetKey });
          break;
        }
        newTarget = newTarget.slice(1);
      }
    }
  }
  for (const { source, target, weight } of toAdd) graph.get(source)!.set(target, weight);
  for (const { source, target } of toRemove) graph.get(source)!.delete(target);
}

/* ── Edge list assembly ───────────────────────────────────────────── */

function honGraphToEdgelist(graph: Graph, count: CountMap): HonEdgeRow[] {
  const rows: HonEdgeRow[] = [];
  for (const [sourceKey, sourceGraph] of graph) {
    const source = honDecode(sourceKey);
    const fromNode = arrowNotation(source);
    const fromOrder = source.length;
    for (const [targetKey, prob] of sourceGraph) {
      const target = honDecode(targetKey);
      const toOrder = target.length;
      const nextState = target[target.length - 1]!;
      const path = [...source, nextState].join(' -> ');
      let edgeCount = 0;
      const sc = count.get(sourceKey);
      if (sc) edgeCount = sc.get(nextState) ?? 0;
      rows.push({
        path, from: fromNode, to: nextState,
        count: edgeCount, probability: prob,
        fromOrder, toOrder,
      });
    }
  }
  return rows;
}

/* ── Public entry point ──────────────────────────────────────────── */

export function buildHon(data: HonInput, options: HonOptions = {}): HonResult {
  const { maxOrder = 5, minFreq = 1, collapseRepeats = false, method = 'hon+' } = options;
  if (!(maxOrder >= 1)) throw new Error("'maxOrder' must be >= 1");
  if (!(minFreq >= 1)) throw new Error("'minFreq' must be >= 1");
  if (method !== 'hon' && method !== 'hon+') {
    throw new Error("'method' must be 'hon' or 'hon+'");
  }

  const trajectories = honParseInput(data, collapseRepeats);
  if (trajectories.length === 0) {
    throw new Error('No valid trajectories (each must have at least 2 states)');
  }

  const { rules, count } = method === 'hon+'
    ? honpExtractRules(trajectories, maxOrder, minFreq)
    : honExtractRules(trajectories, maxOrder, minFreq);

  const graph = honBuildNetwork(rules);
  const edges = honGraphToEdgelist(graph, count);

  // Collect all node names from the graph (sources + targets).
  const allNodes = new Set<string>();
  for (const [sourceKey, sourceGraph] of graph) {
    allNodes.add(arrowNotation(honDecode(sourceKey)));
    for (const targetKey of sourceGraph.keys()) {
      allNodes.add(arrowNotation(honDecode(targetKey)));
    }
  }
  const nodes = [...allNodes].sort();
  const n = nodes.length;
  const idx = new Map<string, number>();
  for (let i = 0; i < n; i++) idx.set(nodes[i]!, i);

  const matrix = new Matrix(n, n);
  for (const [sourceKey, sourceGraph] of graph) {
    const r = idx.get(arrowNotation(honDecode(sourceKey)))!;
    for (const [targetKey, w] of sourceGraph) {
      const c = idx.get(arrowNotation(honDecode(targetKey)))!;
      matrix.set(r, c, w);
    }
  }

  const stateSet = new Set<string>();
  for (const traj of trajectories) for (const s of traj) stateSet.add(s);
  const firstOrderStates = [...stateSet].sort();

  let maxObserved = 1;
  for (const k of rules.keys()) maxObserved = Math.max(maxObserved, honKeyLen(k));

  return {
    matrix,
    nodes,
    edges,
    nNodes: n,
    nEdges: edges.length,
    firstOrderStates,
    maxOrderRequested: maxOrder,
    maxOrderObserved: maxObserved,
    minFreq,
    nTrajectories: trajectories.length,
    directed: true,
    method,
  };
}
