/**
 * Multi-Order Generative Model (MOGen) — port of Nestimate::build_mogen,
 * mogen_transitions, path_counts, state_frequencies (R/mogen.R, 0.5.1).
 *
 * Implements multi-order De Bruijn graph models for sequential data
 * (Scholtes 2017; Gote & Scholtes 2023).
 *
 * At order k, nodes are k-tuples of states from trajectories and edges
 * connect consecutive (overlapping by k-1) k-tuples. The model builds
 * order-0 (marginal) up to order-K layers, computes log-likelihood,
 * AIC, BIC at each order, and selects the optimal Markov order via the
 * chosen information criterion (AIC, BIC, or sequential LRT).
 */
import { Matrix } from '../core/matrix.js';
import type { SequenceData, TNA } from '../core/types.js';
import {
  extractTrajectories,
  kgramCounts,
  layerDof,
  logLikelihood,
  marginalDistribution,
  pchisqUpper,
  transitionMatrixFromKgrams,
} from './markov.js';

const HON_SEP = '\x01';

export type MogenInput = string[][] | SequenceData | TNA;
export type MogenCriterion = 'aic' | 'bic' | 'lrt';

export interface MogenOptions {
  maxOrder?: number;       // default 5
  criterion?: MogenCriterion; // default "aic"
  lrtAlpha?: number;       // default 0.01
}

export interface MogenResult {
  optimalOrder: number;
  criterion: MogenCriterion;
  orders: number[];                 // 0..maxOrder
  aic: number[];                    // length maxOrder + 1
  bic: number[];
  logLikelihood: number[];
  dof: number[];                    // cumulative
  layerDof: number[];               // per-layer
  /** transitionMatrices[0] is a 1×nStates Matrix of the order-0 marginal,
   *  transitionMatrices[k] (k ≥ 1) is the order-k k-gram transition matrix. */
  transitionMatrices: Matrix[];
  /** countMatrices[k] (k ≥ 1) is the raw k-gram count matrix at order k.
   *  Index 0 is unused (we keep alignment with transitionMatrices). */
  countMatrices: Matrix[];
  /** Per-order node labels (k-grams as HON_SEP-joined strings).
   *  transitionNodes[0] = first-order state labels (the marginal columns). */
  transitionNodes: string[][];
  states: string[];
  nPaths: number;
  nObservations: number;
}

export interface MogenTransitionRow {
  path: string;
  count: number;
  probability: number; // rounded to 4 decimals to match R
  from: string;
  to: string;
}

export interface PathCountRow {
  path: string;
  count: number;
  proportion: number;
}

export interface StateFrequencyRow {
  state: string;
  count: number;
  proportion: number;
}

/* ── input coercion ─────────────────────────────────────────────────── */

function inputToTrajectories(data: MogenInput): string[][] {
  if (Array.isArray(data) && data.length > 0 && Array.isArray(data[0])) {
    // Already string[][] but possibly with null cells (SequenceData shape).
    const out: string[][] = [];
    for (const row of data as (string | null)[][]) {
      const cleaned: string[] = [];
      for (const v of row) if (v !== null && v !== undefined) cleaned.push(v as string);
      if (cleaned.length >= 2) out.push(cleaned);
    }
    return out;
  }
  return extractTrajectories(data as TNA | SequenceData);
}

/* ── R-compat rounding ─────────────────────────────────────────────── */

/** R-style round-half-to-even at `digits` decimal places, matching the
 *  IEEE 754 banker's rounding R uses for `round(x, d)`. */
function roundR(x: number, digits: number): number {
  if (!Number.isFinite(x)) return x;
  const m = Math.pow(10, digits);
  const v = x * m;
  const r = Math.round(v);
  // IEEE-754 ties-to-even adjustment: if v is exactly half-integer and
  // round() bumped it the wrong way, correct.
  if (Math.abs(v - Math.trunc(v) - 0.5) < 1e-9) {
    const t = Math.trunc(v);
    const evenAdj = t % 2 === 0 ? t : t + Math.sign(v);
    return evenAdj / m;
  }
  return r / m;
}

/* ── build_mogen ─────────────────────────────────────────────────────── */

export function buildMogen(data: MogenInput, options: MogenOptions = {}): MogenResult {
  const { criterion = 'aic', lrtAlpha = 0.01 } = options;
  let maxOrder = options.maxOrder ?? 5;
  if (!(lrtAlpha > 0 && lrtAlpha < 1)) {
    throw new Error("'lrtAlpha' must be in (0, 1)");
  }
  if (!(maxOrder >= 1)) throw new Error("'maxOrder' must be >= 1");

  const trajectories = inputToTrajectories(data);
  if (trajectories.length === 0) {
    throw new Error('No valid trajectories (each must have at least 2 states)');
  }

  const maxPathLen = trajectories.reduce((m, t) => Math.max(m, t.length), 0);
  if (maxOrder >= maxPathLen) maxOrder = maxPathLen - 1;

  const nObs = trajectories.reduce((s, t) => s + t.length, 0);

  // Order 0: marginal
  const { states, probs } = marginalDistribution(trajectories);
  // Wrap as 1×nStates Matrix so the existing logLikelihood signature works.
  const p0Mat = new Matrix(1, states.length);
  for (let i = 0; i < states.length; i++) p0Mat.set(0, i, probs[i]!);

  const transMats: Matrix[] = new Array(maxOrder + 1);
  const countMats: Matrix[] = new Array(maxOrder + 1);
  const transNodes: string[][] = new Array(maxOrder + 1);
  const layerDofs: number[] = new Array(maxOrder + 1).fill(0);

  transMats[0] = p0Mat;
  // Index 0 of countMats is unused at the matrix level (R stores marginal*N
  // there; we don't need it for AIC/BIC). Keep a 0×0 placeholder for shape.
  countMats[0] = new Matrix(0, 0);
  transNodes[0] = states;
  layerDofs[0] = states.length - 1;

  for (let k = 1; k <= maxOrder; k++) {
    const kg = kgramCounts(trajectories, k);
    const tm = transitionMatrixFromKgrams(kg.nodes, kg.edges);
    // Raw count matrix
    const n = kg.nodes.length;
    const cm = new Matrix(n, n);
    const idx = new Map<string, number>();
    for (let i = 0; i < n; i++) idx.set(kg.nodes[i]!, i);
    for (const e of kg.edges) {
      const r = idx.get(e.from);
      const c = idx.get(e.to);
      if (r !== undefined && c !== undefined) cm.set(r, c, e.weight);
    }
    transMats[k] = tm;
    countMats[k] = cm;
    transNodes[k] = kg.nodes;
    layerDofs[k] = layerDof(tm);
  }

  // Cumulative DOF
  const cumDofs: number[] = new Array(maxOrder + 1);
  let acc = 0;
  for (let k = 0; k <= maxOrder; k++) {
    acc += layerDofs[k]!;
    cumDofs[k] = acc;
  }

  // Per-order log-likelihoods
  const logliks: number[] = new Array(maxOrder + 1);
  for (let k = 0; k <= maxOrder; k++) {
    logliks[k] = logLikelihood(
      trajectories,
      k,
      transMats.slice(0, k + 1),
      transNodes.slice(0, k + 1),
    );
  }

  // Information criteria
  const aics: number[] = new Array(maxOrder + 1);
  const bics: number[] = new Array(maxOrder + 1);
  const logN = Math.log(nObs);
  for (let k = 0; k <= maxOrder; k++) {
    aics[k] = 2 * cumDofs[k]! - 2 * logliks[k]!;
    bics[k] = logN * cumDofs[k]! - 2 * logliks[k]!;
  }

  // Optimal order
  let optimalOrder = 0;
  if (criterion === 'aic') {
    let best = aics[0]!;
    for (let k = 1; k <= maxOrder; k++) {
      if (aics[k]! < best) { best = aics[k]!; optimalOrder = k; }
    }
  } else if (criterion === 'bic') {
    let best = bics[0]!;
    for (let k = 1; k <= maxOrder; k++) {
      if (bics[k]! < best) { best = bics[k]!; optimalOrder = k; }
    }
  } else {
    // Sequential LRT: increase k while p < alpha.
    optimalOrder = 0;
    for (let k = 1; k <= maxOrder; k++) {
      const x = -2 * (logliks[k - 1]! - logliks[k]!);
      const dfDiff = layerDofs[k]!;
      if (dfDiff > 0 && x > 0) {
        const p = pchisqUpper(x, dfDiff);
        if (p < lrtAlpha) optimalOrder = k;
        else break;
      } else {
        break;
      }
    }
  }

  const orders: number[] = [];
  for (let k = 0; k <= maxOrder; k++) orders.push(k);

  return {
    optimalOrder,
    criterion,
    orders,
    aic: aics,
    bic: bics,
    logLikelihood: logliks,
    dof: cumDofs,
    layerDof: layerDofs,
    transitionMatrices: transMats,
    countMatrices: countMats,
    transitionNodes: transNodes,
    states,
    nPaths: trajectories.length,
    nObservations: nObs,
  };
}

/* ── mogen_transitions ─────────────────────────────────────────────── */

export function mogenTransitions(
  mg: MogenResult,
  options: { order?: number; minCount?: number } = {},
): MogenTransitionRow[] {
  const order = options.order ?? mg.optimalOrder;
  const minCount = options.minCount ?? 1;
  if (order < 1) throw new Error("'order' must be >= 1");
  if (order > mg.orders[mg.orders.length - 1]!) {
    throw new Error("'order' exceeds max tested order");
  }

  const tm = mg.transitionMatrices[order]!;
  const cm = mg.countMatrices[order]!;
  const nodes = mg.transitionNodes[order]!;

  const rows: MogenTransitionRow[] = [];
  for (let i = 0; i < tm.rows; i++) {
    for (let j = 0; j < tm.cols; j++) {
      const c = cm.get(i, j);
      if (c < minCount) continue;
      const fromParts = nodes[i]!.split(HON_SEP);
      const toParts = nodes[j]!.split(HON_SEP);
      const nextState = toParts[toParts.length - 1]!;
      rows.push({
        path: [...fromParts, nextState].join(' -> '),
        count: c,
        probability: roundR(tm.get(i, j), 4),
        from: fromParts.join(' -> '),
        to: nextState,
      });
    }
  }

  rows.sort((a, b) => b.count - a.count);
  return rows;
}

/* ── path_counts ────────────────────────────────────────────────────── */

export function pathCounts(
  data: MogenInput,
  k = 2,
  top?: number,
): PathCountRow[] {
  if (k < 2) throw new Error("'k' must be >= 2");
  const trajectories = inputToTrajectories(data);

  // Count k-grams using " -> " as separator (R uses this in path_counts).
  const counts = new Map<string, number>();
  for (const traj of trajectories) {
    const n = traj.length;
    if (n < k) continue;
    for (let i = 0; i + k <= n; i++) {
      const key = traj.slice(i, i + k).join(' -> ');
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }
  const total = Array.from(counts.values()).reduce((s, v) => s + v, 0);
  const rows: PathCountRow[] = [];
  for (const [path, count] of counts) {
    rows.push({
      path,
      count,
      proportion: total > 0 ? roundR(count / total, 4) : 0,
    });
  }
  rows.sort((a, b) => b.count - a.count || a.path.localeCompare(b.path));
  if (top !== undefined && top >= 0) return rows.slice(0, top);
  return rows;
}

/* ── state_frequencies ──────────────────────────────────────────────── */

export function stateFrequencies(data: MogenInput): StateFrequencyRow[] {
  const trajectories = inputToTrajectories(data);
  const counts = new Map<string, number>();
  let total = 0;
  for (const traj of trajectories) {
    for (const s of traj) {
      counts.set(s, (counts.get(s) ?? 0) + 1);
      total++;
    }
  }
  const rows: StateFrequencyRow[] = [];
  for (const [state, count] of counts) {
    rows.push({
      state,
      count,
      proportion: total > 0 ? roundR(count / total, 4) : 0,
    });
  }
  rows.sort((a, b) => b.count - a.count || a.state.localeCompare(b.state));
  return rows;
}
