/**
 * Markov-chain diagnostic suite — ports of Nestimate's transition_entropy
 * (R/transition_entropy.R) and chain_structure (R/chain_structure.R).
 *
 * - `transitionEntropy` returns the Shannon row entropies, the stationary
 *   distribution, the entropy rate h(P) = Σ πᵢ H(P_{i·}), the redundancy
 *   H(π) − h(P), and their normalised forms.
 * - `chainStructure` returns the qualitative shape of the chain: state
 *   classification (absorbing / recurrent / transient), communicating classes
 *   (SCCs of the support graph), per-recurrent-class period (gcd of return
 *   times), hitting-probability matrix, and absorption analysis (fundamental
 *   matrix N = (I − Q)⁻¹).
 *
 * Both expose a flexible input — Matrix, number[][], or TNA — and follow R's
 * default behaviour of renormalising rows that don't sum to 1 (with a
 * `normalize` toggle to match the R signature). Stationary distributions are
 * obtained via tnaj's existing `eigenDominantLeft` (matches R's
 * `.mpt_stationary`).
 *
 * Verified against Nestimate ≥ 0.5.7.
 */
import { Matrix } from '../core/matrix.js';
import { eigenDominantLeft, solveLinear } from '../core/linalg.js';
import type { TNA } from '../core/types.js';

export type DiagnosticsInput = Matrix | number[][] | TNA;

/* ── matrix extraction ─────────────────────────────────────────────── */

function extractTransitionMatrix(x: DiagnosticsInput): { P: Matrix; labels: string[] } {
  if (x instanceof Matrix) {
    if (!x.isSquare) throw new Error('transitionMatrix: must be square');
    const n = x.rows;
    return { P: x.clone(), labels: Array.from({ length: n }, (_, i) => `S${i + 1}`) };
  }
  if (Array.isArray(x)) {
    const P = Matrix.from2D(x);
    if (!P.isSquare) throw new Error('transitionMatrix: must be square');
    const n = P.rows;
    return { P, labels: Array.from({ length: n }, (_, i) => `S${i + 1}`) };
  }
  const tna = x as TNA;
  if (!tna.weights || !(tna.weights instanceof Matrix)) {
    throw new Error('transitionMatrix: TNA has no weight matrix');
  }
  const labels = tna.labels && tna.labels.length === tna.weights.rows
    ? tna.labels.slice()
    : Array.from({ length: tna.weights.rows }, (_, i) => `S${i + 1}`);
  return { P: tna.weights.clone(), labels };
}

/** R's `.mpt_normalize_rows`: row-normalise unless any row is all-zero. */
function normalizeRows(P: Matrix, labels: string[], normalize: boolean): Matrix {
  const n = P.rows;
  for (let i = 0; i < n; i++) {
    let sum = 0;
    for (let j = 0; j < n; j++) sum += P.get(i, j);
    if (sum <= 0) {
      throw new Error(
        `Transition matrix has zero-sum row(s) for state(s): ${labels[i]}. ` +
        'These states have no outgoing transitions, so the chain is not ergodic.',
      );
    }
    if (Math.abs(sum - 1) > 1e-6) {
      if (!normalize) throw new Error('Transition matrix rows must sum to 1.');
      for (let j = 0; j < n; j++) P.set(i, j, P.get(i, j) / sum);
    }
  }
  return P;
}

/* ────────────────────────────────────────────────────────────────────
 * Transition entropy
 * ──────────────────────────────────────────────────────────────────── */

export interface TransitionEntropyOptions {
  /** Logarithm base. 2 = bits (default), Math.E = nats, 10 = hartleys. */
  base?: number;
  /** Renormalise rows that don't sum to 1. Default true. */
  normalize?: boolean;
}

export interface TransitionEntropy {
  /** Per-state branching entropy H(P_{i·}) = −Σⱼ Pᵢⱼ log Pᵢⱼ. */
  rowEntropy: number[];
  /** rowEntropy[i] / log_b(n). In [0,1]; all zeros when n = 1. */
  rowEntropyNorm: number[];
  /** Stationary distribution π. */
  stationary: number[];
  /** H(π) treated as an i.i.d. distribution. */
  stationaryEntropy: number;
  /** stationaryEntropy / log_b(n). */
  stationaryEntropyNorm: number;
  /** Entropy rate h(P) = Σᵢ πᵢ H(P_{i·}) — the Shannon-McMillan-Breiman per-step uncertainty. */
  entropyRate: number;
  /** entropyRate / log_b(n). */
  entropyRateNorm: number;
  /** H(π) − h(P), the order-1 memory deficit. Zero for an i.i.d. chain. */
  redundancy: number;
  /** Relative redundancy (H(π) − h(P)) / H(π). 0 when H(π) = 0. */
  redundancyNorm: number;
  /** log_b(n). The normalisation ceiling. */
  maxEntropy: number;
  base: number;
  /** State labels aligned with rowEntropy / stationary. */
  states: string[];
}

function entropyOfRow(row: number[], base: number): number {
  let h = 0;
  for (const p of row) {
    if (p > 0) h -= p * Math.log(p) / Math.log(base);
  }
  return h;
}

/** Reducible-chain stationary fallback that matches R's eigen-decomp behaviour.
 *  Identifies the first closed strongly-connected component of the support
 *  graph (lowest min vertex index), solves the stationary equation on that
 *  block, embeds back with zeros for non-block states. This mirrors R's
 *  `eigen(t(P))` + `which.min(abs(Re(values) - 1))` which on a
 *  block-diagonal matrix returns the first block's stationary vector. */
function stationaryReducibleFallback(P: Matrix, n: number): number[] {
  // Support graph.
  const adj: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (P.get(i, j) > 0) adj[i]![j] = true;
  }
  // Boolean reachability via repeated multiplication.
  let R: boolean[][] = adj.map(row => row.slice());
  for (let k = 0; k < n - 1; k++) {
    const next: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
    let changed = false;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        let v = R[i]![j]!;
        if (!v) {
          for (let m = 0; m < n; m++) {
            if (R[i]![m] && adj[m]![j]) { v = true; break; }
          }
        }
        if (v && !R[i]![j]) changed = true;
        next[i]![j] = v;
      }
    }
    R = next;
    if (!changed) break;
  }
  for (let i = 0; i < n; i++) R[i]![i] = true;
  // SCCs via mutual reachability.
  const used = new Array<boolean>(n).fill(false);
  const sccs: number[][] = [];
  for (let i = 0; i < n; i++) {
    if (used[i]) continue;
    const cls: number[] = [];
    for (let j = 0; j < n; j++) {
      if (!used[j] && R[i]![j] && R[j]![i]) { cls.push(j); used[j] = true; }
    }
    if (cls.length > 0) sccs.push(cls);
  }
  // Closed = no edges leaving the SCC.
  const closed = sccs.filter(cls => {
    const inCls = new Set(cls);
    for (const i of cls) {
      for (let j = 0; j < n; j++) {
        if (!inCls.has(j) && adj[i]![j]) return false;
      }
    }
    return true;
  });
  // R's eigen on a block-diagonal Pᵀ returns blocks in row-order of P, so
  // pick the closed class with the lowest min vertex index.
  closed.sort((a, b) => Math.min(...a) - Math.min(...b));
  const block = closed[0] ?? sccs[0]!;
  // Solve stationary on the submatrix via closed-form (I − Pᵀ_sub + 1/k·J)·π_sub = 1/k.
  const k = block.length;
  const A = new Matrix(k, k);
  const invK = 1 / k;
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) {
    A.set(i, j, (i === j ? 1 : 0) - P.get(block[j]!, block[i]!) + invK);
  }
  const rhs = new Float64Array(k);
  for (let i = 0; i < k; i++) rhs[i] = invK;
  let piSub: number[];
  try {
    const sol = solveLinear(A, rhs);
    piSub = new Array<number>(k);
    let sum = 0;
    for (let i = 0; i < k; i++) {
      const v = Math.abs(sol.get(i, 0));
      piSub[i] = v;
      sum += v;
    }
    for (let i = 0; i < k; i++) piSub[i] = piSub[i]! / sum;
  } catch (_e) {
    // Truly degenerate (e.g. periodic single-state class) — uniform.
    piSub = new Array<number>(k).fill(1 / k);
  }
  // Embed back with zeros.
  const pi = new Array<number>(n).fill(0);
  for (let i = 0; i < k; i++) pi[block[i]!] = piSub[i]!;
  return pi;
}

export function transitionEntropy(
  x: DiagnosticsInput,
  options: TransitionEntropyOptions = {},
): TransitionEntropy {
  const { base = 2, normalize = true } = options;
  if (!Number.isFinite(base) || base <= 0 || base === 1) {
    throw new Error('transitionEntropy: base must be positive and != 1');
  }
  const { P: P0, labels } = extractTransitionMatrix(x);
  const P = normalizeRows(P0, labels, normalize);
  const n = P.rows;

  // Stationary distribution. R's `.mpt_stationary` returns *some* stationary
  // even for non-irreducible chains by picking the eigenvalue-1 eigenvector
  // closest in numerical sense. tnaj's `eigenDominantLeft` uses a closed-form
  // linear solve that's faster but singular on reducible chains — fall back
  // to power iteration on Pᵀ starting from uniform, which converges to one
  // valid stationary distribution.
  let pi: number[];
  try {
    pi = Array.from(eigenDominantLeft(P));
  } catch (_e) {
    pi = stationaryReducibleFallback(P, n);
  }
  // R: warning + clamp + renormalise when any entry ≤ 0.
  let needsRenorm = false;
  for (let i = 0; i < n; i++) {
    if (pi[i]! <= 0) { pi[i] = Number.EPSILON; needsRenorm = true; }
  }
  if (needsRenorm) {
    const s = pi.reduce((a, b) => a + b, 0);
    for (let i = 0; i < n; i++) pi[i]! /= s;
  }

  const rowEntropy = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) row.push(P.get(i, j));
    rowEntropy[i] = entropyOfRow(row, base);
  }

  // H(π) treats π as i.i.d.
  const stationaryEntropy = entropyOfRow(pi, base);
  // Entropy rate
  let entropyRate = 0;
  for (let i = 0; i < n; i++) entropyRate += pi[i]! * rowEntropy[i]!;

  const maxEntropy = n > 0 ? Math.log(n) / Math.log(base) : 0;
  const norm = (v: number): number => (maxEntropy > 0 ? v / maxEntropy : 0);
  const rowEntropyNorm = rowEntropy.map(norm);
  const stationaryEntropyNorm = norm(stationaryEntropy);
  const entropyRateNorm = norm(entropyRate);
  const redundancy = stationaryEntropy - entropyRate;
  const redundancyNorm = stationaryEntropy > 0 ? redundancy / stationaryEntropy : 0;

  return {
    rowEntropy, rowEntropyNorm,
    stationary: pi,
    stationaryEntropy, stationaryEntropyNorm,
    entropyRate, entropyRateNorm,
    redundancy, redundancyNorm,
    maxEntropy, base, states: labels,
  };
}

/* ────────────────────────────────────────────────────────────────────
 * Chain structure
 * ──────────────────────────────────────────────────────────────────── */

export type StateClassification = 'absorbing' | 'recurrent' | 'transient';

export interface ChainStructureOptions {
  /** Renormalise rows that don't sum to 1. Default true. */
  normalize?: boolean;
  /** Tolerance for support-graph edges + reversibility check. Default 1e-10.
   *  Does NOT relax the absorbing test (always sqrt(eps)). */
  tol?: number;
}

export interface ChainStructure {
  states: string[];
  /** Per-state classification, aligned with `states`. */
  classification: StateClassification[];
  /** Strongly connected components of the support graph (vertex-name vectors). */
  communicatingClasses: string[][];
  /** Subset of communicatingClasses that are closed (no outgoing edges). */
  recurrentClasses: string[][];
  /** Subset that are open. */
  transientClasses: string[][];
  /** States with P[i,i] = 1 (to sqrt(eps)). */
  absorbingStates: string[];
  /** Per-state period; null for transient states. */
  period: (number | null)[];
  isIrreducible: boolean;
  isAperiodic: boolean;
  isRegular: boolean;
  /** Detailed-balance check vs. stationary; null for non-irreducible chains. */
  isReversible: boolean | null;
  /** n×n matrix, [i,j] = P(ever reach j | start i). Diagonal = return probability. */
  hittingProbabilities: Matrix;
  /** Per-transient-state absorption probabilities (n_transient × n_absorbing), or null. */
  absorptionProbabilities: Matrix | null;
  /** Mean steps to absorption per transient state, or null. */
  meanAbsorptionTime: number[] | null;
  /** Possibly-renormalised transition matrix actually used. */
  P: Matrix;
}

function supportGraph(P: Matrix, tol: number): boolean[][] {
  const n = P.rows;
  const adj: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (P.get(i, j) > tol) adj[i]![j] = true;
  }
  return adj;
}

/** Reachability via repeated boolean matrix multiplication. O(n^4) but n small. */
function reachability(adj: boolean[][]): boolean[][] {
  const n = adj.length;
  // R[i][j] = path of length ≥ 1 from i to j.
  let R: boolean[][] = adj.map(row => row.slice());
  for (let k = 0; k < n - 1; k++) {
    const next: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
    let changed = false;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (R[i]![j]) { next[i]![j] = true; continue; }
        // R[i][j] OR (R[i] · A)[j]
        let v = false;
        for (let m = 0; m < n; m++) {
          if (R[i]![m] && adj[m]![j]) { v = true; break; }
        }
        if (v) { next[i]![j] = true; changed = true; }
        else if (R[i]![j]) { next[i]![j] = true; }
      }
    }
    if (!changed) { R = next; break; }
    R = next;
  }
  return R;
}

/** Strongly-connected components via reachability AND its transpose. */
function stronglyConnectedComponents(adj: boolean[][]): number[][] {
  const n = adj.length;
  if (n === 0) return [];
  const R = reachability(adj);
  // Self-loop convention: a state is reachable from itself (matches R's `diag(R) <- 1L`).
  for (let i = 0; i < n; i++) R[i]![i] = true;
  const sameClass: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (R[i]![j] && R[j]![i]) sameClass[i]![j] = true;
  }
  // Each row of sameClass is a fingerprint identifying the component.
  const keyToIdx = new Map<string, number>();
  const classes: number[][] = [];
  for (let i = 0; i < n; i++) {
    let key = '';
    for (let j = 0; j < n; j++) key += sameClass[i]![j] ? '1' : '0';
    let idx = keyToIdx.get(key);
    if (idx === undefined) { idx = classes.length; classes.push([]); keyToIdx.set(key, idx); }
    classes[idx]!.push(i);
  }
  return classes;
}

function gcdAll(values: number[]): number {
  const xs = values.filter(v => v > 0);
  if (xs.length === 0) return NaN;
  const gcd2 = (a: number, b: number): number => {
    while (b !== 0) { const t = a % b; a = b; b = t; }
    return a;
  };
  let g = xs[0]!;
  for (let i = 1; i < xs.length; i++) { g = gcd2(g, xs[i]!); if (g === 1) return 1; }
  return g;
}

/** Period of a recurrent class given its boolean adjacency submatrix.
 *  Period = gcd of n ≥ 1 such that P^n[i,i] > 0. Matches R's .cs_class_period. */
function classPeriod(adjSub: boolean[][]): number {
  const n = adjSub.length;
  if (n === 0) return NaN;
  if (n === 1) return adjSub[0]![0] ? 1 : NaN;
  // Boolean matrix-multiply: M_new = M · A.
  const bmul = (A: boolean[][], B: boolean[][]): boolean[][] => {
    const out: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      for (let k = 0; k < n; k++) {
        if (A[i]![k] && B[k]![j]) { out[i]![j] = true; break; }
      }
    }
    return out;
  };
  let running = adjSub.map(row => row.slice());
  const cycleLengths: number[] = [];
  // Step length 1: any self-loop?
  let anyDiag = false;
  for (let i = 0; i < n; i++) if (running[i]![i]) { anyDiag = true; break; }
  if (anyDiag) cycleLengths.push(1);
  for (let k = 2; k <= 2 * n; k++) {
    running = bmul(running, adjSub);
    anyDiag = false;
    for (let i = 0; i < n; i++) if (running[i]![i]) { anyDiag = true; break; }
    if (anyDiag) {
      cycleLengths.push(k);
      if (cycleLengths.length >= 3 && gcdAll(cycleLengths) === 1) break;
    }
  }
  return gcdAll(cycleLengths);
}

/** Hitting-probability matrix H[i,j] = P(T_j < ∞ | X₀ = i), with T_j the first
 *  ARRIVAL time at j (return-time convention on diagonal: H[j,j] from k≥1). */
function hittingProbabilities(P: Matrix, reach: boolean[][]): Matrix {
  const n = P.rows;
  const H = new Matrix(n, n);
  for (let j = 0; j < n; j++) {
    if (n === 1) {
      H.set(0, 0, P.get(0, 0) > 0 ? 1 : 0);
      continue;
    }
    // Off-diagonal hit-j system: for states i ≠ j that can reach j, solve
    //   h_i = P[i,j] + Σ_{k≠j} P[i,k] · h_k
    // i.e. (I − P_sub) · h = P[·, j] where the submatrix excludes column j.
    const canReach: number[] = [];
    for (let i = 0; i < n; i++) {
      if (i !== j && reach[i]![j]) canReach.push(i);
    }
    if (canReach.length === 0) continue;
    const sz = canReach.length;
    const A = new Matrix(sz, sz);
    const b = new Float64Array(sz);
    for (let a = 0; a < sz; a++) {
      for (let bIdx = 0; bIdx < sz; bIdx++) {
        const i = canReach[a]!, k = canReach[bIdx]!;
        A.set(a, bIdx, (a === bIdx ? 1 : 0) - P.get(i, k));
      }
      b[a] = P.get(canReach[a]!, j);
    }
    try {
      const sol = solveLinear(A, b);
      for (let a = 0; a < sz; a++) H.set(canReach[a]!, j, sol.get(a, 0));
    } catch (_e) {
      // Singular — leave as 0 (R's `error = function(e) rep(NA_real_, ...)` path).
    }
  }
  // Diagonal: H[j,j] = P[j,j] + Σ_{k≠j} P[j,k] · H[k,j].
  for (let j = 0; j < n; j++) {
    let v = P.get(j, j);
    for (let k = 0; k < n; k++) if (k !== j) v += P.get(j, k) * H.get(k, j);
    H.set(j, j, v);
  }
  // Clamp to [0, 1].
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const v = H.get(i, j);
    if (Number.isFinite(v)) H.set(i, j, Math.min(Math.max(v, 0), 1));
  }
  return H;
}

/** Absorption fundamental matrix N = (I − Q)⁻¹ on the transient submatrix. */
function absorptionAnalysis(
  P: Matrix, transientIdx: number[], absorbingIdx: number[], labels: string[],
): { probabilities: Matrix | null; meanTime: number[] | null } {
  if (absorbingIdx.length === 0 || transientIdx.length === 0) {
    return { probabilities: null, meanTime: null };
  }
  const t = transientIdx.length, a = absorbingIdx.length;
  const IQ = new Matrix(t, t);
  for (let i = 0; i < t; i++) for (let j = 0; j < t; j++) {
    IQ.set(i, j, (i === j ? 1 : 0) - P.get(transientIdx[i]!, transientIdx[j]!));
  }
  const R = new Matrix(t, a);
  for (let i = 0; i < t; i++) for (let j = 0; j < a; j++) {
    R.set(i, j, P.get(transientIdx[i]!, absorbingIdx[j]!));
  }
  let probabilities: Matrix; let meanTime: number[];
  try {
    // Solve (I − Q) · N = I (n_transient cols) by passing identity as rhs.
    const I = new Matrix(t, t);
    for (let i = 0; i < t; i++) I.set(i, i, 1);
    const N = solveLinear(IQ, I);
    // probabilities = N · R
    probabilities = new Matrix(t, a);
    for (let i = 0; i < t; i++) for (let j = 0; j < a; j++) {
      let s = 0;
      for (let k = 0; k < t; k++) s += N.get(i, k) * R.get(k, j);
      probabilities.set(i, j, s);
    }
    // mean time = N · 1
    meanTime = new Array<number>(t);
    for (let i = 0; i < t; i++) {
      let s = 0;
      for (let k = 0; k < t; k++) s += N.get(i, k);
      meanTime[i] = s;
    }
  } catch (_e) {
    return { probabilities: null, meanTime: null };
  }
  // Attach row/col labels via a parallel object — labels live alongside in tnaj-friendly form.
  // The Matrix has no label fields, so we return the matrix shape; callers can map indices.
  void labels;
  return { probabilities, meanTime };
}

export function chainStructure(
  x: DiagnosticsInput,
  options: ChainStructureOptions = {},
): ChainStructure {
  const { normalize = true, tol = 1e-10 } = options;
  const { P: P0, labels } = extractTransitionMatrix(x);
  const P = normalizeRows(P0, labels, normalize);
  const n = P.rows;

  const adj = supportGraph(P, tol);
  const classes = stronglyConnectedComponents(adj);

  // Closed classes (recurrent) — no outgoing edges to outside the class.
  const isClosed = classes.map(cls => {
    if (cls.length === n) return true;
    const inCls = new Set(cls);
    for (const i of cls) {
      for (let j = 0; j < n; j++) {
        if (!inCls.has(j) && adj[i]![j]) return false;
      }
    }
    return true;
  });
  const recurrentClasses = classes.filter((_, i) => isClosed[i]);
  const transientClasses = classes.filter((_, i) => !isClosed[i]);
  const recurrentIdx = recurrentClasses.flat().sort((a, b) => a - b);
  const transientIdx = transientClasses.flat().sort((a, b) => a - b);

  // Absorbing test uses fixed sqrt(eps), independent of `tol`.
  const absorbingTol = Math.sqrt(Number.EPSILON);
  const absorbingIdx: number[] = [];
  for (let i = 0; i < n; i++) {
    if (Math.abs(P.get(i, i) - 1) < absorbingTol) absorbingIdx.push(i);
  }

  const classification: StateClassification[] = new Array(n);
  for (const i of recurrentIdx) classification[i] = 'recurrent';
  for (const i of transientIdx) classification[i] = 'transient';
  for (const i of absorbingIdx) classification[i] = 'absorbing';

  // Period per state (null for transient).
  const period: (number | null)[] = new Array(n).fill(null);
  for (const cls of recurrentClasses) {
    const sz = cls.length;
    const sub: boolean[][] = Array.from({ length: sz }, () => new Array<boolean>(sz).fill(false));
    for (let a = 0; a < sz; a++) for (let b = 0; b < sz; b++) sub[a]![b] = adj[cls[a]!]![cls[b]!]!;
    const p = classPeriod(sub);
    for (const i of cls) period[i] = Number.isFinite(p) ? p : null;
  }

  const isIrreducible = classes.length === 1;
  const isAperiodic = recurrentClasses.length > 0
    && recurrentIdx.every(i => period[i] === 1);
  const isRegular = isIrreducible && isAperiodic;

  let isReversible: boolean | null = null;
  if (isIrreducible) {
    try {
      const pi = eigenDominantLeft(P);
      // Detailed balance: max |πᵢ Pᵢⱼ − πⱼ Pⱼᵢ| < tol · max(|πᵢ Pᵢⱼ|, 1).
      let maxDev = 0, maxAbs = 0;
      for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
        const f = pi[i]! * P.get(i, j);
        const g = pi[j]! * P.get(j, i);
        const d = Math.abs(f - g);
        if (d > maxDev) maxDev = d;
        if (Math.abs(f) > maxAbs) maxAbs = Math.abs(f);
      }
      isReversible = maxDev < tol * Math.max(maxAbs, 1);
    } catch (_e) {
      isReversible = null;
    }
  }

  const reach = reachability(adj);
  for (let i = 0; i < n; i++) reach[i]![i] = true; // R's `diag(reach) <- 1L`
  const H = hittingProbabilities(P, reach);
  const abs = absorptionAnalysis(P, transientIdx, absorbingIdx, labels);

  return {
    states: labels,
    classification,
    communicatingClasses: classes.map(cls => cls.map(i => labels[i]!)),
    recurrentClasses: recurrentClasses.map(cls => cls.map(i => labels[i]!)),
    transientClasses: transientClasses.map(cls => cls.map(i => labels[i]!)),
    absorbingStates: absorbingIdx.map(i => labels[i]!),
    period,
    isIrreducible, isAperiodic, isRegular, isReversible,
    hittingProbabilities: H,
    absorptionProbabilities: abs.probabilities,
    meanAbsorptionTime: abs.meanTime,
    P,
  };
}

/* ────────────────────────────────────────────────────────────────────
 * State distribution helper (port of R `state_distribution`)
 *
 * R's `state_distribution` is a thin alias for `colSums(weights) /
 * sum(weights)` on a transition-count or weight matrix — it returns the
 * column-marginal distribution of the matrix (which for a true count matrix
 * is the "destination" state frequency). Kept here for parity; the call
 * is cheap and the R signature is one line.
 * ──────────────────────────────────────────────────────────────────── */

export function stateDistribution(x: DiagnosticsInput): { state: string; proportion: number }[] {
  const { P, labels } = extractTransitionMatrix(x);
  const n = P.rows;
  let total = 0;
  const col = new Array<number>(n).fill(0);
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const v = P.get(i, j);
    col[j]! += v;
    total += v;
  }
  return labels.map((state, j) => ({
    state,
    proportion: total > 0 ? col[j]! / total : 0,
  }));
}
