/**
 * Centrality measures for TNA.
 * Port of Python tna/centralities.py
 *
 * Uses hand-rolled graph algorithms instead of graphology to match
 * the exact R TNA behavior (igraph with 1/weight distances).
 */
import { Matrix } from '../core/matrix.js';
import type { TNA, GroupTNA, CentralityMeasure, CentralityResult } from '../core/types.js';
import { isGroupTNA, groupEntries } from '../core/group.js';

export const AVAILABLE_MEASURES: CentralityMeasure[] = [
  'OutStrength', 'InStrength', 'ClosenessIn', 'ClosenessOut',
  'Closeness', 'Betweenness', 'BetweennessRSP', 'Diffusion', 'Clustering',
  'PageRank',
];

/**
 * Compute centrality measures for a TNA model.
 */
export function centralities(
  model: TNA | GroupTNA,
  options?: {
    loops?: boolean;
    normalize?: boolean;
    measures?: CentralityMeasure[];
  },
): CentralityResult {
  // Handle GroupTNA
  if (isGroupTNA(model)) {
    const allLabels: string[] = [];
    const allGroups: string[] = [];
    const allMeasures: Record<CentralityMeasure, number[]> = {} as Record<CentralityMeasure, number[]>;

    for (const [name, m] of groupEntries(model)) {
      const result = centralities(m, options);
      for (let i = 0; i < result.labels.length; i++) {
        allLabels.push(result.labels[i]!);
        allGroups.push(name);
      }
      for (const [measure, values] of Object.entries(result.measures) as [CentralityMeasure, Float64Array][]) {
        if (!allMeasures[measure]) allMeasures[measure] = [];
        for (let i = 0; i < values.length; i++) {
          allMeasures[measure]!.push(values[i]!);
        }
      }
    }

    const measures: Record<CentralityMeasure, Float64Array> = {} as Record<CentralityMeasure, Float64Array>;
    for (const [m, vals] of Object.entries(allMeasures) as [CentralityMeasure, number[]][]) {
      measures[m] = new Float64Array(vals);
    }

    return { labels: allLabels, measures, groups: allGroups };
  }

  const tnaModel = model as TNA;
  const requestedMeasures = options?.measures ?? [...AVAILABLE_MEASURES];
  const loops = options?.loops ?? false;
  const normalize = options?.normalize ?? false;

  const weights = tnaModel.weights.clone();
  const n = weights.rows;

  // Remove self-loops if not requested
  if (!loops) {
    for (let i = 0; i < n; i++) weights.set(i, i, 0);
  }

  // R tna always uses directed betweenness (igraph directed=TRUE), even for
  // symmetric matrices (co-occurrence/attention). Match that behavior.

  const measures: Record<string, Float64Array> = {};

  for (const measure of AVAILABLE_MEASURES) {
    if (!requestedMeasures.includes(measure)) continue;

    switch (measure) {
      case 'OutStrength':
        measures.OutStrength = outStrength(weights);
        break;
      case 'InStrength':
        measures.InStrength = inStrength(weights);
        break;
      case 'ClosenessIn':
        measures.ClosenessIn = closenessIn(weights, n);
        break;
      case 'ClosenessOut':
        measures.ClosenessOut = closenessOut(weights, n);
        break;
      case 'Closeness':
        measures.Closeness = closenessAll(weights, n);
        break;
      case 'Betweenness':
        measures.Betweenness = betweenness(weights, n);
        break;
      case 'BetweennessRSP':
        measures.BetweennessRSP = betweennessRSP(weights);
        break;
      case 'Diffusion':
        measures.Diffusion = diffusion(weights);
        break;
      case 'Clustering':
        measures.Clustering = clustering(weights);
        break;
      case 'PageRank':
        measures.PageRank = pageRank(weights);
        break;
    }
  }

  // Min-max normalisation — R's `ranger`: (x - min) / (max - min), with `na.rm = FALSE`.
  //
  // Two properties that a naive min-max loop gets wrong, both found by pinning against R:
  //
  //  1. NaN PROPAGATES. R's min/max with na.rm = FALSE return NaN if any element is NaN, so a
  //     single undefined cell (an absorbing state's ClosenessOut) makes the WHOLE normalized
  //     column NaN. A JS loop comparing with `<`/`>` silently skips NaN, which quietly rescales
  //     the remaining values against the wrong range.
  //
  //  2. A CONSTANT MEASURE HAS NO NORMALISATION. (x - m) / (m - m) is 0/0. R returns NaN when
  //     the values are exactly equal — but when they differ only by floating-point dust it
  //     divides by that dust and amplifies rounding error into a full 0..1 spread. Diffusion on
  //     a row-stochastic matrix with loops = TRUE is exactly this: mathematically constant (= n),
  //     observed spread ~5e-15, which R rescales by ~2e14 into a ranking of the states BY THEIR
  //     ROUNDING ERROR. We refuse to do that: a spread at noise level IS constant, so the answer
  //     is NaN. This is a deliberate divergence from R; see FINDINGS-equivalence.md (F3).
  if (normalize) {
    for (const key of Object.keys(measures)) {
      const vals = measures[key]!;
      let min = Infinity;
      let max = -Infinity;
      let anyNaN = false;
      for (let i = 0; i < vals.length; i++) {
        const v = vals[i]!;
        if (Number.isNaN(v)) { anyNaN = true; break; }
        if (v < min) min = v;
        if (v > max) max = v;
      }
      const spread = max - min;
      const scale = Math.max(Math.abs(min), Math.abs(max));
      const degenerate = !(spread > 1e-10 * Math.max(scale, 1e-300));
      if (anyNaN || degenerate) {
        vals.fill(NaN);
      } else {
        for (let i = 0; i < vals.length; i++) vals[i] = (vals[i]! - min) / spread;
      }
    }
  }

  return {
    labels: tnaModel.labels,
    measures: measures as Record<CentralityMeasure, Float64Array>,
  };
}

// ---- Strength ----

function outStrength(weights: Matrix): Float64Array {
  return weights.rowSums();
}

function inStrength(weights: Matrix): Float64Array {
  return weights.colSums();
}

// ---- Dijkstra shortest paths with 1/weight distances ----

/** Dijkstra from source, using 1/weight as distance. Returns distances to all nodes. */
function dijkstra(n: number, getWeight: (from: number, to: number) => number, source: number): Float64Array {
  const dist = new Float64Array(n).fill(Infinity);
  const visited = new Uint8Array(n);
  dist[source] = 0;

  for (let step = 0; step < n; step++) {
    // Find unvisited node with min distance
    let u = -1;
    let minDist = Infinity;
    for (let i = 0; i < n; i++) {
      if (!visited[i] && dist[i]! < minDist) {
        minDist = dist[i]!;
        u = i;
      }
    }
    if (u === -1) break;
    visited[u] = 1;

    for (let v = 0; v < n; v++) {
      if (visited[v]) continue;
      const w = getWeight(u, v);
      if (w > 0) {
        const d = 1 / w; // inverse weight as distance
        const newDist = dist[u]! + d;
        if (newDist < dist[v]!) {
          dist[v] = newDist;
        }
      }
    }
  }

  return dist;
}

// ---- Closeness ----

function closenessIn(weights: Matrix, n: number): Float64Array {
  const result = new Float64Array(n);

  for (let i = 0; i < n; i++) {
    // Reverse graph: paths TO node i
    const dist = dijkstra(n, (from, to) => weights.get(to, from), i);

    let totalDist = 0;
    for (let j = 0; j < n; j++) {
      if (j !== i && isFinite(dist[j]!)) totalDist += dist[j]!;
    }
    // Nothing reaches i (in-degree 0). Closeness is UNDEFINED, not zero — igraph returns
    // NaN. A 0 is a claim ("least central") that sorts the node to the bottom of the table
    // instead of out of it.
    result[i] = totalDist > 0 ? 1 / totalDist : NaN;
  }

  return result;
}

function closenessOut(weights: Matrix, n: number): Float64Array {
  const result = new Float64Array(n);

  for (let i = 0; i < n; i++) {
    const dist = dijkstra(n, (from, to) => weights.get(from, to), i);

    let totalDist = 0;
    for (let j = 0; j < n; j++) {
      if (j !== i && isFinite(dist[j]!)) totalDist += dist[j]!;
    }
    // i reaches nothing (an absorbing state). Undefined, as igraph — see closenessIn.
    result[i] = totalDist > 0 ? 1 / totalDist : NaN;
  }

  return result;
}

function closenessAll(weights: Matrix, n: number): Float64Array {
  // Mode="all" — undirected with max weight per edge pair
  const symWeights = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const w = Math.max(weights.get(i, j), weights.get(j, i));
      symWeights.set(i, j, w);
      symWeights.set(j, i, w);
    }
  }

  const result = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const dist = dijkstra(n, (from, to) => symWeights.get(from, to), i);

    let totalDist = 0;
    for (let j = 0; j < n; j++) {
      if (j !== i && isFinite(dist[j]!)) totalDist += dist[j]!;
    }
    // i is isolated in the symmetrized graph. Undefined, as igraph — see closenessIn.
    result[i] = totalDist > 0 ? 1 / totalDist : NaN;
  }

  return result;
}

// ---- Betweenness (Brandes' algorithm with 1/weight distances) ----

function betweenness(weights: Matrix, n: number): Float64Array {
  const CB = new Float64Array(n);

  for (let s = 0; s < n; s++) {
    // Modified Dijkstra (Brandes' algorithm with 1/weight distances)
    const stack: number[] = [];
    const pred: number[][] = Array.from({ length: n }, () => []);
    const sigma = new Float64Array(n);
    const dist = new Float64Array(n).fill(Infinity);

    sigma[s] = 1;
    dist[s] = 0;

    const visited = new Uint8Array(n);

    for (let step = 0; step < n; step++) {
      let u = -1;
      let minDist = Infinity;
      for (let i = 0; i < n; i++) {
        if (!visited[i] && dist[i]! < minDist) {
          minDist = dist[i]!;
          u = i;
        }
      }
      if (u === -1) break;
      visited[u] = 1;
      stack.push(u);

      for (let v = 0; v < n; v++) {
        if (visited[v]) continue;
        const w = weights.get(u, v);
        if (w <= 0) continue;
        const d = 1 / w;
        const newDist = dist[u]! + d;

        if (newDist < dist[v]! - 1e-15) {
          dist[v] = newDist;
          sigma[v] = sigma[u]!;
          pred[v] = [u];
        } else if (Math.abs(newDist - dist[v]!) < 1e-15) {
          sigma[v] = sigma[v]! + sigma[u]!;
          pred[v]!.push(u);
        }
      }
    }

    // Back-propagation
    const delta = new Float64Array(n);
    while (stack.length > 0) {
      const w = stack.pop()!;
      for (const v of pred[w]!) {
        const frac = (sigma[v]! / sigma[w]!) * (1 + delta[w]!);
        delta[v] = delta[v]! + frac;
      }
      if (w !== s) {
        CB[w] = CB[w]! + delta[w]!;
      }
    }
  }

  return CB;
}

// ---- LU decomposition solve (matches R's solve() / LAPACK dgesv) ----

/** Solve AX = I via LU decomposition with partial pivoting. Returns X = A^{-1}. */
function solveLU(A: Matrix, n: number): Matrix {
  // LU factorization in-place with row permutation
  const LU = new Float64Array(n * n);
  for (let i = 0; i < n * n; i++) LU[i] = A.data[i]!;
  const piv = new Int32Array(n);
  for (let i = 0; i < n; i++) piv[i] = i;

  for (let k = 0; k < n; k++) {
    // Find pivot
    let maxVal = Math.abs(LU[k * n + k]!);
    let maxRow = k;
    for (let i = k + 1; i < n; i++) {
      const v = Math.abs(LU[i * n + k]!);
      if (v > maxVal) { maxVal = v; maxRow = i; }
    }
    if (maxVal < 1e-15) throw new Error('Singular matrix in solveLU');

    // Swap rows
    if (maxRow !== k) {
      for (let j = 0; j < n; j++) {
        const tmp = LU[k * n + j]!;
        LU[k * n + j] = LU[maxRow * n + j]!;
        LU[maxRow * n + j] = tmp;
      }
      const tmp = piv[k]!; piv[k] = piv[maxRow]!; piv[maxRow] = tmp;
    }

    // Eliminate below
    for (let i = k + 1; i < n; i++) {
      const factor = LU[i * n + k]! / LU[k * n + k]!;
      LU[i * n + k] = factor; // store L factor
      for (let j = k + 1; j < n; j++) {
        LU[i * n + j] = LU[i * n + j]! - factor * LU[k * n + j]!;
      }
    }
  }

  // Solve AX = I column by column: for each e_col, solve LU x = P e_col
  const X = Matrix.zeros(n, n);
  for (let col = 0; col < n; col++) {
    // Apply permutation to RHS (column of identity)
    const b = new Float64Array(n);
    for (let i = 0; i < n; i++) b[i] = piv[i] === col ? 1 : 0;

    // Forward substitution (Ly = b, L has 1s on diagonal, factors below)
    for (let i = 1; i < n; i++) {
      for (let j = 0; j < i; j++) {
        b[i] = b[i]! - LU[i * n + j]! * b[j]!;
      }
    }

    // Back substitution (Ux = y)
    for (let i = n - 1; i >= 0; i--) {
      for (let j = i + 1; j < n; j++) {
        b[i] = b[i]! - LU[i * n + j]! * b[j]!;
      }
      b[i] = b[i]! / LU[i * n + i]!;
    }

    for (let i = 0; i < n; i++) X.set(i, col, b[i]!);
  }

  return X;
}

// ---- Randomized Shortest Path Betweenness (Kivimaki et al. 2016) ----

function betweennessRSP(weights: Matrix, beta = 0.01): Float64Array {
  const n = weights.rows;
  const mat = weights.clone();

  // D <- rowSums(mat)
  const D = mat.rowSums();

  // if (any(D == 0)) return NA
  for (let i = 0; i < n; i++) {
    if (D[i] === 0) return new Float64Array(n).fill(NaN);
  }

  // P_ref <- diag(D^-1) %*% mat
  const Pref = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      Pref.set(i, j, mat.get(i, j) / D[i]!);
    }
  }

  // C <- mat^-1; C[is.infinite(C)] <- 0
  const C = mat.map((v) => (v === 0 ? 0 : 1 / v));

  // W <- P_ref * exp(-beta * C)
  const W = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      W.set(i, j, Pref.get(i, j) * Math.exp(-beta * C.get(i, j)));
    }
  }

  // Z <- solve(I - W) using LU decomposition with partial pivoting
  // (matches R's solve() which calls LAPACK dgesv)
  const IminusW = Matrix.eye(n).sub(W);
  let Z: Matrix;
  try {
    Z = solveLU(IminusW, n);
  } catch {
    return new Float64Array(n).fill(NaN);
  }

  // Z_recip <- Z^-1; Z_recip[is.infinite(Z_recip)] <- 0
  //
  // THE TOLERANCE IS LOAD-BEARING. If a state is never entered (in-degree 0) its column of Z
  // is mathematically EXACTLY zero, and the term it contributes must vanish. R guards only
  // with `is.infinite`, which tests the reciprocal — so when LAPACK returns 1e-16 of rounding
  // dust instead of a clean 0, the reciprocal is 1e16: large, but FINITE, so the guard misses
  // it. The formula then evaluates Z * (1/Z) = 1 and adds a phantom unit of betweenness for
  // every dust cell. On our rare_state fixture that inflates R's answer from 59 to 91.
  //
  // Testing the magnitude of Z instead of the finiteness of 1/Z makes the result depend on the
  // mathematics rather than on the solver's rounding. See FINDINGS-equivalence.md (F2).
  const ZERO_TOL = 1e-12;
  const Zrecip = Z.map((v) => {
    if (Math.abs(v) <= ZERO_TOL) return 0;
    const inv = 1 / v;
    return isFinite(inv) ? inv : 0;
  });

  // Z_recip_diag <- diag(Z_recip) * I
  const ZrecipDiag = Matrix.diag(Zrecip.diag());

  // out <- diag(Z %*% (Z_recip - n * Z_recip_diag)^T %*% Z)
  // = diag(Z @ (Zrecip - n*ZrecipDiag).T @ Z)
  const inner = Zrecip.sub(ZrecipDiag.scale(n));
  const step1 = Z.matmul(inner.transpose());
  const step2 = step1.matmul(Z);

  const out = step2.diag();

  // Round
  for (let i = 0; i < n; i++) {
    out[i] = Math.round(out[i]!);
  }

  // out = out - min(out) + 1
  let minVal = Infinity;
  for (let i = 0; i < n; i++) {
    if (out[i]! < minVal) minVal = out[i]!;
  }
  for (let i = 0; i < n; i++) {
    out[i] = out[i]! - minVal + 1;
  }

  return out;
}

// ---- Diffusion centrality (Banerjee et al. 2014) ----

function diffusion(weights: Matrix): Float64Array {
  const n = weights.rows;
  let s = Matrix.zeros(n, n);
  let p = Matrix.eye(n);

  for (let i = 0; i < n; i++) {
    p = p.matmul(weights);
    s = s.add(p);
  }

  return s.rowSums();
}

// ---- Clustering coefficient (Zhang and Horvath 2005) ----

function clustering(weights: Matrix): Float64Array {
  // Symmetrize: mat = weights + weights.T
  const mat = weights.add(weights.transpose());

  // diag(mat) <- 0
  for (let i = 0; i < mat.rows; i++) mat.set(i, i, 0);

  const n = mat.rows;

  // num = diag(mat %*% mat %*% mat)
  const mat2 = mat.matmul(mat);
  const mat3 = mat2.matmul(mat);
  const num = mat3.diag();

  // den = colSums(mat)^2 - colSums(mat^2)
  const colSums = mat.colSums();
  const matSq = mat.map((v) => v * v);
  const colSumsSq = matSq.colSums();

  const result = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const den = colSums[i]! * colSums[i]! - colSumsSq[i]!;
    // den == 0 means the node has fewer than two neighbours: there is no triple it could
    // close, so the clustering coefficient does not exist. R computes 0/0 and gets NaN.
    result[i] = den !== 0 ? num[i]! / den : NaN;
  }

  return result;
}

// ---- PageRank (power iteration, port of psychaj) ----

function pageRank(weights: Matrix, damping = 0.85, maxIter = 100, tol = 1e-8): Float64Array {
  const n = weights.rows;
  const result = new Float64Array(n);
  if (n === 0) return result;

  // outDeg[i] = sum of outgoing weights from node i (excluding self-loops)
  const outDeg = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i !== j) outDeg[i]! += weights.get(i, j);
    }
  }

  let pr = new Float64Array(n).fill(1 / n);

  for (let iter = 0; iter < maxIter; iter++) {
    const newPr = new Float64Array(n).fill((1 - damping) / n);

    // Dangling node contribution
    let danglingSum = 0;
    for (let i = 0; i < n; i++) {
      if (outDeg[i]! <= 0) danglingSum += pr[i]!;
    }
    const danglingContrib = damping * danglingSum / n;
    for (let i = 0; i < n; i++) newPr[i]! += danglingContrib;

    // Standard PageRank contribution: j → i
    for (let j = 0; j < n; j++) {
      if (outDeg[j]! <= 0) continue;
      for (let i = 0; i < n; i++) {
        if (i === j) continue;
        const w = weights.get(j, i);
        if (w > 0) {
          newPr[i]! += damping * pr[j]! * w / outDeg[j]!;
        }
      }
    }

    // Check convergence
    let diff = 0;
    for (let i = 0; i < n; i++) diff += Math.abs(newPr[i]! - pr[i]!);
    pr = newPr;
    if (diff < tol) break;
  }

  for (let i = 0; i < n; i++) result[i] = pr[i]!;
  return result;
}

/**
 * Compute edge betweenness centrality and return as a new TNA model.
 */
export function betweennessNetwork(model: TNA | GroupTNA): TNA | Record<string, TNA> {
  if (isGroupTNA(model)) {
    const result: Record<string, TNA> = {};
    for (const [name, m] of groupEntries(model)) {
      result[name] = betweennessNetwork(m) as TNA;
    }
    return result;
  }

  const tnaModel = model as TNA;
  const weights = tnaModel.weights;
  const n = weights.rows;

  // Use Brandes' algorithm but collect edge betweenness
  const edgeBet = Matrix.zeros(n, n);

  for (let s = 0; s < n; s++) {
    const stack: number[] = [];
    const pred: number[][] = Array.from({ length: n }, () => []);
    const sigma = new Float64Array(n);
    const dist = new Float64Array(n).fill(Infinity);

    sigma[s] = 1;
    dist[s] = 0;

    const visited = new Uint8Array(n);

    for (let step = 0; step < n; step++) {
      let u = -1;
      let minDist = Infinity;
      for (let i = 0; i < n; i++) {
        if (!visited[i] && dist[i]! < minDist) {
          minDist = dist[i]!;
          u = i;
        }
      }
      if (u === -1) break;
      visited[u] = 1;
      stack.push(u);

      for (let v = 0; v < n; v++) {
        if (visited[v]) continue;
        const w = weights.get(u, v);
        if (w <= 0) continue;
        const d = 1 / w;
        const newDist = dist[u]! + d;

        if (newDist < dist[v]! - 1e-15) {
          dist[v] = newDist;
          sigma[v] = sigma[u]!;
          pred[v] = [u];
        } else if (Math.abs(newDist - dist[v]!) < 1e-15) {
          sigma[v] = sigma[v]! + sigma[u]!;
          pred[v]!.push(u);
        }
      }
    }

    const delta = new Float64Array(n);
    while (stack.length > 0) {
      const w = stack.pop()!;
      for (const v of pred[w]!) {
        const frac = (sigma[v]! / sigma[w]!) * (1 + delta[w]!);
        delta[v] = delta[v]! + frac;
        edgeBet.set(v, w, edgeBet.get(v, w) + sigma[v]! / sigma[w]! * (1 + delta[w]!));
      }
    }
  }

  return {
    weights: edgeBet,
    inits: new Float64Array(tnaModel.inits),
    labels: [...tnaModel.labels],
    data: tnaModel.data,
    type: 'betweenness',
    scaling: [...tnaModel.scaling],
  };
}
