/**
 * Directly-Follows Graph (DFG) — process map computation.
 *
 * Builds a process-mining-style DFG from a TNA model or its sequence data.
 * Three metric modes: absolute counts, relative proportions, case-based fractions.
 */
import type { TNA, GroupTNA, SequenceData } from '../core/types.js';
import { isGroupTNA, groupEntries } from '../core/group.js';

// ═══════════════════════════════════════════════════════════
//  Types
// ═══════════════════════════════════════════════════════════

/** Metric mode for process map labels. */
export type DFGMetric = 'absolute' | 'relative' | 'case';

/** A node in the directly-follows graph. */
export interface DFGNode {
  /** Activity/state label. */
  id: string;
  /** Node role: regular activity, synthetic start, or synthetic end. */
  type: 'activity' | 'start' | 'end';
  /** Total occurrences across all sequences. */
  absoluteFreq: number;
  /** absoluteFreq / sum of all absoluteFreqs. */
  relativeFreq: number;
  /** Fraction of sequences (cases) containing this state. */
  caseFreq: number;
}

/** A directed edge in the DFG. */
export interface DFGEdge {
  from: string;
  to: string;
  /** Raw directly-follows count. */
  absoluteCount: number;
  /** absoluteCount / sum of all edge counts. */
  relativeCount: number;
  /** Fraction of cases containing this directly-follows pair. */
  caseCount: number;
}

/** Complete DFG result. */
export interface DFGResult {
  nodes: DFGNode[];
  edges: DFGEdge[];
  /** Number of input sequences (cases). */
  totalSequences: number;
  /** Total directly-follows transitions counted. */
  totalTransitions: number;
}

/** Options for buildDFG. */
export interface DFGOptions {
  /** Label to identify the synthetic start state (if present in sequences). */
  startLabel?: string;
  /** Label to identify the synthetic end state (if present in sequences). */
  endLabel?: string;
}

// ═══════════════════════════════════════════════════════════
//  Implementation
// ═══════════════════════════════════════════════════════════

/**
 * Build a directly-follows graph from a TNA model.
 *
 * Uses `model.data` (the original sequences) when available for accurate
 * per-case metrics. Falls back to the weight matrix for transition counts
 * when sequences are not stored (e.g., matrix-input models).
 *
 * For GroupTNA, returns a record of per-group DFG results.
 */
export function buildDFG(
  model: TNA | GroupTNA,
  options?: DFGOptions,
): DFGResult | Record<string, DFGResult> {
  if (isGroupTNA(model)) {
    const result: Record<string, DFGResult> = {};
    for (const [name, m] of groupEntries(model)) {
      result[name] = buildDFG(m, options) as DFGResult;
    }
    return result;
  }

  const tna = model as TNA;
  const startLabel = options?.startLabel;
  const endLabel = options?.endLabel;

  // Prefer sequences for accurate case-based metrics
  if (tna.data && tna.data.length > 0) {
    return buildDFGFromSequences(tna.data, tna.labels, startLabel, endLabel);
  }
  return buildDFGFromMatrix(tna, startLabel, endLabel);
}

/**
 * Build a DFG directly from sequence data (without needing a TNA model).
 * Useful when you have raw sequences but haven't built a model yet.
 */
export function buildDFGFromSequences(
  sequences: SequenceData,
  labels?: string[],
  startLabel?: string,
  endLabel?: string,
): DFGResult {
  const totalSeq = sequences.length;

  // Count state occurrences and case presence
  const absFreq = new Map<string, number>();
  const casePresence = new Map<string, number>();
  for (const seq of sequences) {
    const seen = new Set<string>();
    for (const s of seq) {
      if (s === null) continue;
      absFreq.set(s, (absFreq.get(s) ?? 0) + 1);
      seen.add(s);
    }
    for (const s of seen) casePresence.set(s, (casePresence.get(s) ?? 0) + 1);
  }

  const totalOcc = [...absFreq.values()].reduce((a, b) => a + b, 0);

  // Count transitions
  const transMap = new Map<string, number>();
  const caseTrans = new Map<string, number>();
  let totalTrans = 0;
  for (const seq of sequences) {
    const seenT = new Set<string>();
    for (let i = 0; i < seq.length - 1; i++) {
      const from = seq[i], to = seq[i + 1];
      if (from === null || to === null) continue;
      const key = `${from}\x00${to}`;
      transMap.set(key, (transMap.get(key) ?? 0) + 1);
      totalTrans++;
      seenT.add(key);
    }
    for (const k of seenT) caseTrans.set(k, (caseTrans.get(k) ?? 0) + 1);
  }

  // Use provided labels or derive from data (sorted)
  const allLabels = labels ?? [...absFreq.keys()].sort();

  const nodes: DFGNode[] = allLabels
    .filter(id => absFreq.has(id))
    .map(id => ({
      id,
      type: id === startLabel ? 'start' : id === endLabel ? 'end' : 'activity',
      absoluteFreq: absFreq.get(id)!,
      relativeFreq: totalOcc > 0 ? absFreq.get(id)! / totalOcc : 0,
      caseFreq: totalSeq > 0 ? (casePresence.get(id) ?? 0) / totalSeq : 0,
    }));

  const edges: DFGEdge[] = [];
  for (const [key, count] of transMap) {
    const sep = key.indexOf('\x00');
    const from = key.slice(0, sep);
    const to = key.slice(sep + 1);
    edges.push({
      from,
      to,
      absoluteCount: count,
      relativeCount: totalTrans > 0 ? count / totalTrans : 0,
      caseCount: totalSeq > 0 ? (caseTrans.get(key) ?? 0) / totalSeq : 0,
    });
  }

  return { nodes, edges, totalSequences: totalSeq, totalTransitions: totalTrans };
}

/**
 * Build a DFG from the weight matrix when sequences are not available.
 * Case-based metrics cannot be computed and are set to 0.
 */
function buildDFGFromMatrix(
  tna: TNA,
  startLabel?: string,
  endLabel?: string,
): DFGResult {
  const n = tna.labels.length;
  const w = tna.weights;

  // For a frequency model, weights are counts; otherwise approximate
  const isFreq = tna.type === 'frequency';

  let totalWeight = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      totalWeight += w.get(i, j);
    }
  }

  // Node frequencies from row sums (out-flow)
  const rowSums = w.rowSums();
  const colSums = w.colSums();
  const totalNodeWeight = [...rowSums].reduce((a, b) => a + b, 0);

  const nodes: DFGNode[] = tna.labels.map((id, i) => ({
    id,
    type: id === startLabel ? 'start' : id === endLabel ? 'end' : 'activity',
    absoluteFreq: isFreq ? Math.round(rowSums[i]! + colSums[i]!) : rowSums[i]! + colSums[i]!,
    relativeFreq: totalNodeWeight > 0 ? (rowSums[i]! + colSums[i]!) / (2 * totalNodeWeight) : 0,
    caseFreq: 0, // Cannot compute without sequences
  }));

  const edges: DFGEdge[] = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const val = w.get(i, j);
      if (val > 0) {
        edges.push({
          from: tna.labels[i]!,
          to: tna.labels[j]!,
          absoluteCount: isFreq ? Math.round(val) : val,
          relativeCount: totalWeight > 0 ? val / totalWeight : 0,
          caseCount: 0, // Cannot compute without sequences
        });
      }
    }
  }

  return { nodes, edges, totalSequences: 0, totalTransitions: isFreq ? Math.round(totalWeight) : totalWeight };
}
