/**
 * HYPA — port of Nestimate::build_hypa (R/hypa.R, 0.5.1).
 *
 * Detects path anomalies in sequential data via a multi-hypergeometric
 * null model on the k-th order De Bruijn graph (LaRock et al. 2020).
 * For each edge (v, w) with observed weight f, computes:
 *   p_under = P(X <= f), p_over = P(X >= f)
 * where X ~ Hypergeometric(N, K, n) with
 *   N = round(sum(Xi)), K = round(Xi[v,w]), n = sum(adj),
 *   Xi[v,w] = out_strength[v] * in_strength[w].
 *
 * Anomalies are classified using BH-adjusted p-values against `alpha`.
 */
import { Matrix } from '../core/matrix.js';
import type { SequenceData, TNA } from '../core/types.js';
import { extractTrajectories, kgramCounts, logGamma } from './markov.js';
import { pAdjust, type PAdjustMethod } from '../stats/pAdjust.js';

const HON_SEP = '\x01';

export type HypaInput = string[][] | SequenceData | TNA;

export interface HypaOptions {
  k?: number;          // default 3
  alpha?: number;      // default 0.05
  minCount?: number;   // default 5
  pAdjustMethod?: PAdjustMethod | 'none'; // default "BH"
}

export interface HypaScoreRow {
  path: string;
  from: string;
  to: string;
  observed: number;
  expected: number;
  ratio: number;
  /** Alias for pUnder (matches R's `p_value` column). */
  pValue: number;
  pUnder: number;
  pOver: number;
  pAdjustedUnder: number;
  pAdjustedOver: number;
  anomaly: 'over' | 'under' | 'normal';
}

export interface HypaResult {
  scores: HypaScoreRow[];
  /** Adjacency matrix of the De Bruijn graph (rows = from, cols = to). */
  adjacency: Matrix;
  adjacencyLabels: string[];
  /** Propensity matrix Xi[i,j] = out_strength[i] * in_strength[j] for cells with edges. */
  xi: Matrix;
  k: number;
  alpha: number;
  pAdjust: PAdjustMethod | 'none';
  nAnomalous: number;
  nOver: number;
  nUnder: number;
  nEdges: number;
  nodes: string[];
  directed: true;
}

/* ── input parsing ─────────────────────────────────────────────────── */

function parseInput(data: HypaInput): string[][] {
  let raw: string[][];
  if (Array.isArray(data) && data.length > 0 && Array.isArray(data[0])) {
    raw = (data as (string | null)[][]).map(row => {
      const out: string[] = [];
      for (const v of row) if (v !== null && v !== undefined) out.push(v as string);
      return out;
    });
  } else {
    raw = extractTrajectories(data as TNA | SequenceData);
  }
  return raw.filter(t => t.length >= 2);
}

/* ── hypergeometric CDF (matches R's phyper) ──────────────────────── */

/** log P(X = k) for X ~ Hypergeometric(N, K, n). */
function logHyperPmf(k: number, K: number, N: number, n: number): number {
  // Support: max(0, n + K - N) <= k <= min(K, n)
  if (k < 0 || k > K || k > n || n - k > N - K) return -Infinity;
  return logGamma(K + 1) - logGamma(k + 1) - logGamma(K - k + 1)
       + logGamma(N - K + 1) - logGamma(n - k + 1) - logGamma(N - K - n + k + 1)
       - logGamma(N + 1) + logGamma(n + 1) + logGamma(N - n + 1);
}

/** P(X <= x) for X ~ Hypergeometric(N, K, n).
 *  Matches R's phyper(x, K, N - K, n, lower.tail = TRUE). */
function phyperLower(x: number, K: number, N: number, n: number): number {
  const xMax = Math.min(K, n);
  const xMin = Math.max(0, n + K - N);
  if (x < xMin) return 0;
  if (x >= xMax) return 1;
  // Walk from xMin upwards, accumulating PMF via the ratio recurrence
  // P(X=k+1)/P(X=k) = (K - k)(n - k) / ((k + 1)(N - K - n + k + 1)).
  let logCurr = logHyperPmf(xMin, K, N, n);
  let cdf = Math.exp(logCurr);
  for (let k = xMin; k < x; k++) {
    const num = (K - k) * (n - k);
    const denom = (k + 1) * (N - K - n + k + 1);
    if (num <= 0 || denom <= 0) break;
    logCurr += Math.log(num) - Math.log(denom);
    cdf += Math.exp(logCurr);
  }
  return Math.min(1, Math.max(0, cdf));
}

/** P(X >= x) for X ~ Hypergeometric(N, K, n). Inclusive upper tail.
 *  Matches R's phyper(x - 1, K, N - K, n, lower.tail = FALSE). */
function phyperUpperInclusive(x: number, K: number, N: number, n: number): number {
  const xMin = Math.max(0, n + K - N);
  if (x <= xMin) return 1;
  const xMax = Math.min(K, n);
  if (x > xMax) return 0;
  return Math.min(1, Math.max(0, 1 - phyperLower(x - 1, K, N, n)));
}

/* ── main ──────────────────────────────────────────────────────────── */

export function buildHypa(data: HypaInput, options: HypaOptions = {}): HypaResult {
  const { k = 3, alpha = 0.05, minCount = 5, pAdjustMethod = 'BH' } = options;
  if (!(k >= 1)) throw new Error("'k' must be >= 1");
  if (!(alpha > 0 && alpha < 0.5)) throw new Error("'alpha' must be in (0, 0.5)");
  if (!(minCount >= 1)) throw new Error("'minCount' must be >= 1");

  const trajectories = parseInput(data);
  if (trajectories.length === 0) {
    throw new Error('No valid trajectories (each must have at least 2 states)');
  }

  // Build k-th order De Bruijn graph from k+1-grams (matches R's choice
  // — kgramCounts(k) returns k-tuples and edges between consecutive
  // overlapping k-tuples; for HYPA at order k the graph is exactly that).
  const kg = kgramCounts(trajectories, k);
  if (kg.edges.length === 0) {
    throw new Error(`No edges at order ${k} (paths too short or too few)`);
  }

  // Adjacency (raw weights, NOT normalized)
  const nodes = kg.nodes;
  const n = nodes.length;
  const idx = new Map<string, number>();
  for (let i = 0; i < n; i++) idx.set(nodes[i]!, i);
  const adj = new Matrix(n, n);
  for (const e of kg.edges) {
    const r = idx.get(e.from);
    const c = idx.get(e.to);
    if (r !== undefined && c !== undefined) adj.set(r, c, e.weight);
  }

  // Out / in strengths and Xi
  const outStrength = new Float64Array(n);
  const inStrength = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    let outS = 0, inS = 0;
    for (let j = 0; j < n; j++) {
      outS += adj.get(i, j);
      inS += adj.get(j, i);
    }
    outStrength[i] = outS;
    inStrength[i] = inS;
  }
  const xi = new Matrix(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (adj.get(i, j) > 0) xi.set(i, j, outStrength[i]! * inStrength[j]!);
    }
  }

  // Total pool sizes
  let xiSum = 0;
  let nDraws = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      xiSum += xi.get(i, j);
      nDraws += adj.get(i, j);
    }
  }
  const N = Math.round(xiSum);
  // R clamps n_draws to <= N to keep parameters valid.
  const nClamp = Math.min(nDraws, N);

  interface RawScore {
    iIdx: number;
    jIdx: number;
    path: string;
    from: string;
    to: string;
    observed: number;
    expected: number;
    ratio: number;
    pUnder: number;
    pOver: number;
  }
  const raw: RawScore[] = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const fObs = adj.get(i, j);
      if (fObs <= 0) continue;
      let K = Math.round(xi.get(i, j));
      K = Math.max(0, Math.min(K, N));
      const fromParts = nodes[i]!.split(HON_SEP);
      const toParts = nodes[j]!.split(HON_SEP);
      const nextState = toParts[toParts.length - 1]!;
      const path = [...fromParts, nextState].join(' -> ');
      const fromArrow = fromParts.join(' -> ');
      const expected = N > 0 ? (nDraws * K) / N : 0;
      const ratio = expected > 0 ? fObs / expected : Infinity;
      const pUnder = phyperLower(fObs, K, N, nClamp);
      const pOver = phyperUpperInclusive(fObs, K, N, nClamp);
      raw.push({
        iIdx: i, jIdx: j,
        path, from: fromArrow, to: nextState,
        observed: fObs, expected, ratio,
        pUnder, pOver,
      });
    }
  }

  // Adjust p-values (BH default)
  const method: PAdjustMethod | 'none' = pAdjustMethod;
  const pUnderRaw = raw.map(r => r.pUnder);
  const pOverRaw = raw.map(r => r.pOver);
  const pAdjUnder = method === 'none' ? pUnderRaw : pAdjust(pUnderRaw, method);
  const pAdjOver = method === 'none' ? pOverRaw : pAdjust(pOverRaw, method);

  // Build initial score rows with anomaly classification
  const scores: HypaScoreRow[] = raw.map((r, i) => {
    let anomaly: 'over' | 'under' | 'normal' = 'normal';
    if (r.observed >= minCount) {
      if (pAdjUnder[i]! < alpha) anomaly = 'under';
      else if (pAdjOver[i]! < alpha) anomaly = 'over';
    }
    return {
      path: r.path, from: r.from, to: r.to,
      observed: r.observed, expected: r.expected, ratio: r.ratio,
      pValue: r.pUnder,
      pUnder: r.pUnder, pOver: r.pOver,
      pAdjustedUnder: pAdjUnder[i]!, pAdjustedOver: pAdjOver[i]!,
      anomaly,
    };
  });

  // Sort: over (by ratio desc), under (by ratio asc), normal (in original order).
  const over = scores.filter(s => s.anomaly === 'over').sort((a, b) => b.ratio - a.ratio);
  const under = scores.filter(s => s.anomaly === 'under').sort((a, b) => a.ratio - b.ratio);
  const normal = scores.filter(s => s.anomaly === 'normal');
  const sorted = [...over, ...under, ...normal];

  return {
    scores: sorted,
    adjacency: adj,
    adjacencyLabels: nodes,
    xi,
    k,
    alpha,
    pAdjust: method,
    nAnomalous: over.length + under.length,
    nOver: over.length,
    nUnder: under.length,
    nEdges: scores.length,
    nodes,
    directed: true,
  };
}
