/**
 * clusterCovariates — do the clusters differ on the metadata, and who ends up where?
 *
 * The engine-side counterpart of `Nestimate::build_clusters(covariates = ~ Age + Gender)`,
 * which resolves covariate names against the metadata and fits `nnet::multinom` of cluster
 * membership on them. Two questions, deliberately answered separately because they are not
 * the same question:
 *
 *   PROFILE   — one test per covariate, marginally. Numeric → ANOVA (F, eta^2) + Kruskal–
 *               Wallis. Categorical → chi-square + Cramér's V + per-cell standardized
 *               residuals. Plus pairwise post-hoc, so a significant omnibus names the
 *               clusters that actually differ. This is what a reader wants first: it says
 *               WHICH covariates the clusters differ on, one at a time.
 *
 *   MEMBERSHIP— one multinomial logit of cluster membership on ALL covariates at once, so
 *               each is adjusted for the others. A covariate that only looks significant
 *               because it proxies another shows up here and nowhere in the profile.
 *
 * THE TWO-STEP, said once and meant. Both run on the HARD assignment, so a sequence with
 * posterior (0.51, 0.49) counts as a certain member: classification uncertainty is discarded
 * and the p-values are optimistic. That is what Nestimate does and what everyone reports, and
 * it is still the two-step. It DESCRIBES the clusters you got. To claim a covariate PREDICTS
 * membership, put it in the model — `mmm({ covariates })` fits the logit inside the EM, keeps
 * the responsibilities soft, and gets standard errors (Louis) that carry the uncertainty.
 */
import type { MetaData } from '../core/prepare-long.js';
import { designMatrix } from '../core/prepare-long.js';
import { anova, kruskal, chisqTest, pairwiseWelch, pairwiseChisq } from '../stats/group-tests.js';
import type { AnovaResult, KruskalResult, ChisqResult, WelchPair, ChisqPair } from '../stats/group-tests.js';
import { pAdjust, type PAdjustMethod } from '../stats/pAdjust.js';
import { fitMultinom, multinomSE } from './multinom.js';

export interface CovariateProfileRow {
  covariate: string;
  kind: 'numeric' | 'categorical' | 'skipped';
  /** Why it was not tested (constant, all-missing, one level, …). */
  reason?: string;
  /** Per-cluster descriptives — mean/sd for numeric, counts per level for categorical. */
  byCluster?: { cluster: string; n: number; mean?: number; sd?: number; counts?: number[] }[];
  levels?: string[];
  anova?: AnovaResult;
  kruskal?: KruskalResult;
  chisq?: ChisqResult;
  postHocNumeric?: WelchPair[];
  postHocCategorical?: ChisqPair[];
}

export interface MembershipModel {
  terms: string[];
  refCluster: string;
  clusters: string[];
  coefficients: number[][];
  se: number[][];
  z: number[][];
  pValues: number[][];
  oddsRatios: number[][];
  ciLower: number[][];
  ciUpper: number[][];
  /** The dropped reference level of every factor term. */
  reference: Record<string, string>;
  /** Sessions dropped for a missing covariate value — never imputed to 0. */
  dropped: number;
  /** False when the standard errors are not USABLE — not merely when a matrix failed to invert.
   *  A separated fit inverts fine and returns an SE of 194,000; that is not a standard error,
   *  it is the MLE sitting on the boundary. When this is false the coefficients, p-values, ORs
   *  and CIs in this object are all meaningless and must not be reported. */
  seOk: boolean;
  /** True when the fit fell back to Firth's penalised likelihood — either because a cluster ×
   *  level cell was empty, or because the unpenalised fit turned out to be (quasi-)separated
   *  (a continuous covariate that orders the clusters too well, or a tiny cluster, neither of
   *  which leaves an empty cell). Nestimate does the same (`estimator = "auto"`). */
  firth: boolean;
}

export interface ClusterCovariatesResult {
  clusters: string[];
  profile: CovariateProfileRow[];
  membership?: MembershipModel;
}

export interface ClusterCovariatesOptions {
  /** Metadata column names to use. Default: every column except `.session_id`/`.session_nr`. */
  terms?: string[];
  /** Multiplicity adjustment for the pairwise post-hoc. Default 'holm'. */
  adjust?: PAdjustMethod;
  /** Also fit the multivariate membership logit. Default true. */
  membership?: boolean;
  /** Reference cluster for the logit, by NAME. Default: the first cluster. */
  refCluster?: string;
  /** Confidence level for the coefficient CIs. Default 0.05 (95%), as R `mmm_stats`. */
  level?: number;
  /** Cluster labels, in assignment order. Default 'Cluster 1'..'Cluster k'. */
  clusterNames?: string[];
}

const Z = (level: number): number => {
  // Inverse standard normal at 1 - level/2 (Acklam). Only ever called with a handful of
  // conventional levels, so precision matters more than speed.
  const p = 1 - level / 2;
  const a = [-39.69683028665376, 220.9460984245205, -275.9285104469687, 138.3577518672690, -30.66479806614716, 2.506628277459239];
  const b = [-54.47609879822406, 161.5858368580409, -155.6989798598866, 66.80131188771972, -13.28068155288572];
  const c = [-0.007784894002430293, -0.3223964580411365, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [0.007784695709041462, 0.3224671290700398, 2.445134137142996, 3.754408661907416];
  const pl = 0.02425;
  let q: number, r: number;
  if (p < pl) {
    q = Math.sqrt(-2 * Math.log(p));
    return (((((c[0]! * q + c[1]!) * q + c[2]!) * q + c[3]!) * q + c[4]!) * q + c[5]!) / ((((d[0]! * q + d[1]!) * q + d[2]!) * q + d[3]!) * q + 1);
  }
  if (p <= 1 - pl) {
    q = p - 0.5; r = q * q;
    return (((((a[0]! * r + a[1]!) * r + a[2]!) * r + a[3]!) * r + a[4]!) * r + a[5]!) * q /
           (((((b[0]! * r + b[1]!) * r + b[2]!) * r + b[3]!) * r + b[4]!) * r + 1);
  }
  q = Math.sqrt(-2 * Math.log(1 - p));
  return -(((((c[0]! * q + c[1]!) * q + c[2]!) * q + c[3]!) * q + c[4]!) * q + c[5]!) / ((((d[0]! * q + d[1]!) * q + d[2]!) * q + d[3]!) * q + 1);
};

function normalCdf(x: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const dd = 0.3989422804014327 * Math.exp(-x * x / 2);
  const pr = dd * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  return x > 0 ? 1 - pr : pr;
}

/**
 * @param assignments 1-indexed cluster of each session, index-aligned with `meta.rows`.
 */
export function clusterCovariates(
  assignments: readonly number[],
  meta: MetaData,
  options?: ClusterCovariatesOptions,
): ClusterCovariatesResult {
  if (assignments.length !== meta.rows.length) {
    throw new Error(`clusterCovariates: ${assignments.length} assignments but ${meta.rows.length} metadata rows`);
  }
  const k = Math.max(...assignments);
  const clusters = options?.clusterNames ?? Array.from({ length: k }, (_, i) => 'Cluster ' + (i + 1));
  const adjust = options?.adjust ?? 'holm';
  const level = options?.level ?? 0.05;

  const skip = new Set(['.session_id', '.session_nr']);
  const terms = options?.terms ?? meta.columns.filter((c) => !skip.has(c));

  const padj = (ps: number[], m: string) => Array.from(pAdjust(ps, m as PAdjustMethod));

  // ── the PROFILE: one covariate at a time ─────────────────────────────────
  const profile: CovariateProfileRow[] = terms.map((term) => {
    const ci = meta.columns.indexOf(term);
    if (ci < 0) return { covariate: term, kind: 'skipped', reason: 'no such metadata column' };

    const perCluster: (string | number | null)[][] = clusters.map(() => []);
    assignments.forEach((a, i) => {
      const v = meta.rows[i]![ci]!;
      if (v != null && v !== '') perCluster[a - 1]!.push(v);
    });
    if (perCluster.some((g) => g.length === 0)) {
      return { covariate: term, kind: 'skipped', reason: 'a cluster has no values for it' };
    }

    if (meta.types[ci] === 'numeric') {
      const groups = perCluster.map((g) => g.map(Number));
      const a = anova(groups);
      if (!a) return { covariate: term, kind: 'skipped', reason: 'too few observations' };
      const byCluster = groups.map((g, i) => {
        const m = g.reduce((s, v) => s + v, 0) / g.length;
        const sd = Math.sqrt(g.reduce((s, v) => s + (v - m) * (v - m), 0) / Math.max(1, g.length - 1));
        return { cluster: clusters[i]!, n: g.length, mean: m, sd };
      });
      return {
        covariate: term, kind: 'numeric', byCluster,
        anova: a, kruskal: kruskal(groups) ?? undefined,
        postHocNumeric: pairwiseWelch(clusters, groups, adjust, padj),
      };
    }

    const levels = Array.from(new Set(perCluster.flat().map(String))).sort();
    if (levels.length < 2) return { covariate: term, kind: 'skipped', reason: 'only one level — a constant, not a covariate' };
    const table = perCluster.map((g) => levels.map((L) => g.filter((v) => String(v) === L).length));
    const cs = chisqTest(table);
    if (!cs) return { covariate: term, kind: 'skipped', reason: 'degenerate contingency table' };
    return {
      covariate: term, kind: 'categorical', levels,
      byCluster: table.map((row, i) => ({ cluster: clusters[i]!, n: row.reduce((s, v) => s + v, 0), counts: row })),
      chisq: cs,
      postHocCategorical: pairwiseChisq(clusters, table, adjust, padj),
    };
  });

  // ── the MEMBERSHIP LOGIT: all covariates at once ─────────────────────────
  let membership: MembershipModel | undefined;
  const usable = profile.filter((p) => p.kind !== 'skipped').map((p) => p.covariate);
  if ((options?.membership ?? true) && usable.length > 0 && k >= 2) {
    const dm = designMatrix(meta, usable);
    const dropped = new Set(dm.dropped);
    const X: number[][] = [];
    const R: number[][] = [];
    assignments.forEach((a, i) => {
      if (dropped.has(i)) return;                        // no value → NOT imputed to 0
      X.push([1, ...dm.X[X.length]!]);
      const r = new Array<number>(k).fill(0);
      r[a - 1] = 1;                                      // the HARD label: the two-step
      R.push(r);
    });

    const refName = options?.refCluster ?? clusters[0]!;
    const refIdx = Math.max(0, clusters.indexOf(refName));

    // FIRTH when the likelihood has no finite maximum. With (quasi-)separation the MLE runs to
    // the boundary: the coefficient grows without bound and its standard error explodes.
    // Nestimate's `estimator = "auto"` switches to Firth's penalised likelihood exactly here,
    // and so do we — the penalty is a Jeffreys prior, which keeps the estimate finite and the
    // direction honest.
    //
    // DETECTING IT TAKES TWO CHECKS, NOT ONE. An empty cluster x level cell is only the visible
    // half. Separation also arises from a CONTINUOUS covariate that orders the clusters too
    // well, or simply from a tiny cluster — neither leaves an empty cell, so a cell-counting
    // heuristic sails straight past them. On the corpus that produced a coefficient of -54 with
    // a standard error of 194,000, reported as a clean fit.
    //
    // The scale-free signal is the STANDARD ERROR, not the coefficient. A large coefficient is
    // not itself suspicious — with an uncentred predictor a legitimate intercept is easily -38 —
    // but an SE in the thousands means the information matrix is numerically singular and the
    // estimate is sitting on the boundary. `ok` alone does not catch it: the matrix does invert,
    // just terribly.
    const SEPARATION_SE = 1e3;
    const absurd = (s: number[][]): boolean =>
      !s.every((row) => row.every((v) => Number.isFinite(v) && Math.abs(v) < SEPARATION_SE));

    const thin = profile.some((p) => p.kind === 'categorical' && p.byCluster!.some((b) => b.counts!.some((c) => c === 0)));
    let firth = thin;
    let fit = fitMultinom(X, R, refIdx, undefined, firth ? { firth: true } : undefined);
    let { se, ok } = multinomSE(X, R, fit.priors, refIdx);

    if (!firth && (!ok || absurd(se))) {
      firth = true;
      fit = fitMultinom(X, R, refIdx, undefined, { firth: true });
      ({ se, ok } = multinomSE(X, R, fit.priors, refIdx));
    }
    // Still degenerate after penalisation: say so. `seOk` must mean "these standard errors are
    // usable", not merely "a matrix inverted".
    const seUsable = ok && !absurd(se);

    const zc = Z(level);
    const nonRef = clusters.filter((_, i) => i !== refIdx);
    const coefficients = fit.beta.map((r) => r.slice());
    const zStat = coefficients.map((row, m) => row.map((b, j) => b / se[m]![j]!));
    membership = {
      terms: ['(Intercept)', ...dm.names],
      refCluster: clusters[refIdx]!,
      clusters: nonRef,
      coefficients,
      se,
      z: zStat,
      pValues: zStat.map((row) => row.map((v) => (Number.isFinite(v) ? 2 * (1 - normalCdf(Math.abs(v))) : NaN))),
      oddsRatios: coefficients.map((row) => row.map((b) => Math.exp(b))),
      ciLower: coefficients.map((row, m) => row.map((b, j) => b - zc * se[m]![j]!)),
      ciUpper: coefficients.map((row, m) => row.map((b, j) => b + zc * se[m]![j]!)),
      reference: dm.reference,
      dropped: dm.dropped.length,
      seOk: seUsable,
      firth,
    };
  }

  return { clusters, profile, membership };
}
